        ('user_daily_tasks','finalized_at','timestamp with time zone',false,false),
        ('user_daily_tasks','policy_id','bigint',false,false),
        ('user_daily_tasks','tests_per_active_app','integer',false,false),
        ('user_daily_tasks','carryover_version','integer',false,false),
        ('user_daily_tasks','base_required_tests','integer',true,false),
        ('user_daily_tasks','carry_in_tests','integer',true,false),
        ('user_daily_tasks','carry_out_tests','integer',true,false),
        ('user_daily_tasks','carry_source_date','date',false,false),
        ('user_daily_tasks','carryover_effective_from','date',false,false),
        ('user_quest_claims','id','uuid',true,false),
        ('user_quest_claims','user_id','uuid',true,false),
        ('user_quest_claims','quest_type','text',true,false),
        ('user_quest_claims','milestone','integer',true,false),
        ('user_quest_claims','reward_credits','integer',true,false),
        ('user_quest_claims','period_key','date',true,false),
        ('user_quest_claims','claimed_at','timestamp with time zone',true,false),
        ('user_slots','id','uuid',true,false),
        ('user_slots','user_id','uuid',true,false),
        ('user_slots','slot_number','integer',true,false),
        ('user_slots','unlocked_at','timestamp with time zone',true,false),
        ('user_slots','expires_at','timestamp with time zone',true,false),
        ('user_slots','created_at','timestamp with time zone',true,false),
        ('user_warnings','id','uuid',true,false),
        ('user_warnings','user_id','uuid',true,false),
        ('user_warnings','warning_type','text',true,false),
        ('user_warnings','message','text',true,false),
        ('user_warnings','warning_date','date',true,false),
        ('user_warnings','created_at','timestamp with time zone',true,false),
        ('user_warnings','acknowledged','boolean',true,false),
        ('user_warnings','metadata','jsonb',false,false)
        ) e(table_name,column_name,expected_type,expected_not_null,optional_column)
        left join pg_namespace n on n.nspname='public'
        left join pg_class c on c.relnamespace=n.oid and c.relname=e.table_name and c.relkind='r'
        left join pg_attribute a on a.attrelid=c.oid and a.attname=e.column_name and a.attnum>0 and not a.attisdropped
        where (a.attname is null and not e.optional_column)
            or (a.attname is not null and (format_type(a.atttypid,a.atttypmod)<>e.expected_type
                or a.attnotnull<>e.expected_not_null));
        if v_missing is not null then
            raise exception 'BASELINE_062_SCHEMA_NOT_READY: %', v_missing
                using hint='File nay danh cho database da ap dung 001-061 (cho phep thieu 046), hoac database moi. Khong chay lai cac file archive tren database dang dung.';
        end if;
        if not exists(select 1 from public.daily_task_policies where effective_from=date '-infinity') then
            raise exception 'BASELINE_062_DAILY_TASK_POLICY_BASELINE_MISSING';
        end if;
    elsif exists(select 1 from pg_class where relnamespace='public'::regnamespace and relname in('app_configs','app_update_claims','app_update_controls','app_update_financial_events','app_update_operations','app_update_releases','campaign_archive','campaign_members','campaign_push_receipts','campaigns','checkins','cleanup_runs','contact_reports','credit_logs','daily_task_carryover_policies','daily_task_carryover_policy_audit','daily_task_policies','daily_task_policy_changes','feedbacks','home_stats_policies','home_stats_policy_audits','mission_participants','mission_reconciliation_events','mission_settlement_jobs','missions','notifications','profiles','report_review_events','report_submission_receipts','tester_reports','topup_orders','topup_packages','user_daily_tasks','user_quest_claims','user_slots','user_warnings')) then
        raise exception 'BASELINE_062_PARTIAL_SCHEMA'
            using hint='Phat hien schema dang do dang. Giao dich da huy, chua thay doi du lieu.';
    end if;
end;
$preflight$;

-- Extensions: không thay secret hoặc cấu hình Media Gateway.
create extension if not exists pgcrypto with schema public;
create extension if not exists "uuid-ossp" with schema public;

-- Sequences: chỉ tạo khi thiếu, không reset bộ đếm đang dùng.
create sequence if not exists public."campaign_push_order_seq" as bigint increment by 1 minvalue 1 maxvalue 9223372036854775807 start with 1 cache 1 no cycle;
create sequence if not exists public."home_stats_policies_id_seq" as bigint increment by 1 minvalue 1 maxvalue 9223372036854775807 start with 1 cache 1 no cycle;
create sequence if not exists public."home_stats_policy_audits_id_seq" as bigint increment by 1 minvalue 1 maxvalue 9223372036854775807 start with 1 cache 1 no cycle;

