alter table public.tester_reports add column if not exists media_expired boolean not null default false;

-- Ownership của serial sequences; không đổi last_value.
alter sequence public."home_stats_policies_id_seq" owned by public."home_stats_policies"."id";
alter sequence public."home_stats_policy_audits_id_seq" owned by public."home_stats_policy_audits"."id";

-- Mỗi chữ ký hàm chỉ giữ một định nghĩa cuối; bao gồm đủ 046 và 061.
CREATE OR REPLACE FUNCTION public._apply_daily_inactivity_penalty(p_eval date)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_today date := (now() at time zone 'Asia/Ho_Chi_Minh')::date;
    v_policy public.daily_task_policies;
    v_carry_policy public.daily_task_carryover_policies;
    v_is_carryover_active boolean := false;
    v_effective_from date := null;
    r record;
    v_status jsonb;
    v_ready boolean;
    v_met boolean;
    v_mode text;
    v_required int;
    v_effective int;
    v_completed int;
    v_logged_in boolean;
    v_exempt boolean;
    v_prev_streak int;
    v_new_streak int;
    v_pct numeric;
    v_ratio numeric;
    v_deduction int;
    v_new_balance int;
    v_rows int;
    v_note text;
    v_base_req int;
    v_carry_in int;
    v_carry_out int;
    v_source_date date;
begin
    if p_eval is null then
        return;
    end if;

    -- Giới hạn không chốt ngày hôm nay hoặc tương lai (trừ cờ test)
    if p_eval >= v_today and current_setting('test.allow_future_finalize', true) is distinct from 'true' then
        return;
    end if;

    -- Chống chạy song song giữa nhiều phiên / cron retry
    perform pg_advisory_xact_lock(hashtextextended('daily_inactivity_penalty', 0));

    v_policy := public.get_daily_task_policy(p_eval);
    v_carry_policy := public.get_daily_task_carryover_policy(p_eval);
    v_is_carryover_active := (v_carry_policy is not null and v_carry_policy.is_enabled and p_eval >= v_carry_policy.effective_from);
    v_effective_from := case when v_is_carryover_active then v_carry_policy.effective_from else null end;

    -- Khóa tuần tự từng profile
    for r in
        select p.id, p.credits, p.daily_missed_streak, lower(p.role) as role, p.created_at
        from public.profiles p
        where p.created_at < ((p_eval + 1)::timestamp at time zone 'Asia/Ho_Chi_Minh')
        for update of p
    loop
        -- 1. R10: Tài khoản đăng ký trong chính ngày p_eval: miễn cho ngày đăng ký, tạo checkpoint
        if r.created_at >= (p_eval::timestamp at time zone 'Asia/Ho_Chi_Minh') then
            insert into public.user_daily_tasks as t (
                user_id, task_date, mode, active_app_count, required_tests,
                effective_required_tests, available_apps, completed_tests,
                logged_in, is_exempt, met, missed_streak, penalty_credits, finalized_at,
                policy_id, tests_per_active_app,
                carryover_version, base_required_tests, carry_in_tests, carry_out_tests,
                carry_source_date, carryover_effective_from
            ) values (
                r.id, p_eval, 'member',
                0, 0, 0, 0, 0,
                true, true, true, 0, 0, now(),
                v_policy.id, v_policy.tests_per_active_app,
                case when v_is_carryover_active then 1 else null end,
                0, 0, 0, null, v_effective_from
            )
            on conflict (user_id, task_date) do update
            set mode = 'member',
                active_app_count = 0,
                required_tests = 0,
                effective_required_tests = 0,
                available_apps = 0,
                completed_tests = 0,
                logged_in = true,
                is_exempt = true,
                met = true,
                missed_streak = 0,
                penalty_credits = 0,
                finalized_at = now(),
                policy_id = excluded.policy_id,
                tests_per_active_app = excluded.tests_per_active_app,
                carryover_version = case when v_is_carryover_active then 1 else null end,
                base_required_tests = 0,
                carry_in_tests = 0,
                carry_out_tests = 0,
                carry_source_date = null,
                carryover_effective_from = v_effective_from
            where t.finalized_at is null;

            continue;
        end if;

        -- 2. Đã finalized trước đó -> bỏ qua (idempotent, không trừ Credit lần hai)
        if exists (
            select 1
            from public.user_daily_tasks t
            where t.user_id = r.id
              and t.task_date = p_eval
              and t.finalized_at is not null
        ) then
            continue;
        end if;

        v_status := public.get_daily_task_status(r.id, p_eval);
        if v_status is null then
            continue;
        end if;

        v_ready := coalesce((v_status ->> 'carryover_ready')::boolean, true);

        -- R01: Finalizer từ chối/hoãn riêng user-day thiếu nguồn chuyển tiếp
        -- Không finalized, không phạt, không ghi carry_out = 0 khi carryover_ready = false
        if v_is_carryover_active and not v_ready then
            continue;
        end if;

        v_met := coalesce((v_status ->> 'met')::boolean, false);
        v_mode := coalesce(v_status ->> 'mode', 'member');
        v_required := coalesce((v_status ->> 'required_tests')::int, 0);
        v_effective := coalesce((v_status ->> 'effective_required_tests')::int, 0);
        v_completed := coalesce((v_status ->> 'completed_tests')::int, 0);
        v_logged_in := coalesce((v_status ->> 'logged_in_today')::boolean, false);
        v_exempt := coalesce((v_status ->> 'is_penalty_exempt')::boolean, false);
        v_base_req := coalesce((v_status ->> 'base_required_tests')::int, 0);
        v_carry_in := coalesce((v_status ->> 'carry_in_tests')::int, 0);
        v_carry_out := coalesce((v_status ->> 'carryover_remaining_tests')::int, 0);
        v_source_date := case when v_is_carryover_active and p_eval > v_effective_from then (p_eval - 1) else null end;

        -- Lấy missed_streak từ row finalized gần nhất
        select coalesce(
            (select t.missed_streak
             from public.user_daily_tasks t
             where t.user_id = r.id
               and t.task_date < p_eval
               and t.finalized_at is not null
             order by t.task_date desc
             limit 1),
            r.daily_missed_streak,
            0
        ) into v_prev_streak;

        -- Xác định streak mới và phạt
        if v_exempt then
            v_new_streak := 0;
            v_deduction := 0;
        elsif v_met then
            v_new_streak := 0;
            v_deduction := 0;
        else
            -- Khi owner có effective_required_tests = 0 (do nguồn app = 0): không phạt và không tăng chuỗi
            if v_mode = 'owner' and v_effective <= 0 then
                v_new_streak := v_prev_streak;
                v_deduction := 0;
            else
                v_new_streak := v_prev_streak + 1;
                v_pct := case
                    when v_new_streak = 1 then 0.01
                    when v_new_streak = 2 then 0.02
                    when v_new_streak = 3 then 0.05
                    else 0.10
                end;

                if v_mode = 'owner' and v_effective > 0 then
                    v_ratio := greatest(
                        0,
                        least(
                            1,
                            (v_effective - v_completed)::numeric / v_effective::numeric
                        )
                    );
                elsif v_mode = 'member' then
                    v_ratio := case when v_logged_in then 0 else 1 end;
                else
                    v_ratio := 0;
                end if;

                if v_ratio <= 0 then
                    v_deduction := 0;
                else
                    v_deduction := least(
                        r.credits,
                        greatest(1, ceil(r.credits * v_pct * v_ratio)::int)
                    );
                end if;
            end if;
        end if;

        v_new_balance := r.credits - v_deduction;

        -- Ghi bản ghi vào user_daily_tasks
        insert into public.user_daily_tasks as t (
            user_id, task_date, mode, active_app_count, required_tests,
            effective_required_tests, available_apps, completed_tests,
            logged_in, is_exempt, met, missed_streak, penalty_credits, finalized_at,
            policy_id, tests_per_active_app,
            carryover_version, base_required_tests, carry_in_tests, carry_out_tests,
            carry_source_date, carryover_effective_from
        ) values (
            r.id, p_eval, v_mode,
            coalesce((v_status ->> 'active_app_count')::int, 0),
            v_required,
            v_effective,
            coalesce((v_status ->> 'available_apps')::int, 0),
            v_completed,
            v_logged_in,
            v_exempt,
            v_met,
            v_new_streak,
            v_deduction,
            now(),
            v_policy.id,
            v_policy.tests_per_active_app,
            case when v_is_carryover_active then 1 else null end,
            v_base_req,
            v_carry_in,
            v_carry_out,
            v_source_date,
            v_effective_from
        )
        on conflict (user_id, task_date) do update
        set mode = excluded.mode,
            active_app_count = excluded.active_app_count,
            required_tests = excluded.required_tests,
            effective_required_tests = excluded.effective_required_tests,
            available_apps = excluded.available_apps,
            completed_tests = excluded.completed_tests,
            logged_in = excluded.logged_in,
            is_exempt = excluded.is_exempt,
            met = excluded.met,
            missed_streak = excluded.missed_streak,
            penalty_credits = excluded.penalty_credits,
            finalized_at = now(),
            policy_id = excluded.policy_id,
            tests_per_active_app = excluded.tests_per_active_app,
            carryover_version = excluded.carryover_version,
            base_required_tests = excluded.base_required_tests,
            carry_in_tests = excluded.carry_in_tests,
            carry_out_tests = excluded.carry_out_tests,
            carry_source_date = excluded.carry_source_date,
            carryover_effective_from = excluded.carryover_effective_from
        where t.finalized_at is null;

        get diagnostics v_rows = row_count;
        if v_rows = 0 then
            continue;
        end if;

        if not v_exempt then
            update public.profiles
            set credits = v_new_balance,
                daily_missed_streak = v_new_streak
            where id = r.id;

            if v_deduction > 0 then
                if v_mode = 'owner' then
                    v_note := format(
                        'Không đạt chỉ tiêu ngày %s: %s/%s app (thiếu %s). Trừ %s Credit.',
                        to_char(p_eval, 'DD/MM/YYYY'),
                        v_completed,
                        v_effective,
                        greatest(0, v_effective - v_completed),
                        v_deduction
                    );
                else
                    v_note := format(
                        'Không đăng nhập ngày %s. Trừ %s Credit.',
                        to_char(p_eval, 'DD/MM/YYYY'),
                        v_deduction
                    );
                end if;

                insert into public.credit_logs (user_id, amount, action, note, balance)
                values (r.id, -v_deduction, 'inactivity_penalty', v_note, v_new_balance);
            end if;

            if not v_met then
                insert into public.notifications (user_id, title, message, type, data)
                values (
                    r.id,
                    'Không đạt nhiệm vụ ngày',
                    case
                        when v_deduction = 0 and v_mode = 'owner' then format(
                            'Ngày %s bạn mới test %s/%s app. Số dư hiện tại là 0 nên không trừ Credit, nhưng chuỗi thiếu nhiệm vụ tăng lên %s ngày.',
                            to_char(p_eval, 'DD/MM/YYYY'),
                            v_completed,
                            v_effective,
                            v_new_streak
                        )
                        when v_deduction = 0 then format(
                            'Ngày %s bạn không mở app. Số dư hiện tại là 0 nên không trừ Credit, nhưng chuỗi thiếu nhiệm vụ tăng lên %s ngày.',
                            to_char(p_eval, 'DD/MM/YYYY'),
                            v_new_streak
                        )
                        when v_mode = 'owner' then format(
                            'Ngày %s bạn mới test %s/%s app. Bạn bị trừ %s Credit và chuỗi thiếu nhiệm vụ tăng lên %s ngày.',
                            to_char(p_eval, 'DD/MM/YYYY'),
                            v_completed,
                            v_effective,
                            v_deduction,
                            v_new_streak
                        )
                        else format(
                            'Ngày %s bạn không mở app. Bạn bị trừ %s Credit và chuỗi thiếu nhiệm vụ tăng lên %s ngày.',
                            to_char(p_eval, 'DD/MM/YYYY'),
                            v_deduction,
                            v_new_streak
                        )
                    end,
                    'credit',
                    jsonb_build_object(
                        'task_date', to_char(p_eval, 'YYYY-MM-DD'),
                        'penalty_credits', v_deduction
                    )
                );
            end if;

            -- Nếu hôm nay (v_today) đã hoàn thành, reset streak ngay
            perform public.refresh_daily_completion(r.id, v_today);
        end if;
    end loop;
end;
$function$;

CREATE OR REPLACE FUNCTION public._assert_daily_task_admin()
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_uid uuid := auth.uid();
    v_role text;
    v_locked boolean;
begin
    if v_uid is null then
        raise exception 'UNAUTHORIZED: Authentication required';
    end if;

    select p.role, coalesce(p.is_locked, false)
    into v_role, v_locked
    from public.profiles p
    where p.id = v_uid;

    if v_role is null or lower(v_role) != 'admin' or v_locked = true then
        raise exception 'FORBIDDEN: Admin access required';
    end if;

    return v_uid;
end;
$function$;

CREATE OR REPLACE FUNCTION public._campaign_json(c campaigns)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
    select jsonb_build_object(
        'id', c.id,
        'owner_id', c.owner_id,
        'app_name', c.app_name,
        'package_name', c.package_name,
        'play_url', c.play_url,
        'testing_url', c.testing_url,
        'description', c.description,
        'target_testers', c.target_testers,
        'target_days', c.target_days,
        'start_date', to_char(c.start_date, 'YYYY-MM-DD'),
        'status', c.status,
        'icon_url', c.icon_url,
        'test_username', c.test_username,
        'test_password', c.test_password,
        'tip_credits', c.tip_credits,
        'is_boosted', c.is_boosted,
        'slot_number', c.slot_number,
        'paused_reason', c.paused_reason,
        'admin_note', c.admin_note,
        'completed_at', to_char(c.completed_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
        'created_at', to_char(c.created_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
        'push_business_date', to_char(c.push_business_date, 'YYYY-MM-DD'),
        'push_expires_at', to_char(c.push_expires_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
        'push_order', c.push_order
    );
$function$;

CREATE OR REPLACE FUNCTION public._check_home_stats_policy_immutability()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_current_vn date := (clock_timestamp() at time zone 'Asia/Ho_Chi_Minh')::date;
begin
    if tg_op = 'UPDATE' then
        if old.effective_from <= v_current_vn then
            raise exception 'ACTIVE_POLICY_IMMUTABLE: Cannot modify an active or past policy (effective_from: %)', old.effective_from;
        end if;
    end if;
    return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public._format_daily_task_policy_json(p daily_task_policies)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
    select jsonb_build_object(
        'id', p.id,
        'tests_per_active_app', p.tests_per_active_app,
        'effective_from', case when not isfinite(p.effective_from) then null else to_char(p.effective_from, 'YYYY-MM-DD') end,
        'is_baseline', not isfinite(p.effective_from),
        'operator_note', p.operator_note,
        'updated_at', to_char(p.updated_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
    );
$function$;

CREATE OR REPLACE FUNCTION public._get_daily_task_policy_revision()
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
    select coalesce(
        md5(string_agg(
            p.id::text || ':' ||
            p.effective_from::text || ':' ||
            p.tests_per_active_app::text || ':' ||
            to_char(p.updated_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"') || ':' ||
            md5(p.operator_note),
            ',' order by p.id
        )),
        'empty'
    )
    from public.daily_task_policies p;
$function$;

CREATE OR REPLACE FUNCTION public._get_home_stats_period(p_today date)
 RETURNS TABLE(period_start date, period_end_exclusive date, cycle_days integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_eff date;
    v_days int;
    v_diff int;
begin
    -- Tìm chính sách có effective_from <= p_today gần nhất
    select p.effective_from, p.cycle_days
    into v_eff, v_days
    from public.home_stats_policies p
    where p.effective_from <= p_today
    order by p.effective_from desc
    limit 1;

    if v_eff is null then
        v_eff := p_today;
        v_days := 1;
    end if;

    v_diff := p_today - v_eff;
    period_start := v_eff + ((floor(v_diff::numeric / v_days) * v_days)::int);
    period_end_exclusive := period_start + v_days;
    cycle_days := v_days;
    return next;
end;
$function$;

CREATE OR REPLACE FUNCTION public._get_home_stats_revision()
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    select coalesce(
        md5(string_agg(
            id::text || ':' || effective_from::text || ':' || cycle_days::text || ':' || coalesce(extract(epoch from updated_at)::bigint::text, '0'),
            ',' order by id
        )),
        'empty'
    ) from public.home_stats_policies;
$function$;

CREATE OR REPLACE FUNCTION public._grant_report_tip(p_campaign_id uuid, p_tester_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_owner_id uuid;
    v_tip int;
    v_app_name text;
    v_owner_balance int;
    v_tester_balance int;
begin
    select owner_id, tip_credits, app_name
      into v_owner_id, v_tip, v_app_name
    from public.campaigns
    where id = p_campaign_id;

    if v_owner_id is null
       or coalesce(v_tip, 0) <= 0
       or v_owner_id = p_tester_id then
        return 0;
    end if;

    if not exists (select 1 from public.profiles where id = p_tester_id) then
        return 0;
    end if;

    select credits into v_owner_balance
    from public.profiles
    where id = v_owner_id
    for update;

    if coalesce(v_owner_balance, 0) < v_tip then
        return 0;
    end if;

    update public.profiles
    set credits = credits - v_tip
    where id = v_owner_id
    returning credits into v_owner_balance;

    update public.profiles
    set credits = credits + v_tip
    where id = p_tester_id
    returning credits into v_tester_balance;

    insert into public.credit_logs (user_id, amount, action, note, balance)
    values (
        v_owner_id,
        -v_tip,
        'campaign_tip_paid',
        format('Boa cho tester ứng dụng "%s" (mỗi lượt duyệt, -%s Credit)', coalesce(v_app_name, 'của bạn'), v_tip),
        v_owner_balance
    );

    insert into public.credit_logs (user_id, amount, action, note, balance)
    values (
        p_tester_id,
        v_tip,
        'campaign_tip_received',
        format('Nhận %s Credit boa từ chủ app "%s"', v_tip, coalesce(v_app_name, '')),
        v_tester_balance
    );

    return v_tip;
end;
$function$;

CREATE OR REPLACE FUNCTION public._profile_json(p profiles)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
    select jsonb_build_object(
        'id', p.id,
        'email', p.email,
        'display_name', p.display_name,
        'avatar_url', p.avatar_url,
        'credits', p.credits,
        'last_active_date', to_char(p.last_active_date, 'YYYY-MM-DD'),
        'missed_streak', p.daily_missed_streak,
        'daily_missed_streak', p.daily_missed_streak,
        'last_login_date', to_char(p.last_login_date, 'YYYY-MM-DD'),
        'role', p.role,
        'is_locked', p.is_locked,
        'created_at', to_char(p.created_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"')
    );
$function$;

CREATE OR REPLACE FUNCTION public._settle_campaign_app_update(p_campaign_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_camp                public.campaigns%rowtype;
    v_rel                 record;
    v_remaining           int;
    v_owner_balance       int;
    v_credit_log_id       uuid;
    v_target_owner_id     uuid;
begin
    -- Khóa theo thứ tự chuẩn: campaigns -> controls -> releases -> profiles
    select * into v_camp from public.campaigns where id = p_campaign_id for update;

    for v_rel in
        select * from public.app_update_releases
        where campaign_id = p_campaign_id and status = 'active'
        order by id
        for update
    loop
        v_remaining := v_rel.remaining_credits;
        v_target_owner_id := coalesce(v_rel.owner_id, v_rel.owner_id_snapshot);

        -- Khóa control trước
        update public.app_update_controls
        set active_release_id = null,
            updated_at = now()
        where owner_id = v_target_owner_id
          and package_name = v_rel.package_name
          and active_release_id = v_rel.id;

        -- Cập nhật release
        update public.app_update_releases
        set status = 'closed',
            closed_at = now(),
            remaining_credits = 0,
            refunded_credits = refunded_credits + v_remaining
        where id = v_rel.id;

        if v_remaining > 0 and v_target_owner_id is not null then
            -- Khóa profile nếu tồn tại
            if exists (select 1 from public.profiles where id = v_target_owner_id) then
                update public.profiles
                set credits = credits + v_remaining
                where id = v_target_owner_id
                returning credits into v_owner_balance;

                insert into public.credit_logs (user_id, amount, action, note, balance)
                values (
                    v_target_owner_id,
                    v_remaining,
                    'app_update_refund',
                    format('Hoàn %s Credit chưa dùng từ phiên bản %s (%s)', v_remaining, v_rel.version_name, v_rel.app_name),
                    v_owner_balance
                )
                returning id into v_credit_log_id;

                insert into public.app_update_financial_events (
                    release_id, event_type, amount, owner_id, credit_log_id
                ) values (
                    v_rel.id, 'refund', v_remaining, v_target_owner_id, v_credit_log_id
                );
            else
                insert into public.app_update_financial_events (
                    release_id, event_type, amount, owner_id, credit_log_id
                ) values (
                    v_rel.id, 'refund', v_remaining, v_target_owner_id, null
                );
            end if;
        end if;
    end loop;
end;
$function$;

CREATE OR REPLACE FUNCTION public._settle_mission_reward(p_report_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_report record;
    v_match record;
    v_job record;
    v_saved_m record;
    v_saved_mp record;
    v_creator_balance int;
    v_tester_balance int;
    v_paid boolean := false;
    v_backoff interval;
begin
    if p_report_id is null then
        return jsonb_build_object('settled', false, 'reason', 'NULL_REPORT_ID');
    end if;

    select * into v_report
    from public.tester_reports
    where id = p_report_id
    for update;

    if v_report.id is null then
        return jsonb_build_object('settled', false, 'reason', 'REPORT_NOT_FOUND');
    end if;

    if v_report.status <> 'approved' then
        return jsonb_build_object('settled', false, 'reason', 'REPORT_NOT_APPROVED');
    end if;

    -- Báo cáo test thường không được xét thưởng nhiệm vụ
    if v_report.submission_context = 'app_test' then
        return jsonb_build_object('settled', false, 'reason', 'NOT_A_MISSION_REPORT');
    end if;

    select * into v_job
    from public.mission_settlement_jobs
    where report_id = p_report_id
    for update;

    if v_job.id is not null and v_job.status in ('completed', 'skipped') then
        return jsonb_build_object('settled', false, 'reason', 'ALREADY_SETTLED', 'job_status', v_job.status);
    end if;

    if v_job.id is not null then
        select * into v_saved_m from public.missions where id = v_job.mission_id for update;
        select * into v_saved_mp from public.mission_participants where id = v_job.participant_id for update;

        if v_saved_m.id is null or v_saved_mp.id is null then
            update public.mission_settlement_jobs
            set status = 'skipped',
                skip_reason = 'MISSION_OR_PARTICIPANT_NOT_FOUND',
                updated_at = now()
            where id = v_job.id;
            return jsonb_build_object('settled', false, 'reason', 'TERMINATED_NOT_FOUND');
        end if;

        if v_saved_mp.status <> 'joined' then
            update public.mission_settlement_jobs
            set status = 'skipped',
                skip_reason = 'PARTICIPANT_NOT_JOINED',
                updated_at = now()
            where id = v_job.id;
            return jsonb_build_object('settled', false, 'reason', 'TERMINATED_PARTICIPANT_NOT_JOINED');
        end if;

        if v_saved_m.ends_at <= now() or v_saved_m.status in ('expired', 'cancelled', 'deleted', 'stopped_no_credits') then
            update public.mission_settlement_jobs
            set status = 'skipped',
                skip_reason = 'MISSION_EXPIRED_OR_TERMINATED',
                updated_at = now()
            where id = v_job.id;
            return jsonb_build_object('settled', false, 'reason', 'TERMINATED_MISSION_EXPIRED');
        end if;

        if v_saved_m.status = 'paused_by_creator' then
            update public.mission_settlement_jobs
            set attempt_count = attempt_count + 1,
                next_attempt_at = now() + interval '5 minutes',
                last_error = 'MISSION_PAUSED_BY_CREATOR',
                updated_at = now()
            where id = v_job.id;
            return jsonb_build_object('settled', false, 'reason', 'MISSION_PAUSED_BY_CREATOR');
        end if;

        select
            v_saved_m.id as mission_id,
            v_saved_m.creator_id,
            v_saved_m.title as mission_title,
            v_job.reward_credits,
            v_job.campaign_id,
            v_saved_mp.id as participant_id,
            v_saved_mp.joined_at
        into v_match;
    else
        -- Lần đầu (chưa có job)
        if v_report.mission_id is not null then
            -- Dữ liệu mới: Dùng chính xác identity nhiệm vụ đã lưu trên báo cáo
            select
                m.id as mission_id,
                m.creator_id,
                m.title as mission_title,
                m.reward_credits,
                m.campaign_id,
                mp.id as participant_id,
                mp.joined_at,
                m.status as mission_status,
                m.ends_at as mission_ends_at,
                mp.status as participant_status
            into v_match
            from public.missions m
            join public.mission_participants mp on mp.mission_id = m.id
            where m.id = v_report.mission_id
              and mp.id = v_report.mission_participant_id
              and mp.user_id = v_report.user_id
              and m.campaign_id = v_report.campaign_id
            for update of m;

            if v_match.mission_id is null then
                return jsonb_build_object('settled', false, 'reason', 'MISSION_OR_PARTICIPANT_NOT_FOUND');
            end if;

            if v_match.participant_status <> 'joined' then
                return jsonb_build_object('settled', false, 'reason', 'PARTICIPANT_NOT_JOINED');
            end if;

            -- Chính sách hiện hành: duyệt sau hạn ends_at <= now() không trả thưởng mission
            if v_match.mission_ends_at <= now() or v_match.mission_status in ('expired', 'cancelled', 'deleted', 'stopped_no_credits') then
                return jsonb_build_object('settled', false, 'reason', 'TERMINATED_MISSION_EXPIRED');
            end if;

            if v_match.mission_status = 'paused_by_creator' then
                return jsonb_build_object('settled', false, 'reason', 'MISSION_PAUSED_BY_CREATOR');
            end if;
        else
            -- Dữ liệu lịch sử (legacy reports chưa có mission_id)
            select
                m.id as mission_id,
                m.creator_id,
                m.title as mission_title,
                m.reward_credits,
                m.campaign_id,
                mp.id as participant_id,
                mp.joined_at
            into v_match
            from public.missions m
            join public.mission_participants mp on mp.mission_id = m.id
            where m.campaign_id = v_report.campaign_id
              and mp.user_id = v_report.user_id
              and mp.status = 'joined'
              and v_report.created_at >= mp.joined_at
              and m.status in ('open', 'full')
              and m.ends_at > now()
            order by m.created_at desc
            limit 1
            for update of m;

            if v_match.mission_id is null then
                return jsonb_build_object('settled', false, 'reason', 'NO_ELIGIBLE_MISSION');
            end if;
        end if;

        insert into public.mission_settlement_jobs (
            report_id, mission_id, participant_id, campaign_id,
            tester_id, creator_id, reward_credits, status,
            next_attempt_at
        ) values (
            v_report.id, v_match.mission_id, v_match.participant_id, v_match.campaign_id,
            v_report.user_id, v_match.creator_id, v_match.reward_credits, 'pending',
            now()
        )
        on conflict (report_id) do update
        set mission_id = excluded.mission_id,
            participant_id = excluded.participant_id,
            updated_at = now()
        returning * into v_job;
    end if;

    begin
        select credits into v_creator_balance
        from public.profiles
        where id = v_match.creator_id
        for update;

        if coalesce(v_creator_balance, 0) >= v_match.reward_credits then
            update public.mission_participants
            set status = 'completed',
                completed_at = now()
            where id = v_match.participant_id
              and status = 'joined';

            if not found then
                update public.mission_settlement_jobs
                set status = 'skipped',
                    skip_reason = 'PARTICIPANT_ALREADY_COMPLETED',
                    updated_at = now()
                where id = v_job.id;

                return jsonb_build_object('settled', false, 'reason', 'ALREADY_COMPLETED');
            end if;

            update public.profiles
            set credits = credits - v_match.reward_credits
            where id = v_match.creator_id
            returning credits into v_creator_balance;

            insert into public.credit_logs (user_id, amount, action, note, balance)
            values (
                v_match.creator_id,
                -v_match.reward_credits,
                'mission_reward',
                format('Trả thưởng nhiệm vụ "%s" cho người tham gia', v_match.mission_title),
                v_creator_balance
            );

            update public.profiles
            set credits = credits + v_match.reward_credits
            where id = v_report.user_id
            returning credits into v_tester_balance;

            insert into public.credit_logs (user_id, amount, action, note, balance)
            values (
                v_report.user_id,
                v_match.reward_credits,
                'mission_reward',
                format('Nhận thưởng nhiệm vụ "%s"', v_match.mission_title),
                v_tester_balance
            );

            update public.mission_settlement_jobs
            set status = 'completed',
                updated_at = now()
            where id = v_job.id;

            insert into public.notifications (user_id, title, message, type, data)
            values (
                v_report.user_id,
                'Nhận thưởng nhiệm vụ 🎉',
                format('Báo cáo của bạn đã được duyệt. Bạn nhận được +%s Credit từ nhiệm vụ "%s"!', v_match.reward_credits, v_match.mission_title),
                'mission',
                jsonb_build_object(
                    'mission_id', v_match.mission_id,
                    'campaign_id', v_match.campaign_id,
                    'report_id', v_report.id,
                    'reward_credits', v_match.reward_credits
                )
            );

            return jsonb_build_object(
                'settled', true,
                'mission_id', v_match.mission_id,
                'reward_credits', v_match.reward_credits,
                'tester_balance', v_tester_balance
            );
        else
            update public.missions
            set status = 'stopped_no_credits'
            where id = v_match.mission_id
              and status in ('open', 'full', 'paused_by_creator');

            update public.mission_settlement_jobs
            set status = 'failed',
                attempt_count = attempt_count + 1,
                last_error = 'INSUFFICIENT_CREATOR_CREDITS',
                next_attempt_at = now() + interval '10 minutes',
                updated_at = now()
            where id = v_job.id;

            insert into public.notifications (user_id, title, message, type, data)
            values (
                v_match.creator_id,
                'Nhiệm vụ bị tạm dừng do hết Credit',
                format('Nhiệm vụ "%s" không đủ Credit trả cho tester. Nhiệm vụ đã tạm dừng.', v_match.mission_title),
                'mission',
                jsonb_build_object(
                    'mission_id', v_match.mission_id,
                    'campaign_id', v_match.campaign_id,
                    'action', 'stopped_no_credits'
                )
            );

            return jsonb_build_object('settled', false, 'reason', 'INSUFFICIENT_CREATOR_CREDITS');
        end if;
    exception when others then
        v_backoff := case
            when coalesce(v_job.attempt_count, 0) < 3 then interval '1 minute'
            when coalesce(v_job.attempt_count, 0) < 6 then interval '5 minutes'
            else interval '30 minutes'
        end;

        update public.mission_settlement_jobs
        set status = 'failed',
            attempt_count = attempt_count + 1,
            last_error = sqlerrm,
            next_attempt_at = now() + v_backoff,
            updated_at = now()
        where id = v_job.id;

        return jsonb_build_object('settled', false, 'reason', 'ERROR', 'error', sqlerrm);
    end;
end;
$function$;

CREATE OR REPLACE FUNCTION public._settle_mission_reward(p_campaign_id uuid, p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_report_id uuid;
begin
    if p_campaign_id is null or p_user_id is null then
        return jsonb_build_object('settled', false);
    end if;

    select id into v_report_id
    from public.tester_reports
    where campaign_id = p_campaign_id
      and user_id = p_user_id
      and status = 'approved'
    order by coalesce(reviewed_at, created_at) desc, created_at desc
    limit 1;

    if v_report_id is not null then
        return public._settle_mission_reward(v_report_id);
    end if;

    return jsonb_build_object('settled', false);
end;
$function$;

CREATE OR REPLACE FUNCTION public.acknowledge_warning(p_warning_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    update public.user_warnings
    set acknowledged = true
    where id = p_warning_id
      and user_id = auth.uid();
    return true;
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_adjust_credits(p_target_user_id uuid, p_amount integer, p_reason text DEFAULT 'Điều chỉnh bởi Admin'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_caller_id uuid := auth.uid();
    v_caller_role text;
    v_current_credits int;
    v_new_balance int;
begin
    if v_caller_id is null then
        raise exception 'NOT_AUTHENTICATED';
    end if;

    -- Kiểm tra quyền Admin của người gọi
    select role into v_caller_role
    from public.profiles
    where id = v_caller_id;

    if v_caller_role is null or lower(v_caller_role) != 'admin' then
        raise exception 'PERMISSION_DENIED: Chỉ Quản trị viên mới có quyền điều chỉnh Credit';
    end if;

    -- Khóa dòng profile của user mục tiêu để đảm bảo tính nguyên tử
    select credits into v_current_credits
    from public.profiles
    where id = p_target_user_id
    for update;

    if v_current_credits is null then
        raise exception 'USER_NOT_FOUND';
    end if;

    v_new_balance := v_current_credits + p_amount;
    if v_new_balance < 0 then
        v_new_balance := 0; -- Số dư không được âm
    end if;

    update public.profiles
    set credits = v_new_balance
    where id = p_target_user_id;

    -- Ghi lịch sử biến động Credit
    insert into public.credit_logs (user_id, amount, action, note, balance)
    values (
        p_target_user_id,
        p_amount,
        case when p_amount >= 0 then 'admin_grant' else 'admin_deduct' end,
        coalesce(nullif(trim(p_reason), ''), case when p_amount >= 0 then 'Admin tặng Credit' else 'Admin trừ Credit' end),
        v_new_balance
    );

    return jsonb_build_object(
        'success', true,
        'user_id', p_target_user_id,
        'previous_credits', v_current_credits,
        'new_credits', v_new_balance,
        'amount', p_amount
    );
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_cancel_daily_task_policy(p_effective_from date, p_operator_note text, p_expected_revision text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_today date;
    v_current_rev text;
    v_cancelled_row jsonb;
    v_new_config jsonb;
begin
    perform public._assert_daily_task_admin();

    -- Lấy khóa advisory trước khi kiểm tra revision và ngày
    perform pg_advisory_xact_lock(hashtextextended('daily_task_policy_schedule', 0));

    if p_expected_revision is null or btrim(p_expected_revision) = '' then
        raise exception 'DAILY_TASK_POLICY_REVISION_REQUIRED';
    end if;

    v_current_rev := public._get_daily_task_policy_revision();
    if v_current_rev is distinct from p_expected_revision then
        raise exception 'DAILY_TASK_POLICY_CONFLICT';
    end if;

    v_today := (clock_timestamp() at time zone 'Asia/Ho_Chi_Minh')::date;
    if p_effective_from is null or not isfinite(p_effective_from) or p_effective_from <= v_today then
        raise exception 'DAILY_TASK_POLICY_FUTURE_DATE_REQUIRED';
    end if;

    if p_operator_note is null or length(btrim(p_operator_note)) not between 1 and 1000 then
        raise exception 'DAILY_TASK_POLICY_NOTE_REQUIRED';
    end if;

    -- Gọi hàm nội bộ kế thừa từ 042
    v_cancelled_row := public.cancel_daily_task_policy(
        p_effective_from,
        p_operator_note
    );

    v_new_config := public.admin_get_daily_task_config();

    return jsonb_build_object(
        'success', true,
        'cancelled_policy', v_cancelled_row,
        'config', v_new_config,
        'revision', v_new_config ->> 'revision'
    );
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_delete_campaign(p_campaign_id uuid, p_reason text DEFAULT 'Gỡ bỏ bởi Admin'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_caller_id uuid := auth.uid();
    v_caller_role text;
    v_app_name text;
    v_owner_id uuid;
begin
    if v_caller_id is null then
        raise exception 'NOT_AUTHENTICATED';
    end if;

    -- Kiểm tra quyền Admin của người thực hiện
    select role into v_caller_role
    from public.profiles
    where id = v_caller_id;

    if v_caller_role is null or lower(v_caller_role) != 'admin' then
        raise exception 'PERMISSION_DENIED: Chỉ Quản trị viên mới có quyền gỡ bỏ ứng dụng';
    end if;

    -- Lấy thông tin ứng dụng trước khi xóa
    select app_name, owner_id into v_app_name, v_owner_id
    from public.campaigns
    where id = p_campaign_id;

    if v_app_name is null then
        raise exception 'CAMPAIGN_NOT_FOUND';
    end if;

    -- Xóa app (nhờ ON DELETE CASCADE, tất cả checkins, feedbacks, campaign_members, tester_reports sẽ tự động bị xóa theo)
    delete from public.campaigns
    where id = p_campaign_id;

    return jsonb_build_object(
        'success', true,
        'campaign_id', p_campaign_id,
        'app_name', v_app_name,
        'owner_id', v_owner_id,
        'reason', coalesce(p_reason, 'Gỡ bỏ bởi Admin')
    );
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_get_contact_reports(p_status text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_caller_id uuid := auth.uid();
    v_caller_role text;
    v_result jsonb;
begin
    if v_caller_id is null then
        raise exception 'NOT_AUTHENTICATED';
    end if;

    select role into v_caller_role
    from public.profiles
    where id = v_caller_id;

    if v_caller_role is distinct from 'admin' then
        raise exception 'NOT_ADMIN';
    end if;

    select coalesce(jsonb_agg(to_jsonb(t) order by t.created_at desc), '[]'::jsonb)
    into v_result
    from (
        select
            r.id,
            r.user_id,
            r.category,
            r.message,
            r.app_version,
            r.platform,
            r.device_model,
            r.status,
            r.admin_reply,
            r.replied_at,
            r.created_at,
            p.display_name,
            p.email,
            p.avatar_url
        from public.contact_reports r
        left join public.profiles p on p.id = r.user_id
        where p_status is null or r.status = p_status
        order by r.created_at desc
        limit 300
    ) t;

    return v_result;
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_get_daily_task_config()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_today date;
    v_active_policy public.daily_task_policies;
    v_future_json jsonb;
    v_revision text;
    v_has_more boolean := false;
    v_next_date date := null;
    v_next_id bigint := null;
    v_total_future integer := 0;
begin
    perform public._assert_daily_task_admin();
    v_today := (clock_timestamp() at time zone 'Asia/Ho_Chi_Minh')::date;

    select p.* into v_active_policy
    from public.daily_task_policies p
    where p.effective_from <= v_today
    order by p.effective_from desc
    limit 1;

    with candidates as (
        select p as policy_row, count(*) over() as found_count
        from public.daily_task_policies p
        where p.effective_from > v_today
        order by p.effective_from asc, p.id asc
        limit 51
    ),
    page_items as (
        select policy_row, found_count
        from candidates
        order by (policy_row).effective_from asc, (policy_row).id asc
        limit 50
    ),
    last_item as (
        select (policy_row).effective_from as effective_from, (policy_row).id as id, found_count
        from page_items
        order by (policy_row).effective_from desc, (policy_row).id desc
        limit 1
    )
    select
        coalesce(jsonb_agg(public._format_daily_task_policy_json(p.policy_row) order by (p.policy_row).effective_from asc, (p.policy_row).id asc), '[]'::jsonb),
        coalesce((select found_count > 50 from last_item), false),
        (select case when found_count > 50 then effective_from else null end from last_item),
        (select case when found_count > 50 then id else null end from last_item)
    into v_future_json, v_has_more, v_next_date, v_next_id
    from page_items p;

    select count(*) into v_total_future
    from public.daily_task_policies
    where effective_from > v_today;

    v_revision := public._get_daily_task_policy_revision();

    return jsonb_build_object(
        'today', to_char(v_today, 'YYYY-MM-DD'),
        'timezone', 'Asia/Ho_Chi_Minh',
        'revision', v_revision,
        'active_policy', case when v_active_policy.id is not null then public._format_daily_task_policy_json(v_active_policy) else null end,
        'future_policies', coalesce(v_future_json, '[]'::jsonb),
        'has_more', coalesce(v_has_more, false),
        'next_cursor_date', case when v_next_date is not null then to_char(v_next_date, 'YYYY-MM-DD') else null end,
        'next_cursor_id', v_next_id,
        'total_future_policies', v_total_future
    );
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_get_daily_task_policy_history(p_limit integer DEFAULT 20, p_cursor_id bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_limit integer;
    v_items jsonb;
    v_has_more boolean := false;
    v_next_id bigint := null;
begin
    perform public._assert_daily_task_admin();
    v_limit := least(greatest(coalesce(p_limit, 20), 1), 100);

    with candidates as (
        select c.*
        from public.daily_task_policy_changes c
        where (p_cursor_id is null or c.id < p_cursor_id)
        order by c.id desc
        limit v_limit + 1
    ),
    counted as (
        select candidates.*, count(*) over() as total_found
        from candidates
    ),
    page_items as (
        select *
        from counted
        order by id desc
        limit v_limit
    ),
    last_item as (
        select id, total_found
        from page_items
        order by id asc
        limit 1
    )
    select
        coalesce(jsonb_agg(jsonb_build_object(
            'id', h.id,
            'policy_id', h.policy_id,
            'operation', h.operation,
            'old_row', h.old_row,
            'new_row', h.new_row,
            'operator_note', h.operator_note,
            'session_role', h.session_role,
            'invoked_role', h.invoked_role,
            'actor_id', h.actor_id,
            'actor_name', prof.display_name,
            'actor_email', prof.email,
            'changed_at', to_char(h.changed_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
        ) order by h.id desc), '[]'::jsonb),
        coalesce((select total_found > v_limit from last_item), false),
        (select case when total_found > v_limit then id else null end from last_item)
    into v_items, v_has_more, v_next_id
    from page_items h
    left join public.profiles prof on prof.id = h.actor_id;

    return jsonb_build_object(
        'items', coalesce(v_items, '[]'::jsonb),
        'has_more', coalesce(v_has_more, false),
        'next_cursor_id', v_next_id
    );
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_get_home_stats_config()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_uid uuid := auth.uid();
    v_caller_role text;
    v_today date := (clock_timestamp() at time zone 'Asia/Ho_Chi_Minh')::date;
    v_active_days int;
    v_active_from date;
    v_pending_days int;
    v_pending_from date;
    v_revision text;
begin
    if v_uid is null then
        raise exception 'UNAUTHORIZED: Authentication required';
    end if;

    select role into v_caller_role from public.profiles where id = v_uid;
    if v_caller_role is null or lower(v_caller_role) != 'admin' then
        raise exception 'FORBIDDEN: Admin access required';
    end if;

    -- Lấy chính sách đang chạy (effective_from <= v_today)
    select cycle_days, effective_from into v_active_days, v_active_from
    from public.home_stats_policies
    where effective_from <= v_today
    order by effective_from desc
    limit 1;

    -- Lấy chính sách chờ áp dụng ở tương lai gần nhất (effective_from > v_today)
    select cycle_days, effective_from into v_pending_days, v_pending_from
    from public.home_stats_policies
    where effective_from > v_today
    order by effective_from asc
    limit 1;

    v_revision := public._get_home_stats_revision();

    return jsonb_build_object(
        'active_cycle_days', coalesce(v_active_days, 1),
        'active_effective_from', v_active_from,
        'pending_cycle_days', v_pending_days,
        'pending_effective_from', v_pending_from,
        'revision', v_revision,
        'today', v_today
    );
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_list_daily_task_policies(p_limit integer DEFAULT 50, p_cursor_date date DEFAULT NULL::date, p_cursor_id bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_today date;
    v_limit integer;
    v_items jsonb;
    v_has_more boolean := false;
    v_next_date date := null;
    v_next_id bigint := null;
begin
    perform public._assert_daily_task_admin();
    v_today := (clock_timestamp() at time zone 'Asia/Ho_Chi_Minh')::date;
    v_limit := least(greatest(coalesce(p_limit, 50), 1), 100);

    with candidates as (
        select p as policy_row, count(*) over() as total_found
        from public.daily_task_policies p
        where p.effective_from > v_today
          and (
              p_cursor_date is null
              or (p.effective_from, p.id) > (p_cursor_date, coalesce(p_cursor_id, 0))
          )
        order by p.effective_from asc, p.id asc
        limit v_limit + 1
    ),
    page_items as (
        select policy_row, total_found
        from candidates
        order by (policy_row).effective_from asc, (policy_row).id asc
        limit v_limit
    ),
    last_item as (
        select (policy_row).effective_from as effective_from, (policy_row).id as id, total_found
        from page_items
        order by (policy_row).effective_from desc, (policy_row).id desc
        limit 1
    )
    select
        coalesce(jsonb_agg(public._format_daily_task_policy_json(p.policy_row) order by (p.policy_row).effective_from asc, (p.policy_row).id asc), '[]'::jsonb),
        coalesce((select total_found > v_limit from last_item), false),
        (select case when total_found > v_limit then effective_from else null end from last_item),
        (select case when total_found > v_limit then id else null end from last_item)
    into v_items, v_has_more, v_next_date, v_next_id
    from page_items p;

    return jsonb_build_object(
        'items', coalesce(v_items, '[]'::jsonb),
        'has_more', coalesce(v_has_more, false),
        'next_cursor_date', case when v_next_date is not null then to_char(v_next_date, 'YYYY-MM-DD') else null end,
        'next_cursor_id', v_next_id
    );
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_pause_campaign(p_campaign_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_caller_id uuid := auth.uid();
    v_caller_role text;
    v_camp public.campaigns%rowtype;
    v_note text;
begin
    if v_caller_id is null then
        raise exception 'NOT_AUTHENTICATED';
    end if;

    select lower(role) into v_caller_role
    from public.profiles
    where id = v_caller_id;

    if coalesce(v_caller_role, '') <> 'admin' then
        raise exception 'NOT_ADMIN';
    end if;

    select * into v_camp
    from public.campaigns
    where id = p_campaign_id
    for update;

    if v_camp.id is null then
        raise exception 'CAMPAIGN_NOT_FOUND';
    end if;

    if v_camp.status in ('production', 'completed') then
        raise exception 'CAMPAIGN_FINALIZED';
    end if;

    if v_camp.status not in ('open', 'paused') then
        raise exception 'CAMPAIGN_NOT_OPEN';
    end if;

    v_note := nullif(btrim(coalesce(p_reason, '')), '');

    -- Idempotent: đã tạm dừng bởi Admin với cùng lý do thì không gửi trùng thông báo.
    if v_camp.status = 'paused'
       and v_camp.paused_reason = 'admin_manual'
       and v_camp.admin_note is not distinct from v_note then
        return jsonb_build_object(
            'success', true,
            'campaign_id', p_campaign_id,
            'previous_status', v_camp.status,
            'status', v_camp.status,
            'paused_reason', v_camp.paused_reason,
            'app_name', v_camp.app_name,
            'owner_id', v_camp.owner_id,
            'admin_note', v_camp.admin_note
        );
    end if;

    update public.campaigns
    set status = 'paused',
        paused_reason = 'admin_manual',
        admin_note = v_note,
        admin_resumed = false
    where id = p_campaign_id;

    insert into public.notifications (user_id, title, message, type, data)
    values (
        v_camp.owner_id,
        'Ứng dụng đã bị tạm dừng bởi Admin ⏸',
        format(
            'Ứng dụng "%s" đã bị Quản trị viên tạm dừng.%s',
            coalesce(nullif(v_camp.app_name, ''), 'của bạn'),
            case when v_note is null then '' else E'\nLý do: ' || v_note end
        ),
        'campaign',
        jsonb_build_object(
            'campaign_id', p_campaign_id,
            'reason', 'admin_pause',
            'admin_note', v_note
        )
    );

    return jsonb_build_object(
        'success', true,
        'campaign_id', p_campaign_id,
        'previous_status', v_camp.status,
        'status', 'paused',
        'paused_reason', 'admin_manual',
        'app_name', v_camp.app_name,
        'owner_id', v_camp.owner_id,
        'admin_note', v_note
    );
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_reply_contact_report(p_report_id uuid, p_message text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_caller_id uuid := auth.uid();
    v_caller_role text;
    v_report public.contact_reports;
begin
    if v_caller_id is null then
        raise exception 'NOT_AUTHENTICATED';
    end if;

    select role into v_caller_role
    from public.profiles
    where id = v_caller_id;

    if v_caller_role is distinct from 'admin' then
        raise exception 'NOT_ADMIN';
    end if;

    if p_message is null or trim(p_message) = '' then
        raise exception 'MESSAGE_REQUIRED';
    end if;

    update public.contact_reports
    set admin_reply = trim(p_message),
        replied_at = now(),
        status = 'replied'
    where id = p_report_id
    returning * into v_report;

    if v_report.id is null then
        raise exception 'REPORT_NOT_FOUND';
    end if;

    -- Đẩy thông báo cho user sở hữu phản hồi (hiện trong Trung tâm thông báo).
    insert into public.notifications (user_id, title, message, type, data)
    values (
        v_report.user_id,
        'Phản hồi từ Admin',
        trim(p_message),
        'admin',
        jsonb_build_object(
            'sender', 'admin',
            'broadcast', false,
            'contact_report_id', p_report_id
        )
    );

    return to_jsonb(v_report);
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_resume_campaign(p_campaign_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_caller_id uuid := auth.uid();
    v_caller_role text;
    v_camp public.campaigns%rowtype;
    v_hold_open boolean;
begin
    if v_caller_id is null then
        raise exception 'NOT_AUTHENTICATED';
    end if;

    select lower(role) into v_caller_role
    from public.profiles
    where id = v_caller_id;

    if coalesce(v_caller_role, '') <> 'admin' then
        raise exception 'NOT_ADMIN';
    end if;

    select * into v_camp
    from public.campaigns
    where id = p_campaign_id
    for update;

    if v_camp.id is null then
        raise exception 'CAMPAIGN_NOT_FOUND';
    end if;

    if v_camp.status in ('production', 'completed') then
        raise exception 'CAMPAIGN_FINALIZED';
    end if;

    if v_camp.status <> 'paused' then
        raise exception 'CAMPAIGN_NOT_PAUSED';
    end if;

    -- Vẫn giữ luật 30 ngày hiển thị.
    if v_camp.created_at <= now() - interval '30 days' then
        update public.campaigns
        set status = 'completed',
            completed_at = now(),
            paused_reason = null,
            admin_note = null,
            admin_resumed = false
        where id = p_campaign_id;

        insert into public.notifications (user_id, title, message, type, data)
        values (
            v_camp.owner_id,
            'Ứng dụng đã hoàn thành kiểm thử ✅',
            format(
                'Ứng dụng "%s" đã hoàn thành thời gian hiển thị 30 ngày và được chuyển sang mục "Đã hoàn thành Kiểm thử" trên Trang chủ.',
                coalesce(nullif(v_camp.app_name, ''), 'của bạn')
            ),
            'campaign',
            jsonb_build_object('campaign_id', p_campaign_id, 'reason', 'window_expired')
        );

        return jsonb_build_object(
            'success', true,
            'campaign_id', p_campaign_id,
            'previous_status', v_camp.status,
            'status', 'completed',
            'app_name', v_camp.app_name,
            'owner_id', v_camp.owner_id
        );
    end if;

    -- Không cho Admin mở app đã hết hạn Slot: chủ app vẫn phải gia hạn Slot.
    if v_camp.slot_number > 1 then
        if not exists (
            select 1 from public.user_slots s
            where s.user_id = v_camp.owner_id
              and s.slot_number = v_camp.slot_number
              and s.expires_at > now()
        ) then
            raise exception 'SLOT_EXPIRED';
        end if;
    end if;

    -- Chỉ giữ mở khi app bị auto-pause vì chủ vắng. Các lý do khác
    -- (chủ tự tạm dừng, Admin tạm dừng) trả về luật bình thường.
    v_hold_open := (v_camp.paused_reason = 'owner_inactive');

    update public.campaigns
    set status = 'open',
        paused_reason = null,
        completed_at = null,
        admin_note = null,
        admin_resumed = v_hold_open
    where id = p_campaign_id;

    insert into public.notifications (user_id, title, message, type, data)
    values (
        v_camp.owner_id,
        'Ứng dụng đã được Admin mở lại ✅',
        format(
            'Ứng dụng "%s" đã được Quản trị viên mở lại và đang nhận tester bình thường.',
            coalesce(nullif(v_camp.app_name, ''), 'của bạn')
        ),
        'campaign',
        jsonb_build_object('campaign_id', p_campaign_id, 'reason', 'admin_resume')
    );

    return jsonb_build_object(
        'success', true,
        'campaign_id', p_campaign_id,
        'previous_status', v_camp.status,
        'status', 'open',
        'paused_reason', null,
        'app_name', v_camp.app_name,
        'owner_id', v_camp.owner_id,
        'admin_resumed', v_hold_open
    );
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_schedule_daily_task_policy(p_tests_per_active_app integer, p_effective_from date, p_operator_note text, p_expected_revision text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_today date;
    v_current_rev text;
    v_saved_row jsonb;
    v_new_config jsonb;
begin
    perform public._assert_daily_task_admin();

    -- Lấy khóa advisory trước khi kiểm tra revision và ngày
    perform pg_advisory_xact_lock(hashtextextended('daily_task_policy_schedule', 0));

    if p_expected_revision is null or btrim(p_expected_revision) = '' then
        raise exception 'DAILY_TASK_POLICY_REVISION_REQUIRED';
    end if;

    v_current_rev := public._get_daily_task_policy_revision();
    if v_current_rev is distinct from p_expected_revision then
        raise exception 'DAILY_TASK_POLICY_CONFLICT';
    end if;

    v_today := (clock_timestamp() at time zone 'Asia/Ho_Chi_Minh')::date;
    if p_effective_from is null or not isfinite(p_effective_from) or p_effective_from <= v_today then
        raise exception 'DAILY_TASK_POLICY_FUTURE_DATE_REQUIRED';
    end if;

    if p_tests_per_active_app is null or p_tests_per_active_app not between 1 and 30 then
        raise exception 'DAILY_TASK_POLICY_INVALID_RATIO';
    end if;

    if p_operator_note is null or length(btrim(p_operator_note)) not between 1 and 1000 then
        raise exception 'DAILY_TASK_POLICY_NOTE_REQUIRED';
    end if;

    -- Gọi hàm nội bộ kế thừa từ 042 (chạy dưới quyền security definer của wrapper)
    v_saved_row := public.schedule_daily_task_policy(
        p_tests_per_active_app,
        p_effective_from,
        p_operator_note
    );

    v_new_config := public.admin_get_daily_task_config();

    return jsonb_build_object(
        'success', true,
        'policy', v_saved_row,
        'config', v_new_config,
        'revision', v_new_config ->> 'revision'
    );
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_send_notification(p_target_user_id uuid DEFAULT NULL::uuid, p_title text DEFAULT ''::text, p_message text DEFAULT ''::text, p_type text DEFAULT 'admin'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_caller_id uuid := auth.uid();
    v_caller_role text;
    v_count int := 0;
begin
    if v_caller_id is null then
        raise exception 'NOT_AUTHENTICATED';
    end if;

    select role into v_caller_role
    from public.profiles
    where id = v_caller_id;

    if coalesce(v_caller_role, '') <> 'admin' then
        raise exception 'PERMISSION_DENIED';
    end if;

    if p_title is null or trim(p_title) = '' then
        raise exception 'TITLE_REQUIRED';
    end if;

    if p_message is null or trim(p_message) = '' then
        raise exception 'MESSAGE_REQUIRED';
    end if;

    if p_target_user_id is not null then
        -- Gửi đích danh cho 1 user
        insert into public.notifications (user_id, title, message, type, data)
        values (
            p_target_user_id,
            p_title,
            p_message,
            coalesce(p_type, 'admin'),
            jsonb_build_object('sender', 'admin', 'broadcast', false)
        );
        v_count := 1;
    else
        -- Broadcast toàn hệ thống tới tất cả thành viên
        insert into public.notifications (user_id, title, message, type, data)
        select
            id,
            p_title,
            p_message,
            coalesce(p_type, 'admin'),
            jsonb_build_object('sender', 'admin', 'broadcast', true)
        from public.profiles;
        get diagnostics v_count = row_count;
    end if;

    return jsonb_build_object(
        'success', true,
        'sent_count', v_count,
        'target', case when p_target_user_id is null then 'all' else p_target_user_id::text end
    );
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_set_home_stats_cycle(p_cycle_days integer, p_expected_revision text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_uid uuid := auth.uid();
    v_caller_role text;
    v_today date;
    v_tomorrow date;
    v_active_days int;
    v_active_from date;
    v_existing_tomorrow int;
    v_current_rev text;
    r record;
begin
    if v_uid is null then
        raise exception 'UNAUTHORIZED: Authentication required';
    end if;

    select role into v_caller_role from public.profiles where id = v_uid;
    if v_caller_role is null or lower(v_caller_role) != 'admin' then
        raise exception 'FORBIDDEN: Admin access required';
    end if;

    if p_cycle_days is null or p_cycle_days not in (1, 2, 3) then
        raise exception 'INVALID_CYCLE_DAYS: Must be 1, 2, or 3';
    end if;

    -- R05: Bắt buộc revision hợp lệ; không được để null hoặc rỗng
    if p_expected_revision is null or trim(p_expected_revision) = '' then
        raise exception 'MISSING_REVISION: Expected revision is required';
    end if;

    -- Khóa tránh hai admin thao tác cùng lúc
    lock table public.home_stats_policies in exclusive mode;

    -- R06: Tính lại ngày chính xác sau khi đã lấy được lock
    v_today := (clock_timestamp() at time zone 'Asia/Ho_Chi_Minh')::date;
    v_tomorrow := v_today + 1;

    -- Kiểm tra revision dưới lock
    v_current_rev := public._get_home_stats_revision();
    if p_expected_revision <> v_current_rev then
        raise exception 'CONCURRENCY_CONFLICT: Config has been modified by another administrator';
    end if;

    -- Tìm chu kỳ đang có hiệu lực hôm nay
    select cycle_days, effective_from into v_active_days, v_active_from
    from public.home_stats_policies
    where effective_from <= v_today
    order by effective_from desc
    limit 1;

    v_active_days := coalesce(v_active_days, 1);

    if p_cycle_days = v_active_days then
        -- Admin chọn lại cùng giá trị đang chạy
        -- Nếu có lịch chờ ở tương lai (> v_today), hủy lịch chờ đó (rollback về mốc cũ)
        for r in select * from public.home_stats_policies where effective_from > v_today loop
            insert into public.home_stats_policy_audits (action, effective_from, cycle_days_old, cycle_days_new, actor_id)
            values ('CANCEL_SCHEDULE', r.effective_from, r.cycle_days, null, v_uid);
        end loop;
        delete from public.home_stats_policies where effective_from > v_today;
    else
        -- Admin chọn chu kỳ mới khác chu kỳ đang chạy -> áp dụng từ 00:00 ngày mai
        select cycle_days into v_existing_tomorrow
        from public.home_stats_policies
        where effective_from = v_tomorrow;

        if found then
            if v_existing_tomorrow <> p_cycle_days then
                update public.home_stats_policies
                set cycle_days = p_cycle_days, updated_at = now(), updated_by = v_uid
                where effective_from = v_tomorrow;

                insert into public.home_stats_policy_audits (action, effective_from, cycle_days_old, cycle_days_new, actor_id)
                values ('UPDATE_SCHEDULE', v_tomorrow, v_existing_tomorrow, p_cycle_days, v_uid);
            end if;
        else
            insert into public.home_stats_policies (effective_from, cycle_days, created_by, updated_by, created_at, updated_at)
            values (v_tomorrow, p_cycle_days, v_uid, v_uid, now(), now());

            insert into public.home_stats_policy_audits (action, effective_from, cycle_days_old, cycle_days_new, actor_id)
            values ('SET_SCHEDULE', v_tomorrow, v_active_days, p_cycle_days, v_uid);
        end if;

        -- Dọn các lịch xa hơn ngày mai nếu có
        delete from public.home_stats_policies where effective_from > v_tomorrow;
    end if;

    -- Trả về cấu hình mới nhất
    return public.admin_get_home_stats_config();
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_set_user_lock(p_target_user_id uuid, p_locked boolean, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_caller_id uuid := auth.uid();
    v_caller_role text;
begin
    if v_caller_id is null then
        raise exception 'NOT_AUTHENTICATED';
    end if;

    -- Kiểm tra quyền Admin
    select role into v_caller_role
    from public.profiles
    where id = v_caller_id;

    if v_caller_role is null or lower(v_caller_role) != 'admin' then
        raise exception 'PERMISSION_DENIED: Chỉ Quản trị viên mới có quyền khóa/mở khóa tài khoản';
    end if;

    -- Không cho phép Admin tự khóa chính mình
    if p_target_user_id = v_caller_id and p_locked = true then
        raise exception 'CANNOT_LOCK_SELF: Không thể tự khóa tài khoản của chính mình';
    end if;

    update public.profiles
    set is_locked = p_locked
    where id = p_target_user_id;

    return jsonb_build_object(
        'success', true,
        'user_id', p_target_user_id,
        'is_locked', p_locked
    );
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_update_app_config(p_min_version_code integer, p_latest_version_code integer, p_latest_version_name text, p_force_update boolean, p_title text DEFAULT NULL::text, p_message text DEFAULT NULL::text, p_store_url text DEFAULT NULL::text, p_title_vi text DEFAULT NULL::text, p_title_en text DEFAULT NULL::text, p_message_vi text DEFAULT NULL::text, p_message_en text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_caller_id uuid := auth.uid();
    v_caller_role text;
    v_config public.app_configs;
begin
    if v_caller_id is null then
        raise exception 'NOT_AUTHENTICATED';
    end if;

    select role into v_caller_role
    from public.profiles
    where id = v_caller_id;

    if v_caller_role is distinct from 'admin' then
        raise exception 'NOT_ADMIN';
    end if;

    if p_min_version_code < 1 or p_latest_version_code < p_min_version_code then
        raise exception 'INVALID_VERSION_RANGE';
    end if;

    if p_latest_version_name is null or trim(p_latest_version_name) = '' then
        raise exception 'INVALID_VERSION_NAME';
    end if;

    insert into public.app_configs (
        id,
        min_version_code,
        latest_version_code,
        latest_version_name,
        force_update,
        title,
        message,
        store_url,
        title_vi,
        title_en,
        message_vi,
        message_en,
        updated_at
    )
    values (
        'android_client',
        p_min_version_code,
        p_latest_version_code,
        trim(p_latest_version_name),
        p_force_update,
        coalesce(p_title, p_title_vi, p_title_en),
        coalesce(p_message, p_message_vi, p_message_en),
        p_store_url,
        p_title_vi,
        p_title_en,
        p_message_vi,
        p_message_en,
        now()
    )
    on conflict (id) do update set
        min_version_code = excluded.min_version_code,
        latest_version_code = excluded.latest_version_code,
        latest_version_name = excluded.latest_version_name,
        force_update = excluded.force_update,
        title = coalesce(excluded.title, p_title_vi, p_title_en),
        message = coalesce(excluded.message, p_message_vi, p_message_en),
        store_url = coalesce(excluded.store_url, public.app_configs.store_url),
        title_vi = excluded.title_vi,
        title_en = excluded.title_en,
        message_vi = excluded.message_vi,
        message_en = excluded.message_en,
        updated_at = now()
    returning * into v_config;

    return to_jsonb(v_config);
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_update_report_status(p_report_id uuid, p_resolved boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_caller_id uuid := auth.uid();
    v_caller_role text;
    v_report public.contact_reports;
begin
    if v_caller_id is null then
        raise exception 'NOT_AUTHENTICATED';
    end if;

    select role into v_caller_role
    from public.profiles
    where id = v_caller_id;

    if v_caller_role is distinct from 'admin' then
        raise exception 'NOT_ADMIN';
    end if;

    update public.contact_reports
    set status = case
        when p_resolved then 'resolved'
        when admin_reply is not null then 'replied'
        else 'new'
    end
    where id = p_report_id
    returning * into v_report;

    if v_report.id is null then
        raise exception 'REPORT_NOT_FOUND';
    end if;

    return to_jsonb(v_report);
end;
$function$;

CREATE OR REPLACE FUNCTION public.apply_daily_inactivity_penalty()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_yesterday date := ((now() at time zone 'Asia/Ho_Chi_Minh')::date) - 1;
    v_carry_policy public.daily_task_carryover_policies;
    v_earliest_unfinalized date;
    v_cur date;
begin
    v_carry_policy := public.get_daily_task_carryover_policy(v_yesterday);

    if v_carry_policy is not null and v_carry_policy.is_enabled then
        -- Tìm ngày chưa chốt sớm nhất (tối đa lùi 30 ngày)
        select min(d.dt::date) into v_earliest_unfinalized
        from generate_series(
            greatest(v_carry_policy.effective_from, v_yesterday - 30),
            v_yesterday,
            interval '1 day'
        ) d(dt)
        where exists (
            select 1 from public.profiles p
            where p.created_at < (d.dt::timestamp at time zone 'Asia/Ho_Chi_Minh')
              and not exists (
                  select 1 from public.user_daily_tasks t
                  where t.user_id = p.id
                    and t.task_date = d.dt::date
                    and t.finalized_at is not null
              )
        );

        if v_earliest_unfinalized is not null and v_earliest_unfinalized <= v_yesterday then
            v_cur := v_earliest_unfinalized;
            while v_cur <= v_yesterday loop
                perform public._apply_daily_inactivity_penalty(v_cur);
                v_cur := v_cur + 1;
            end loop;
            return;
        end if;
    end if;

    -- Mặc định chốt hôm qua
    perform public._apply_daily_inactivity_penalty(v_yesterday);
end;
$function$;

CREATE OR REPLACE FUNCTION public.apply_report_credit(p_report_id uuid, p_amount integer, p_action text DEFAULT ''::text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_caller uuid := auth.uid();
    v_role text;
    v_target uuid;
    v_owner uuid;
    v_current int;
    v_new int;
    v_actual int;
begin
    if v_caller is null then
        raise exception 'NOT_AUTHENTICATED';
    end if;

    select tr.user_id, c.owner_id
      into v_target, v_owner
    from public.tester_reports tr
    join public.campaigns c on c.id = tr.campaign_id
    where tr.id = p_report_id;

    if v_target is null then
        raise exception 'REPORT_NOT_FOUND';
    end if;

    select role into v_role
    from public.profiles
    where id = v_caller;

    if v_owner is distinct from v_caller
       and lower(coalesce(v_role, '')) not in ('admin', 'moderator') then
        raise exception 'PERMISSION_DENIED';
    end if;

    -- Khoá dòng profile mục tiêu: hai lượt cộng/trừ song song không mất cập nhật.
    select credits into v_current
    from public.profiles
    where id = v_target
    for update;

    if v_current is null then
        raise exception 'USER_NOT_FOUND';
    end if;

    v_new := greatest(v_current + p_amount, 0);
    -- Số tiền thực thay đổi (đã bị kẹp ở mức >= 0) — khớp với số dư mới.
    v_actual := v_new - v_current;

    update public.profiles
    set credits = v_new
    where id = v_target;

    insert into public.credit_logs (user_id, amount, action, note, balance)
    values (
        v_target,
        v_actual,
        coalesce(nullif(trim(p_action), ''), 'report_adjust'),
        p_note,
        v_new
    );

    return jsonb_build_object(
        'success', true,
        'user_id', v_target,
        'previous_credits', v_current,
        'new_credits', v_new,
        'amount', v_actual
    );
end;
$function$;

CREATE OR REPLACE FUNCTION public.approve_tester_report(p_report_id uuid, p_bonus integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_caller_id uuid := auth.uid();
    v_caller_role text;
    v_report record;
    v_camp record;
    v_extra_reward int := 2;
    v_tip int := 0;
    v_total_bonus int;
    v_new_balance int;
    v_owner_bonus int := 0;
    v_owner_balance int;
    v_is_owner boolean := false;
    v_today date := (now() at time zone 'Asia/Ho_Chi_Minh')::date;
begin
    if v_caller_id is null then
        raise exception 'NOT_AUTHENTICATED';
    end if;

    select * into v_report
    from public.tester_reports
    where id = p_report_id
    for update;

    if v_report.id is null then
        raise exception 'REPORT_NOT_FOUND';
    end if;

    if v_report.status <> 'pending' then
        raise exception 'REPORT_ALREADY_REVIEWED';
    end if;

    select * into v_camp
    from public.campaigns
    where id = v_report.campaign_id;

    select role into v_caller_role
    from public.profiles
    where id = v_caller_id;

    if v_camp.owner_id <> v_caller_id
       and lower(coalesce(v_caller_role, '')) not in ('admin', 'moderator') then
        raise exception 'PERMISSION_DENIED';
    end if;

    if v_report.created_at <= (now() - interval '8 hours') then
        raise exception 'REPORT_EXPIRED';
    end if;

    v_is_owner := (v_camp.owner_id = v_caller_id);

    insert into public.report_review_events (
        report_id, campaign_id, tester_id, owner_id, reviewer_id, event_type
    ) values (
        v_report.id, v_report.campaign_id, v_report.user_id,
        v_camp.owner_id, v_caller_id, 'approve'
    );

    v_tip := public._grant_report_tip(v_report.campaign_id, v_report.user_id);
    v_total_bonus := coalesce(v_report.bonus_awarded, 2) + v_extra_reward + v_tip;

    update public.tester_reports
    set status = 'approved',
        bonus_awarded = v_total_bonus,
        reviewed_at = now()
    where id = p_report_id;

    update public.profiles
    set credits = credits + v_extra_reward,
        last_active_date = v_today,
        missed_streak = 0
    where id = v_report.user_id
    returning credits into v_new_balance;

    insert into public.credit_logs (user_id, amount, action, note, balance)
    values (
        v_report.user_id,
        v_extra_reward,
        'test_approved_bonus',
        format(
            '%s duyệt kết quả kiểm thử (Thưởng thêm +%s Credit)',
            case when v_is_owner then 'Chủ app' else 'Admin/Moderator' end,
            v_extra_reward
        ),
        v_new_balance
    );

    if v_is_owner then
        v_owner_bonus := 2;
        update public.profiles
        set credits = credits + v_owner_bonus
        where id = v_camp.owner_id
        returning credits into v_owner_balance;

        insert into public.credit_logs (user_id, amount, action, note, balance)
        values (
            v_camp.owner_id,
            v_owner_bonus,
            'owner_approval_bonus',
            format('Duyệt báo cáo kiểm thử (+%s Credit)', v_owner_bonus),
            v_owner_balance
        );
    end if;

    -- M03: Chuyển p_report_id sang helper settlement
    perform public._settle_mission_reward(v_report.id);

    update public.checkins
    set note = 'Đã kiểm thử và được duyệt'
    where campaign_id = v_report.campaign_id
      and user_id = v_report.user_id
      and checkin_date = (v_report.created_at at time zone 'Asia/Ho_Chi_Minh')::date;

    if not found then
        insert into public.checkins (campaign_id, user_id, checkin_date, note)
        values (v_report.campaign_id, v_report.user_id, v_today, 'Đã kiểm thử và được duyệt')
        on conflict (campaign_id, user_id, checkin_date)
        do update set note = 'Đã kiểm thử và được duyệt';
    end if;

    return jsonb_build_object(
        'success', true,
        'report_id', p_report_id,
        'tester_id', v_report.user_id,
        'status', 'approved',
        'credits_awarded', v_extra_reward,
        'tip_awarded', v_tip,
        'owner_credits_awarded', v_owner_bonus,
        'total_earned', v_total_bonus,
        'tester_balance', v_new_balance,
        'owner_balance', v_owner_balance,
        'message', format(
            'Duyệt kết quả thành công (Thưởng thêm +%s Credit cho tester%s)',
            v_extra_reward,
            case when v_owner_bonus > 0 then format(' và +%s Credit cho bạn', v_owner_bonus) else '' end
        )
    );
end;
$function$;

CREATE OR REPLACE FUNCTION public.archive_campaign_before_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_reason text;
    v_target_days int;
begin
    v_reason := coalesce(
        nullif(current_setting('app.delete_reason', true), ''),
        'unknown'
    );
    v_target_days := coalesce(old.target_days, 14);

    insert into public.campaign_archive (
        campaign_id,
        owner_id,
        app_name,
        package_name,
        campaign_status,
        target_testers,
        target_days,
        created_at,
        completed_at,
        member_count,
        completed_tester_count,
        checkin_count,
        feedback_count,
        report_count,
        avg_rating,
        archived_reason
    )
    values (
        old.id,
        old.owner_id,
        old.app_name,
        old.package_name,
        old.status,
        old.target_testers,
        old.target_days,
        old.created_at,
        coalesce(old.completed_at, old.created_at),
        (select count(*) from public.campaign_members m where m.campaign_id = old.id),
        (
            select count(*)
            from (
                select ci.user_id
                from public.checkins ci
                where ci.campaign_id = old.id
                group by ci.user_id
                having count(*) >= v_target_days
            ) completed
        ),
        (select count(*) from public.checkins ci where ci.campaign_id = old.id),
        (select count(*) from public.feedbacks f where f.campaign_id = old.id),
        (select count(*) from public.tester_reports tr where tr.campaign_id = old.id),
        (select round(avg(f.rating), 2) from public.feedbacks f where f.campaign_id = old.id),
        v_reason
    )
    on conflict (campaign_id) do nothing;

    return old;
end;
$function$;

CREATE OR REPLACE FUNCTION public.audit_daily_task_policy()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
    insert into public.daily_task_policy_changes (
        policy_id, operation, old_row, new_row, operator_note, invoked_role, actor_id
    ) values (
        case when tg_op = 'DELETE' then old.id else new.id end,
        tg_op,
        case when tg_op in ('UPDATE', 'DELETE') then to_jsonb(old) end,
        case when tg_op in ('INSERT', 'UPDATE') then to_jsonb(new) end,
        case when tg_op = 'DELETE' then old.operator_note else new.operator_note end,
        nullif(current_setting('role', true), 'none'),
        auth.uid()
    );
    return null;
end;
$function$;

CREATE OR REPLACE FUNCTION public.auto_accept_expired_reports()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_report record;
    v_count int := 0;
    v_retried int := 0;
    v_owner_id uuid;
    v_camp_name text;
    v_tip int;
    v_base int;
    v_total_bonus int;
begin
    perform set_config('app.suppress_report_notify', '1', true);

    for v_report in
        select id, campaign_id, user_id, created_at, bonus_awarded, provisional_granted_credits
        from public.tester_reports
        where status = 'pending'
          and created_at <= (now() - interval '8 hours')
        for update skip locked
    loop
        select owner_id, app_name into v_owner_id, v_camp_name
        from public.campaigns
        where id = v_report.campaign_id;

        v_tip := public._grant_report_tip(v_report.campaign_id, v_report.user_id);
        v_base := coalesce(
            nullif(v_report.provisional_granted_credits, 0),
            nullif(v_report.bonus_awarded, 0),
            0
        );
        v_total_bonus := coalesce(nullif(v_report.bonus_awarded, 0), v_base) + v_tip;

        update public.tester_reports
        set status = 'approved',
            bonus_awarded = v_total_bonus,
            reviewed_at = now()
        where id = v_report.id;

        insert into public.report_review_events (
            report_id, campaign_id, tester_id, owner_id, reviewer_id, event_type
        ) values (
            v_report.id, v_report.campaign_id, v_report.user_id,
            v_owner_id, null, 'auto_accept'
        );

        update public.checkins
        set note = 'Tự động duyệt sau 8h'
        where campaign_id = v_report.campaign_id
          and user_id = v_report.user_id
          and checkin_date = (v_report.created_at at time zone 'Asia/Ho_Chi_Minh')::date;

        if not found then
            insert into public.checkins (campaign_id, user_id, checkin_date, note)
            values (
                v_report.campaign_id, v_report.user_id,
                (v_report.created_at at time zone 'Asia/Ho_Chi_Minh')::date,
                'Tự động duyệt sau 8h'
            )
            on conflict (campaign_id, user_id, checkin_date)
            do update set note = 'Tự động duyệt sau 8h';
        end if;

        -- M03: Gọi settlement với report_id
        perform public._settle_mission_reward(v_report.id);

        insert into public.notifications (user_id, title, message, type, data)
        values (
            v_report.user_id,
            'Báo cáo kiểm thử tự động duyệt ⏱️',
            case
                when v_tip > 0 then
                    format('Báo cáo của bạn cho ứng dụng "%s" đã được hệ thống tự động duyệt sau 8 giờ (giữ nguyên %s Credit của lượt test này + %s Credit boa từ chủ app). Cảm ơn bạn!', coalesce(v_camp_name, 'ứng dụng'), v_base, v_tip)
                else
                    format('Báo cáo của bạn cho ứng dụng "%s" đã được hệ thống tự động duyệt sau 8 giờ (giữ nguyên %s Credit của lượt test này). Cảm ơn bạn!', coalesce(v_camp_name, 'ứng dụng'), v_base)
            end,
            'report',
            jsonb_build_object(
                'report_id', v_report.id,
                'campaign_id', v_report.campaign_id,
                'status', 'approved',
                'auto_accepted', true
            )
        );

        v_count := v_count + 1;
    end loop;

    -- M05: Tự động chạy retry các settlement job thất bại trong lượt quét định kỳ
    v_retried := public.retry_failed_mission_settlements(50);

    -- R06: Reset cờ suppress notification trước khi trả về
    perform set_config('app.suppress_report_notify', '0', true);

    return v_count + v_retried;
end;
$function$;

CREATE OR REPLACE FUNCTION public.auto_confirm_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
begin
    if new.email_confirmed_at is null then
        new.email_confirmed_at := now();
    end if;
    return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.cancel_daily_task_policy(p_effective_from date, p_operator_note text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
    v_policy public.daily_task_policies;
begin
    perform pg_advisory_xact_lock(hashtextextended('daily_task_policy_schedule', 0));
    if p_effective_from is null or not isfinite(p_effective_from)
       or p_effective_from <= (clock_timestamp() at time zone 'Asia/Ho_Chi_Minh')::date then
        raise exception 'DAILY_TASK_POLICY_FUTURE_DATE_REQUIRED';
    end if;
    if p_operator_note is null or length(btrim(p_operator_note)) not between 1 and 1000 then
        raise exception 'DAILY_TASK_POLICY_NOTE_REQUIRED';
    end if;
    -- Preserve the cancellation reason in the DELETE audit, with a preceding
    -- UPDATE audit retaining the original note. Both changes are atomic.
    update public.daily_task_policies set operator_note = btrim(p_operator_note)
    where effective_from = p_effective_from returning * into v_policy;
    if not found then
        raise exception 'DAILY_TASK_POLICY_NOT_FOUND';
    end if;
    delete from public.daily_task_policies where id = v_policy.id;
    return to_jsonb(v_policy);
end;
$function$;

CREATE OR REPLACE FUNCTION public.check_campaign_slot_validity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    if new.status = 'open' then
        -- Slot 1 is always unlocked
        if new.slot_number > 1 then
            if not exists (
                select 1 from public.user_slots
                where user_id = new.owner_id
                  and slot_number = new.slot_number
                  and expires_at > now()
            ) then
                raise exception 'SLOT_NOT_ACTIVE_OR_EXPIRED';
            end if;
        end if;

        -- Prevent two open campaigns from using the same slot concurrently
        if exists (
            select 1 from public.campaigns
            where owner_id = new.owner_id
              and slot_number = new.slot_number
              and status = 'open'
              and id <> coalesce(new.id, '00000000-0000-0000-0000-000000000000'::uuid)
        ) then
            raise exception 'SLOT_ALREADY_IN_USE';
        end if;
    end if;
    return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.claim_app_update_reward(p_release_id uuid, p_observed_version_code bigint, p_client_operation_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_caller_id            uuid := auth.uid();
    v_rel                  public.app_update_releases%rowtype;
    v_camp                 public.campaigns%rowtype;
    v_member               public.campaign_members%rowtype;
    v_existing_claim       public.app_update_claims%rowtype;
    v_tester_is_locked     boolean := false;
    v_next_ordinal         int;
    v_new_paid_count       int;
    v_new_remaining        int;
    v_new_status           text;
    v_tester_credits       int;
    v_credit_log_id        uuid;
    v_claim_id             uuid;
    v_confirmed_at         timestamptz;
begin
    if v_caller_id is null then
        raise exception 'NOT_AUTHENTICATED';
    end if;

    if p_observed_version_code is null or p_observed_version_code <= 0 then
        raise exception 'INVALID_OBSERVED_VERSION_CODE';
    end if;

    -- Kiểm tra biên lai claim cũ dưới release_id và tester_id (Idempotency)
    select * into v_existing_claim
    from public.app_update_claims
    where release_id = p_release_id and tester_id = v_caller_id;

    if v_existing_claim.id is not null then
        select credits into v_tester_credits from public.profiles where id = v_caller_id;
        select * into v_rel from public.app_update_releases where id = p_release_id;

        return jsonb_build_object(
            'success', true,
            'newly_awarded', false,
            'reward', v_existing_claim.reward_credits,
            'tester_balance', v_tester_credits,
            'paid_count', v_rel.paid_count,
            'release_status', v_rel.status,
            'receipt', jsonb_build_object(
                'claim_id', v_existing_claim.id,
                'release_id', v_existing_claim.release_id,
                'ordinal', v_existing_claim.ordinal,
                'reward_credits', v_existing_claim.reward_credits,
                'confirmed_at', to_char(v_existing_claim.confirmed_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"')
            )
        );
    end if;

    -- R05: Khóa đợt cập nhật (FOR UPDATE)
    select * into v_rel from public.app_update_releases where id = p_release_id for update;
    if v_rel.id is null then
        raise exception 'RELEASE_NOT_FOUND';
    end if;

    -- Re-check claim sau khi đã có lock để tránh race condition giữa 2 request đồng thời
    select * into v_existing_claim
    from public.app_update_claims
    where release_id = p_release_id and tester_id = v_caller_id;

    if v_existing_claim.id is not null then
        select credits into v_tester_credits from public.profiles where id = v_caller_id;
        return jsonb_build_object(
            'success', true,
            'newly_awarded', false,
            'reward', v_existing_claim.reward_credits,
            'tester_balance', v_tester_credits,
            'paid_count', v_rel.paid_count,
            'release_status', v_rel.status,
            'receipt', jsonb_build_object(
                'claim_id', v_existing_claim.id,
                'release_id', v_existing_claim.release_id,
                'ordinal', v_existing_claim.ordinal,
                'reward_credits', v_existing_claim.reward_credits,
                'confirmed_at', to_char(v_existing_claim.confirmed_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"')
            )
        );
    end if;

    -- Kiểm tra trạng thái đợt
    if v_rel.status = 'superseded' then
        raise exception 'RELEASE_REPLACED';
    elsif v_rel.status = 'closed' then
        raise exception 'RELEASE_CLOSED';
    elsif v_rel.status = 'exhausted' or v_rel.paid_count >= v_rel.max_claims or v_rel.remaining_credits < v_rel.reward_per_claim then
        raise exception 'RELEASE_EXHAUSTED';
    elsif v_rel.status <> 'active' then
        raise exception 'RELEASE_NOT_ACTIVE';
    end if;

    -- Chủ app không thể tự claim nhận thưởng của chính app mình
    if coalesce(v_rel.owner_id, v_rel.owner_id_snapshot) = v_caller_id then
        raise exception 'OWNER_CANNOT_CLAIM';
    end if;

    -- Kiểm tra campaign
    select * into v_camp from public.campaigns where id = v_rel.campaign_id;
    if v_camp.id is null then
        raise exception 'CAMPAIGN_NOT_FOUND';
    end if;

    if v_camp.status <> 'open' then
        raise exception 'CAMPAIGN_NOT_OPEN';
    end if;

    -- Kiểm tra quyền thành viên và thời điểm tham gia
    select * into v_member
    from public.campaign_members
    where campaign_id = v_rel.campaign_id and user_id = v_caller_id;

    if v_member.campaign_id is null then
        raise exception 'NOT_A_MEMBER';
    end if;

    if v_member.joined_at > v_rel.published_at then
        raise exception 'MEMBER_JOINED_AFTER_RELEASE';
    end if;

    -- Kiểm tra phiên bản cài đặt thực tế
    if p_observed_version_code < v_rel.target_version_code then
        raise exception 'VERSION_NOT_SATISFIED';
    end if;

    -- Khóa ví tester
    select credits, coalesce(is_locked, false)
    into v_tester_credits, v_tester_is_locked
    from public.profiles
    where id = v_caller_id
    for update;

    if v_tester_is_locked then
        raise exception 'USER_LOCKED';
    end if;

    -- Tính toán ordinal và số dư quỹ mới
    v_next_ordinal := v_rel.paid_count + 1;
    v_new_paid_count := v_next_ordinal;
    v_new_remaining := v_rel.remaining_credits - v_rel.reward_per_claim;
    v_new_status := case
        when v_new_paid_count >= v_rel.max_claims or v_new_remaining < v_rel.reward_per_claim then 'exhausted'
        else 'active'
    end;

    update public.app_update_releases
    set paid_count = v_new_paid_count,
        remaining_credits = v_new_remaining,
        status = v_new_status,
        closed_at = case when v_new_status = 'exhausted' then now() else closed_at end
    where id = v_rel.id;

    -- R09: Nếu đợt đã exhausted, cập nhật control active_release_id về null
    if v_new_status = 'exhausted' then
        update public.app_update_controls
        set active_release_id = null,
            updated_at = now()
        where owner_id = coalesce(v_rel.owner_id, v_rel.owner_id_snapshot)
          and package_name = v_rel.package_name
          and active_release_id = v_rel.id;
    end if;

    -- Cộng 6 Credit cho tester (trích từ quỹ, KHÔNG trừ ví chủ)
    v_tester_credits := v_tester_credits + v_rel.reward_per_claim;
    update public.profiles set credits = v_tester_credits where id = v_caller_id;

    insert into public.credit_logs (user_id, amount, action, note, balance)
    values (
        v_caller_id,
        v_rel.reward_per_claim,
        'app_update_reward',
        format('Thưởng +%s Credit cập nhật phiên bản %s (%s)', v_rel.reward_per_claim, v_rel.version_name, v_rel.app_name),
        v_tester_credits
    )
    returning id into v_credit_log_id;

    -- Ghi nhận biên lai claim
    insert into public.app_update_claims (
        release_id,
        tester_id,
        ordinal,
        observed_version_code,
        reward_credits,
        confirmed_at,
        credit_log_id
    ) values (
        v_rel.id,
        v_caller_id,
        v_next_ordinal,
        p_observed_version_code,
        v_rel.reward_per_claim,
        now(),
        v_credit_log_id
    )
    returning id, confirmed_at into v_claim_id, v_confirmed_at;

    -- Ghi nhận financial event
    insert into public.app_update_financial_events (
        release_id, event_type, amount, owner_id, tester_id, credit_log_id, operation_id
    ) values (
        v_rel.id, 'reward', v_rel.reward_per_claim, coalesce(v_rel.owner_id, v_rel.owner_id_snapshot), v_caller_id, v_credit_log_id, p_client_operation_id
    );

    return jsonb_build_object(
        'success', true,
        'newly_awarded', true,
        'reward', v_rel.reward_per_claim,
        'tester_balance', v_tester_credits,
        'paid_count', v_new_paid_count,
        'release_status', v_new_status,
        'receipt', jsonb_build_object(
            'claim_id', v_claim_id,
            'release_id', v_rel.id,
            'ordinal', v_next_ordinal,
            'reward_credits', v_rel.reward_per_claim,
            'confirmed_at', to_char(v_confirmed_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"')
        )
    );
end;
$function$;

CREATE OR REPLACE FUNCTION public.claim_quest_reward(p_quest_type text, p_milestone integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_uid uuid := auth.uid();
    v_is_locked boolean := false;
    v_today date := (now() at time zone 'Asia/Ho_Chi_Minh')::date;
    v_week_start date := date_trunc('week', (now() at time zone 'Asia/Ho_Chi_Minh'))::date;
    v_period_key date;
    v_reward int := 0;
    v_current_count int := 0;
    v_new_balance int := 0;
begin
    if v_uid is null then
        return jsonb_build_object('success', false, 'error', 'NOT_AUTHENTICATED', 'message', 'Vui lòng đăng nhập để nhận thưởng.');
    end if;

    -- Kiểm tra tài khoản có bị khóa không
    select is_locked into v_is_locked from public.profiles where id = v_uid;
    if v_is_locked then
        return jsonb_build_object('success', false, 'error', 'ACCOUNT_LOCKED', 'message', 'Tài khoản của bạn đang bị tạm khóa.');
    end if;

    -- Kiểm tra tính hợp lệ của mốc và loại nhiệm vụ
    if p_quest_type = 'daily' then
        v_period_key := v_today;
        if p_milestone = 10 then
            v_reward := 5;
        elsif p_milestone = 20 then
            v_reward := 15;
        elsif p_milestone = 50 then
            v_reward := 30;
        else
            return jsonb_build_object('success', false, 'error', 'INVALID_MILESTONE', 'message', 'Mốc nhiệm vụ ngày không hợp lệ.');
        end if;

        -- Đếm số lượt checkin hôm nay
        select count(*) into v_current_count
        from public.checkins
        where user_id = v_uid and checkin_date = v_today;

    elsif p_quest_type = 'weekly' then
        v_period_key := v_week_start;
        if p_milestone = 150 then
            v_reward := 50;
        elsif p_milestone = 300 then
            v_reward := 100;
        else
            return jsonb_build_object('success', false, 'error', 'INVALID_MILESTONE', 'message', 'Mốc nhiệm vụ tuần không hợp lệ.');
        end if;

        -- Đếm số lượt checkin trong tuần này
        select count(*) into v_current_count
        from public.checkins
        where user_id = v_uid and checkin_date >= v_week_start and checkin_date <= v_today;

    else
        return jsonb_build_object('success', false, 'error', 'INVALID_QUEST_TYPE', 'message', 'Loại nhiệm vụ không hợp lệ.');
    end if;

    -- Kiểm tra xem người dùng đã đạt mốc chưa
    if v_current_count < p_milestone then
        return jsonb_build_object(
            'success', false,
            'error', 'MILESTONE_NOT_REACHED',
            'current_count', v_current_count,
            'milestone', p_milestone,
            'message', format('Bạn chưa hoàn thành mốc kiểm thử này (hiện tại %s/%s)!', v_current_count, p_milestone)
        );
    end if;

    -- Kiểm tra xem đã nhận thưởng mốc này trong chu kỳ chưa
    if exists (
        select 1 from public.user_quest_claims
        where user_id = v_uid and quest_type = p_quest_type and milestone = p_milestone and period_key = v_period_key
    ) then
        return jsonb_build_object(
            'success', false,
            'error', 'ALREADY_CLAIMED',
            'message', 'Bạn đã nhận phần thưởng này rồi!'
        );
    end if;

    -- Ghi nhận nhận thưởng
    insert into public.user_quest_claims (user_id, quest_type, milestone, reward_credits, period_key)
    values (v_uid, p_quest_type, p_milestone, v_reward, v_period_key);

    -- Cộng dồn Credit vào tài khoản
    update public.profiles
    set credits = credits + v_reward
    where id = v_uid
    returning credits into v_new_balance;

    -- Ghi nhật ký biến động số dư (Credit Log)
    insert into public.credit_logs (user_id, amount, action, note, balance)
    values (
        v_uid,
        v_reward,
        case when p_quest_type = 'daily' then 'quest_daily_reward' else 'quest_weekly_reward' end,
        case when p_quest_type = 'daily'
             then format('Thưởng hoàn thành nhiệm vụ ngày (Mốc %s lần test, +%s Credit)', p_milestone, v_reward)
             else format('Thưởng hoàn thành nhiệm vụ tuần (Mốc %s lần test, +%s Credit)', p_milestone, v_reward)
        end,
        v_new_balance
    );

    -- Tự động gửi thông báo chúc mừng
    insert into public.notifications (user_id, title, message, type)
    values (
        v_uid,
        case when p_quest_type = 'daily' then '🎉 Thưởng nhiệm vụ ngày!' else '🏆 Thưởng nhiệm vụ tuần!' end,
        case when p_quest_type = 'daily'
             then format('Chúc mừng bạn đã hoàn thành mốc test %s app hôm nay và nhận được +%s Credit!', p_milestone, v_reward)
             else format('Chúc mừng bạn đã hoàn thành mốc test %s app trong tuần này và nhận được +%s Credit!', p_milestone, v_reward)
        end,
        'credit'
    );

    return jsonb_build_object(
        'success', true,
        'quest_type', p_quest_type,
        'milestone', p_milestone,
        'reward', v_reward,
        'new_balance', v_new_balance,
        'message', format('Nhận thành công +%s Credit!', v_reward)
    );
end;
$function$;

CREATE OR REPLACE FUNCTION public.close_app_update_release(p_release_id uuid, p_reason text DEFAULT 'manual_close'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_caller_id       uuid := auth.uid();
    v_rel_lookup      record;
    v_rel             public.app_update_releases%rowtype;
    v_ctrl            record;
    v_camp            public.campaigns%rowtype;
    v_remaining       int;
    v_owner_credits   int;
    v_credit_log_id   uuid;
begin
    if v_caller_id is null then
        raise exception 'NOT_AUTHENTICATED';
    end if;

    -- Tra cứu nhanh để biết campaign và package
    select id, campaign_id, owner_id, owner_id_snapshot, package_name, status, remaining_credits
    into v_rel_lookup
    from public.app_update_releases
    where id = p_release_id;

    if v_rel_lookup.id is null then
        raise exception 'RELEASE_NOT_FOUND';
    end if;

    if coalesce(v_rel_lookup.owner_id, v_rel_lookup.owner_id_snapshot) <> v_caller_id then
        raise exception 'NOT_ACTUAL_OWNER';
    end if;

    -- R05: Khóa theo thứ tự 1 - campaigns (nếu có)
    if v_rel_lookup.campaign_id is not null then
        select * into v_camp from public.campaigns where id = v_rel_lookup.campaign_id for update;
    end if;

    -- R05: Khóa theo thứ tự 2 - app_update_controls
    select * into v_ctrl
    from public.app_update_controls
    where owner_id = v_caller_id and package_name = v_rel_lookup.package_name
    for update;

    -- R05: Khóa theo thứ tự 3 - app_update_releases
    select * into v_rel
    from public.app_update_releases
    where id = p_release_id
    for update;

    if v_rel.status <> 'active' then
        raise exception 'RELEASE_NOT_ACTIVE';
    end if;

    v_remaining := v_rel.remaining_credits;

    -- R05: Khóa theo thứ tự 4 - profiles
    select credits into v_owner_credits from public.profiles where id = v_caller_id for update;

    -- Đóng đợt
    update public.app_update_releases
    set status = 'closed',
        closed_at = now(),
        remaining_credits = 0,
        refunded_credits = refunded_credits + v_remaining
    where id = v_rel.id;

    -- R09: Cập nhật active_release_id về null
    update public.app_update_controls
    set active_release_id = null,
        updated_at = now()
    where owner_id = v_caller_id
      and package_name = v_rel.package_name
      and active_release_id = v_rel.id;

    -- Hoàn tiền cho chủ app nếu còn số dư chưa chi
    if v_remaining > 0 then
        v_owner_credits := v_owner_credits + v_remaining;
        update public.profiles set credits = v_owner_credits where id = v_caller_id;

        insert into public.credit_logs (user_id, amount, action, note, balance)
        values (
            v_caller_id,
            v_remaining,
            'app_update_refund',
            format('Hoàn %s Credit chưa dùng từ phiên bản %s (%s)', v_remaining, v_rel.version_name, v_rel.app_name),
            v_owner_credits
        )
        returning id into v_credit_log_id;

        insert into public.app_update_financial_events (
            release_id, event_type, amount, owner_id, credit_log_id
        ) values (
            v_rel.id, 'refund', v_remaining, v_caller_id, v_credit_log_id
        );
    end if;

    return jsonb_build_object(
        'success', true,
        'release_id', v_rel.id,
        'release_status', 'closed',
        'refund_amount', v_remaining,
        'owner_credits', v_owner_credits
    );
end;
$function$;

CREATE OR REPLACE FUNCTION public.complete_expired_campaigns()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    r record;
    v_count int := 0;
begin
    for r in
        update public.campaigns c
        set status = 'completed',
            completed_at = now()
        where c.status in ('open', 'paused')
          and c.created_at <= now() - interval '30 days'
        returning c.id, c.owner_id, c.app_name
    loop
        v_count := v_count + 1;

        insert into public.notifications (user_id, title, message, type, data)
        values (
            r.owner_id,
            'Ứng dụng đã hoàn thành kiểm thử ✅',
            format(
                'Ứng dụng "%s" đã hoàn thành thời gian hiển thị 30 ngày và được chuyển sang mục "Đã hoàn thành Kiểm thử" trên Trang chủ.',
                coalesce(nullif(r.app_name, ''), 'của bạn')
            ),
            'campaign',
            jsonb_build_object('campaign_id', r.id, 'reason', 'window_expired')
        );
    end loop;

    return v_count;
end;
$function$;

CREATE OR REPLACE FUNCTION public.create_mission(p_campaign_id uuid, p_title text, p_description text DEFAULT ''::text, p_max_participants integer DEFAULT 10, p_duration_days integer DEFAULT 3, p_reward_credits integer DEFAULT 10)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_user_id uuid := auth.uid();
    v_camp record;
    v_balance int;
    v_fee int;
    v_ends_at timestamptz;
    v_mission_id uuid;
begin
    if v_user_id is null then
        raise exception 'NOT_AUTHENTICATED';
    end if;

    if nullif(trim(coalesce(p_title, '')), '') is null then
        raise exception 'MISSION_TITLE_REQUIRED';
    end if;

    if p_max_participants is null or p_max_participants < 1 or p_max_participants > 50 then
        raise exception 'INVALID_PARTICIPANTS';
    end if;

    if p_duration_days is null or p_duration_days < 1 or p_duration_days > 7 then
        raise exception 'INVALID_DURATION';
    end if;

    if p_reward_credits is null or p_reward_credits < 10 then
        raise exception 'INVALID_REWARD';
    end if;

    -- Khóa campaign row để serialize các request tạo mission đồng thời
    select * into v_camp
    from public.campaigns
    where id = p_campaign_id
    for update;

    if v_camp.id is null then
        raise exception 'CAMPAIGN_NOT_FOUND';
    end if;

    if v_camp.owner_id <> v_user_id then
        raise exception 'PERMISSION_DENIED';
    end if;

    if v_camp.status <> 'open' then
        raise exception 'CAMPAIGN_NOT_OPEN';
    end if;

    -- M06: Đồng bộ mission hết hạn của campaign này dưới khóa trước khi kiểm tra trùng
    update public.missions
    set status = 'expired'
    where campaign_id = p_campaign_id
      and status in ('open', 'full', 'paused_by_creator')
      and ends_at <= now();

    -- M02: open, full, paused_by_creator đều chiếm vị trí nhiệm vụ
    if exists (
        select 1 from public.missions
        where campaign_id = p_campaign_id
          and status in ('open', 'full', 'paused_by_creator')
    ) then
        raise exception 'MISSION_ALREADY_EXISTS';
    end if;

    v_fee := 50 * p_duration_days;

    select credits into v_balance
    from public.profiles
    where id = v_user_id
    for update;

    if v_balance is null or v_balance < 300 then
        raise exception 'INSUFFICIENT_MIN_CREDITS';
    end if;

    if v_balance < v_fee then
        raise exception 'INSUFFICIENT_CREDITS';
    end if;

    v_ends_at := now() + make_interval(days => p_duration_days);

    insert into public.missions (
        creator_id, campaign_id, title, description,
        max_participants, duration_days, reward_credits, fee_credits,
        status, ends_at
    ) values (
        v_user_id, p_campaign_id, trim(p_title), coalesce(p_description, ''),
        p_max_participants, p_duration_days, p_reward_credits, v_fee,
        'open', v_ends_at
    )
    returning id into v_mission_id;

    update public.profiles
    set credits = credits - v_fee
    where id = v_user_id
    returning credits into v_balance;

    insert into public.credit_logs (user_id, amount, action, note, balance)
    values (
        v_user_id,
        -v_fee,
        'mission_fee',
        format('Mở nhiệm vụ "%s" (%s ngày × 50 Credit phí nền tảng)', trim(p_title), p_duration_days),
        v_balance
    );

    return jsonb_build_object(
        'success', true,
        'mission_id', v_mission_id,
        'fee', v_fee,
        'balance', v_balance,
        'ends_at', to_char(v_ends_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"')
    );
end;
$function$;

CREATE OR REPLACE FUNCTION public.delete_mission(p_mission_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_user_id uuid := auth.uid();
    v_mission record;
begin
    if v_user_id is null then
        raise exception 'NOT_AUTHENTICATED';
    end if;

    select * into v_mission
    from public.missions
    where id = p_mission_id
    for update;

    if v_mission.id is null or v_mission.status = 'deleted' then
        raise exception 'MISSION_NOT_FOUND';
    end if;

    if v_mission.creator_id <> v_user_id then
        raise exception 'PERMISSION_DENIED';
    end if;

    update public.missions
    set status = 'deleted'
    where id = p_mission_id;

    -- Người đã nhận nhưng chưa hoàn thành: báo nhiệm vụ bị xóa, mất cơ hội nhận thưởng.
    insert into public.notifications (user_id, title, message, type, data)
    select
        mp.user_id,
        'Nhiệm vụ đã bị xóa 🗑️',
        format('Nhiệm vụ "%s" đã được chủ nhiệm vụ xóa. Bạn không thể tiếp tục nhận thưởng từ nhiệm vụ này.',
               v_mission.title),
        'mission',
        jsonb_build_object('mission_id', p_mission_id, 'campaign_id', v_mission.campaign_id, 'deleted', true)
    from public.mission_participants mp
    where mp.mission_id = p_mission_id
      and mp.status = 'joined';

    return jsonb_build_object(
        'success', true,
        'mission_id', p_mission_id,
        'status', 'deleted'
    );
end;
$function$;

CREATE OR REPLACE FUNCTION public.dhash_hamming(p_a text, p_b text)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
AS $function$
    select case
        when p_a is null or p_b is null then 64
        when lower(p_a) !~ '^[0-9a-f]{16}$' or lower(p_b) !~ '^[0-9a-f]{16}$' then 64
        else length(
            replace(
                (
                    (('x' || lower(p_a))::bit(64))
                    #
                    (('x' || lower(p_b))::bit(64))
                )::text,
                '0',
                ''
            )
        )
    end;
$function$;

CREATE OR REPLACE FUNCTION public.finalize_daily_tasks_for_date(p_target_date date)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    if p_target_date is null then
        raise exception 'TARGET_DATE_REQUIRED';
    end if;
    perform public._apply_daily_inactivity_penalty(p_target_date);
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_campaign_detail(p_campaign_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_uid              uuid := auth.uid();
    v_today            date := (now() at time zone 'Asia/Ho_Chi_Minh')::date;
    v_camp             public.campaigns%rowtype;
    v_is_owner         boolean := false;
    v_is_actual_owner  boolean := false;
    v_can_manage       boolean := false;
    v_is_member        boolean := false;
    v_member_joined_at timestamptz;
    v_confirmed        boolean := false;
    v_campaign         jsonb;
    v_testers          jsonb := '[]'::jsonb;
    v_feedbacks        jsonb := '[]'::jsonb;
    v_reports          jsonb := '[]'::jsonb;
    v_profiles         jsonb := '{}'::jsonb;
    v_today_tested     int := 0;
    v_reports_count    int := 0;
    v_avg              float;
    v_my_dates         jsonb := '[]'::jsonb;
    v_my_profile       jsonb;
    v_unread           jsonb := '[]'::jsonb;
    v_weekly           int := 0;
    v_rel              record;
    v_app_update       jsonb := null;
    v_claim            record;
    v_is_eligible      boolean := true;
    v_ineligible_reason text := null;
begin
    if v_uid is null then
        raise exception 'NOT_AUTHENTICATED';
    end if;

    select * into v_camp from public.campaigns where id = p_campaign_id;
    if v_camp.id is null then
        raise exception 'CAMPAIGN_NOT_FOUND';
    end if;

    perform public.auto_accept_expired_reports();

    v_is_actual_owner := (v_camp.owner_id = v_uid);

    v_can_manage := v_is_actual_owner
        or exists (
            select 1 from public.profiles p
            where p.id = v_uid and lower(p.role) in ('admin', 'moderator')
        );

    v_is_owner := v_can_manage;

    select joined_at into v_member_joined_at
    from public.campaign_members m
    where m.campaign_id = p_campaign_id and m.user_id = v_uid;

    v_is_member := (v_member_joined_at is not null);

    v_confirmed := exists (
        select 1 from public.checkins ci
        where ci.campaign_id = p_campaign_id
          and ci.user_id = v_uid
          and ci.checkin_date = v_today
          and coalesce(ci.note, '') not like '%tạm tính%'
    );

    select coalesce(jsonb_agg(jsonb_build_object(
        'user_id', t.user_id,
        'joined_at', t.joined_at,
        'days', t.days,
        'checkin_count', t.checkin_count,
        'last_checkin_date', t.last_checkin_date
    ) order by t.days desc), '[]'::jsonb)
    into v_testers
    from (
        select m.user_id,
               to_char(m.joined_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"') as joined_at,
               coalesce(s.days, 0) as days,
               coalesce(s.cnt, 0) as checkin_count,
               to_char(s.last_date, 'YYYY-MM-DD') as last_checkin_date
        from public.campaign_members m
        left join (
            select user_id,
                   count(distinct checkin_date) as days,
                   count(*) as cnt,
                   max(checkin_date) as last_date
            from public.checkins
            where campaign_id = p_campaign_id
            group by user_id
        ) s on s.user_id = m.user_id
        where m.campaign_id = p_campaign_id
    ) t;

    select coalesce(jsonb_agg(jsonb_build_object(
        'id', f.id,
        'campaign_id', f.campaign_id,
        'user_id', f.user_id,
        'rating', f.rating,
        'comment', f.comment,
        'created_at', to_char(f.created_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
        'updated_at', to_char(f.updated_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"')
    ) order by f.created_at desc), '[]'::jsonb)
    into v_feedbacks
    from public.feedbacks f
    where f.campaign_id = p_campaign_id;

    select coalesce(jsonb_agg(jsonb_build_object(
        'id', tr.id,
        'campaign_id', tr.campaign_id,
        'user_id', tr.user_id,
        'report_type', tr.report_type,
        'content', tr.content,
        'screenshot_url', tr.screenshot_url,
        'thumbnail_url', tr.thumbnail_url,
        'rating', tr.rating,
        'status', tr.status,
        'bonus_awarded', tr.bonus_awarded,
        'created_at', to_char(tr.created_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
        'reviewed_at', to_char(tr.reviewed_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
        'rejection_reason', tr.rejection_reason,
        'image_hash', tr.image_hash,
        'submission_context', tr.submission_context,
        'mission_id', tr.mission_id,
        'mission_participant_id', tr.mission_participant_id,
        'mission_title', tr.mission_title,
        'mission_reward_credits', tr.mission_reward_credits,
        'mission_ends_at', to_char(tr.mission_ends_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
        'mission_submitted_at', to_char(tr.mission_submitted_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"')
    ) order by tr.created_at desc), '[]'::jsonb)
    into v_reports
    from (
        select * from public.tester_reports
        where campaign_id = p_campaign_id
          and (v_can_manage or user_id = v_uid)
        order by created_at desc
        limit 200
    ) tr;

    select coalesce(jsonb_object_agg(t.id::text, public._profile_json(p)), '{}'::jsonb)
    into v_profiles
    from public.profiles p
    join (
        select v_camp.owner_id as id
        union
        select m.user_id from public.campaign_members m where m.campaign_id = p_campaign_id
        union
        select f.user_id from public.feedbacks f where f.campaign_id = p_campaign_id
        union
        select tr.user_id from public.tester_reports tr
        where tr.campaign_id = p_campaign_id and (v_can_manage or tr.user_id = v_uid)
    ) t on t.id = p.id;

    select count(distinct user_id) into v_today_tested
    from public.checkins
    where campaign_id = p_campaign_id and checkin_date = v_today;

    select count(*), coalesce(round(avg(rating)::numeric, 1), 0.0)
    into v_reports_count, v_avg
    from public.feedbacks
    where campaign_id = p_campaign_id;

    select coalesce(jsonb_agg(to_char(ci.checkin_date, 'YYYY-MM-DD') order by ci.checkin_date asc), '[]'::jsonb)
    into v_my_dates
    from public.checkins ci
    where ci.campaign_id = p_campaign_id and ci.user_id = v_uid;

    v_campaign := row_to_json(v_camp);

    select public._profile_json(p) into v_my_profile
    from public.profiles p where p.id = v_uid;

    select coalesce(jsonb_agg(jsonb_build_object(
        'id', w.id,
        'user_id', w.user_id,
        'message', w.message,
        'warning_date', to_char(w.warning_date, 'YYYY-MM-DD'),
        'created_at', to_char(w.created_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
        'acknowledged', w.acknowledged
    ) order by w.created_at desc), '[]'::jsonb)
    into v_unread
    from public.user_warnings w
    where w.user_id = v_uid and w.acknowledged = false;

    select count(*) into v_weekly
    from public.user_warnings w
    where w.user_id = v_uid
      and (w.created_at at time zone 'Asia/Ho_Chi_Minh')::date >= (v_today - 6);

    -- =========================================================================
    -- R09: Tìm release cập nhật phiên bản
    -- =========================================================================
    select * into v_rel
    from public.app_update_releases
    where campaign_id = p_campaign_id and status in ('active', 'exhausted')
    order by published_at desc, target_version_code desc
    limit 1;

    if v_rel.id is not null then
        if v_is_actual_owner then
            -- Góc nhìn chủ app: hiển thị toàn bộ tiến độ, ngân sách đang giữ và đã chi
            v_app_update := jsonb_build_object(
                'id', v_rel.id,
                'campaign_id', v_rel.campaign_id,
                'owner_id', coalesce(v_rel.owner_id, v_rel.owner_id_snapshot),
                'package_name', v_rel.package_name,
                'app_name', v_rel.app_name,
                'version_name', v_rel.version_name,
                'target_version_code', v_rel.target_version_code,
                'release_notes', v_rel.release_notes,
                'status', v_rel.status,
                'reward_per_claim', v_rel.reward_per_claim,
                'max_claims', v_rel.max_claims,
                'reserved_credits', v_rel.reserved_credits,
                'paid_count', v_rel.paid_count,
                'remaining_credits', v_rel.remaining_credits,
                'spent_credits', v_rel.paid_count * v_rel.reward_per_claim,
                'published_at', to_char(v_rel.published_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"')
            );
        else
            -- Góc nhìn tester:
            -- Quy tắc: Nếu đã đủ 20 suất (paid_count >= 20) thì ẩn toàn bộ đối với tester
            if v_rel.paid_count < v_rel.max_claims and v_rel.remaining_credits >= v_rel.reward_per_claim then
                select * into v_claim
                from public.app_update_claims
                where release_id = v_rel.id and tester_id = v_uid;

                -- R07: Kiểm tra điều kiện tester
                if not v_is_member then
                    v_is_eligible := false;
                    v_ineligible_reason := 'not_member';
                elsif v_member_joined_at > v_rel.published_at then
                    v_is_eligible := false;
                    v_ineligible_reason := 'joined_after_release';
                elsif v_camp.status = 'paused' then
                    v_is_eligible := false;
                    v_ineligible_reason := 'campaign_paused';
                elsif v_camp.status <> 'open' then
                    v_is_eligible := false;
                    v_ineligible_reason := 'campaign_not_open';
                elsif exists (select 1 from public.profiles p where p.id = v_uid and coalesce(p.is_locked, false) = true) then
                    v_is_eligible := false;
                    v_ineligible_reason := 'user_locked';
                end if;

                v_app_update := jsonb_build_object(
                    'id', v_rel.id,
                    'campaign_id', v_rel.campaign_id,
                    'package_name', v_rel.package_name,
                    'app_name', v_rel.app_name,
                    'version_name', v_rel.version_name,
                    'target_version_code', v_rel.target_version_code,
                    'release_notes', v_rel.release_notes,
                    'status', v_rel.status,
                    'reward_per_claim', v_rel.reward_per_claim,
                    'max_claims', v_rel.max_claims,
                    'paid_count', v_rel.paid_count,
                    'has_claimed', (v_claim.id is not null),
                    'is_eligible', v_is_eligible,
                    'ineligibility_reason', v_ineligible_reason,
                    'claim_receipt', case when v_claim.id is not null then jsonb_build_object(
                        'claim_id', v_claim.id,
                        'release_id', v_claim.release_id,
                        'ordinal', v_claim.ordinal,
                        'reward_credits', v_claim.reward_credits,
                        'confirmed_at', to_char(v_claim.confirmed_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"')
                    ) else null end
                );
            end if;
        end if;
    end if;

    return jsonb_build_object(
        'campaign', v_campaign,
        'is_owner', v_is_owner,
        'is_actual_owner', v_is_actual_owner,
        'can_manage', v_can_manage,
        'is_member', v_is_member,
        'checked_in_confirmed_today', v_confirmed,
        'testers', v_testers,
        'feedbacks', v_feedbacks,
        'reports', v_reports,
        'profiles', v_profiles,
        'today_tested_count', v_today_tested,
        'reports_count', v_reports_count,
        'avg_rating', v_avg,
        'my_checkin_dates', v_my_dates,
        'my_profile', v_my_profile,
        'unread_warnings', v_unread,
        'weekly_warnings_count', v_weekly,
        'app_update', v_app_update
    );
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_campaign_mission(p_campaign_id uuid, p_mission_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_user_id uuid := auth.uid();
    v_row record;
begin
    if p_mission_id is not null then
        select
            m.id, m.title, m.description, m.reward_credits,
            m.max_participants, m.participant_count, m.status,
            m.ends_at, m.created_at, m.campaign_id, m.creator_id,
            c.app_name, c.icon_url, c.package_name,
            coalesce(nullif(p.display_name, ''), split_part(coalesce(p.email, ''), '@', 1), '') as creator_name
        into v_row
        from public.missions m
        join public.campaigns c on c.id = m.campaign_id
        left join public.profiles p on p.id = m.creator_id
        where m.id = p_mission_id
          and m.campaign_id = p_campaign_id
          and m.status <> 'deleted'
        limit 1;
    else
        select
            m.id, m.title, m.description, m.reward_credits,
            m.max_participants, m.participant_count, m.status,
            m.ends_at, m.created_at, m.campaign_id, m.creator_id,
            c.app_name, c.icon_url, c.package_name,
            coalesce(nullif(p.display_name, ''), split_part(coalesce(p.email, ''), '@', 1), '') as creator_name
        into v_row
        from public.missions m
        join public.campaigns c on c.id = m.campaign_id
        left join public.profiles p on p.id = m.creator_id
        where m.campaign_id = p_campaign_id
          and m.status <> 'deleted'
        order by m.created_at desc
        limit 1;
    end if;

    if v_row.id is null then
        return jsonb_build_object('mission', null);
    end if;

    return jsonb_build_object(
        'mission', jsonb_build_object(
            'id', v_row.id,
            'title', v_row.title,
            'description', v_row.description,
            'reward_credits', v_row.reward_credits,
            'max_participants', v_row.max_participants,
            'participant_count', v_row.participant_count,
            'status', v_row.status,
            'ends_at', to_char(v_row.ends_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
            'created_at', to_char(v_row.created_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
            'campaign_id', v_row.campaign_id,
            'app_name', v_row.app_name,
            'icon_url', v_row.icon_url,
            'package_name', v_row.package_name,
            'creator_id', v_row.creator_id,
            'creator_name', v_row.creator_name,
            'is_mine', v_row.creator_id = v_user_id,
            'has_joined', exists (
                select 1 from public.mission_participants mp2
                where mp2.mission_id = v_row.id and mp2.user_id = v_user_id
            ),
            'has_completed', exists (
                select 1 from public.mission_participants mp3
                where mp3.mission_id = v_row.id and mp3.user_id = v_user_id
                  and mp3.status = 'completed'
            )
        )
    );
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_campaign_reports_for_owner(p_campaign_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_caller_id uuid := auth.uid();
    v_camp record;
    v_role text;
    v_res jsonb;
begin
    if v_caller_id is null then
        raise exception 'NOT_AUTHENTICATED';
    end if;

    select * into v_camp from public.campaigns where id = p_campaign_id;
    if v_camp.id is null then
        raise exception 'CAMPAIGN_NOT_FOUND';
    end if;

    select role into v_role from public.profiles where id = v_caller_id;

    if v_camp.owner_id <> v_caller_id
       and lower(coalesce(v_role, '')) not in ('admin', 'moderator') then
        raise exception 'PERMISSION_DENIED';
    end if;

    perform public.auto_accept_expired_reports();

    select coalesce(
        jsonb_agg(
            jsonb_build_object(
                'id', tr.id,
                'campaign_id', tr.campaign_id,
                'user_id', tr.user_id,
                'report_type', tr.report_type,
                'content', tr.content,
                'screenshot_url', tr.screenshot_url,
                'thumbnail_url', tr.thumbnail_url,
                'rating', tr.rating,
                'status', tr.status,
                'bonus_awarded', tr.bonus_awarded,
                'created_at', to_char(tr.created_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
                'reviewed_at', to_char(tr.reviewed_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
                'rejection_reason', tr.rejection_reason,
                'image_hash', tr.image_hash,
                'tester_name', coalesce(p.display_name, split_part(coalesce(p.email, ''), '@', 1), 'Tester'),
                'tester_avatar', p.avatar_url,
                'tester_credits', p.credits,
                'submission_context', tr.submission_context,
                'mission_id', tr.mission_id,
                'mission_participant_id', tr.mission_participant_id,
                'mission_title', tr.mission_title,
                'mission_reward_credits', tr.mission_reward_credits,
                'mission_ends_at', to_char(tr.mission_ends_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
                'mission_submitted_at', to_char(tr.mission_submitted_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"')
            )
            order by tr.created_at desc
        ),
        '[]'::jsonb
    ) into v_res
    from public.tester_reports tr
    left join public.profiles p on p.id = tr.user_id
    where tr.campaign_id = p_campaign_id;

    return v_res;
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_campaign_update_history(p_campaign_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_caller_id  uuid := auth.uid();
    v_camp       record;
    v_can_manage boolean := false;
    v_history    jsonb := '[]'::jsonb;
begin
    if v_caller_id is null then
        raise exception 'NOT_AUTHENTICATED';
    end if;

    select owner_id into v_camp from public.campaigns where id = p_campaign_id;
    if v_camp.owner_id is null then
        raise exception 'CAMPAIGN_NOT_FOUND';
    end if;

    v_can_manage := (v_camp.owner_id = v_caller_id)
        or exists (
            select 1 from public.profiles p
            where p.id = v_caller_id and lower(p.role) in ('admin', 'moderator')
        );

    if not v_can_manage then
        raise exception 'FORBIDDEN';
    end if;

    select coalesce(jsonb_agg(jsonb_build_object(
        'id', r.id,
        'campaign_id', r.campaign_id,
        'owner_id', r.owner_id,
        'package_name', r.package_name,
        'app_name', r.app_name,
        'version_name', r.version_name,
        'target_version_code', r.target_version_code,
        'release_notes', r.release_notes,
        'status', r.status,
        'reward_per_claim', r.reward_per_claim,
        'max_claims', r.max_claims,
        'reserved_credits', r.reserved_credits,
        'paid_count', r.paid_count,
        'remaining_credits', r.remaining_credits,
        'refunded_credits', r.refunded_credits,
        'spent_credits', r.paid_count * r.reward_per_claim,
        'published_at', to_char(r.published_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
        'closed_at', case when r.closed_at is not null then to_char(r.closed_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"') else null end
    ) order by r.published_at desc), '[]'::jsonb)
    into v_history
    from public.app_update_releases r
    where r.campaign_id = p_campaign_id;

    return v_history;
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_campaigns_stats(p_campaign_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_uid uuid := auth.uid();
    v_today date := (clock_timestamp() at time zone 'Asia/Ho_Chi_Minh')::date;
    v_period_start date;
begin
    if p_campaign_ids is null or array_length(p_campaign_ids, 1) is null then
        return '{}'::jsonb;
    end if;

    select period_start into v_period_start from public._get_home_stats_period(v_today);

    return (
        select coalesce(jsonb_object_agg(cid::text, jsonb_build_object(
            'installed_count', coalesce(t.installed, 0),
            'today_tested_count', coalesce(t.today_tested, 0),
            'has_tested_today', coalesce(t.has_tested, false),
            'home_tested_count', coalesce(t.home_tested, 0),
            'stats_date', v_today::text
        )), '{}'::jsonb)
        from unnest(p_campaign_ids) as cid
        left join (
            select c.id,
                (select count(*) from public.campaign_members m where m.campaign_id = c.id) as installed,
                (select count(distinct ci.user_id) from public.checkins ci
                  where ci.campaign_id = c.id and ci.checkin_date = v_today) as today_tested,
                (select count(*) from public.checkins ci_period
                  where ci_period.campaign_id = c.id
                    and ci_period.checkin_date >= v_period_start
                    and ci_period.checkin_date <= v_today) as home_tested,
                (v_uid is not null and (
                    exists (select 1 from public.checkins ci2
                            where ci2.campaign_id = c.id and ci2.user_id = v_uid and ci2.checkin_date = v_today)
                    or exists (select 1 from public.tester_reports tr
                               where tr.campaign_id = c.id and tr.user_id = v_uid
                                 and tr.status <> 'rejected'
                                 and (tr.created_at at time zone 'Asia/Ho_Chi_Minh')::date = v_today)
                )) as has_tested
            from public.campaigns c
            where c.id = any(p_campaign_ids)
        ) t on t.id = cid
    );
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_daily_task_carryover_policy(p_date date)
 RETURNS daily_task_carryover_policies
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_row public.daily_task_carryover_policies;
begin
    if p_date is null then
        return null;
    end if;
    select *
    into v_row
    from public.daily_task_carryover_policies
    where effective_from <= p_date
    order by effective_from desc
    limit 1;
    return v_row;
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_daily_task_policy(p_date date)
 RETURNS daily_task_policies
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_policy public.daily_task_policies;
begin
    if p_date is null or not isfinite(p_date) then
        raise exception 'DAILY_TASK_POLICY_INVALID_DATE';
    end if;
    if not exists (
        select 1 from public.daily_task_policies where effective_from = date '-infinity'
    ) then
        raise exception 'DAILY_TASK_POLICY_BASELINE_MISSING';
    end if;
    select p.* into v_policy
    from public.daily_task_policies p
    where p.effective_from <= p_date
    order by p.effective_from desc limit 1;
    if not found then
        raise exception 'DAILY_TASK_POLICY_NOT_FOUND';
    end if;
    return v_policy;
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_daily_task_status(p_user_id uuid, p_date date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_policy public.daily_task_policies;
    v_carry_policy public.daily_task_carryover_policies;
    v_role text;
    v_last_login date;
    v_streak int := 0;
    v_exempt boolean := false;
    v_k int := 0;
    v_a int := 0;
    v_d int := 0;
    v_base_required int := 0;
    v_carry_in int := 0;
    v_required int := 0;
    v_effective int := 0;
    v_logged_in boolean := false;
    v_met boolean := false;
    v_next_pct int := 1;
    v_mode text;
    v_day_start timestamptz;
    v_next_day_start timestamptz;
    v_window_start timestamptz;
    v_carryover_ready boolean := true;
    v_carry_remaining int := 0;
    v_carry_effective_from date := null;
    v_prev_finalized timestamptz;
    v_prev_carry_out int;
    v_last_carry_out int;
    v_q int := 0;
    v_first_policy_effective date;
    v_has_prior_history boolean := false;
begin
    if p_user_id is null or p_date is null then
        return null;
    end if;

    select lower(p.role), p.last_login_date, p.daily_missed_streak
    into v_role, v_last_login, v_streak
    from public.profiles p
    where p.id = p_user_id;

    if not found then
        return null;
    end if;

    v_streak := coalesce(v_streak, 0);
    v_exempt := coalesce(v_role in ('admin', 'moderator'), false);

    v_day_start := (p_date::timestamp at time zone 'Asia/Ho_Chi_Minh');
    v_next_day_start := ((p_date + 1)::timestamp at time zone 'Asia/Ho_Chi_Minh');
    v_window_start := ((p_date - 30)::timestamp at time zone 'Asia/Ho_Chi_Minh');

    -- R02: Tái dựng K chính xác: App được tính cho ngày p_date nếu được tạo trước v_day_start
    -- và trong khoảng [v_day_start, v_next_day_start] chưa bị completed/production.
    -- Nếu hiện tại completed nhưng completed_at >= v_next_day_start thì vào ngày p_date app vẫn active!
    select count(*) into v_k
    from public.campaigns c
    where c.owner_id = p_user_id
      and c.created_at < v_day_start
      and c.created_at > v_window_start
      and (
          c.status = 'open'
          or (c.status = 'paused' and c.paused_reason = 'owner_inactive')
          or (c.completed_at is not null and c.completed_at >= v_next_day_start)
      );

    -- R02: Tái dựng A chính xác: App open của người khác trong ngày p_date
    select count(*) into v_a
    from public.campaigns c
    where c.owner_id <> p_user_id
      and c.created_at < v_next_day_start
      and c.created_at > v_window_start
      and (
          c.status = 'open'
          or (c.completed_at is not null and c.completed_at >= v_next_day_start)
      );

    -- D: số app khác nhau user đã test trong ngày p_date
    select count(distinct campaign_id) into v_d
    from (
        select ci.campaign_id
        from public.checkins ci
        join public.campaigns c on c.id = ci.campaign_id
        where ci.user_id = p_user_id
          and ci.checkin_date = p_date
          and c.owner_id <> p_user_id
          and (
              ci.note is null
              or (
                  ci.note not like 'Đã kiểm thử%'
                  and ci.note not like 'Đã nộp kết quả%'
                  and ci.note not like '%tạm tính%'
                  and ci.note not like 'Tự động duyệt%'
                  and ci.note not like '%Tự động duyệt%'
                  and ci.note not like '%chủ app duyệt%'
              )
          )

        union

        select tr.campaign_id
        from public.tester_reports tr
        join public.campaigns c on c.id = tr.campaign_id
        where tr.user_id = p_user_id
          and (tr.created_at at time zone 'Asia/Ho_Chi_Minh')::date = p_date
          and tr.status in ('pending', 'approved')
          and c.owner_id <> p_user_id
    ) t;

    -- Login lấy từ lịch sử theo ngày hoặc profile
    select (v_last_login = p_date) or exists (
        select 1
        from public.user_daily_tasks t
        where t.user_id = p_user_id
          and t.task_date = p_date
          and t.logged_in = true
    ) into v_logged_in;

    v_policy := public.get_daily_task_policy(p_date);
    v_base_required := coalesce(v_policy.tests_per_active_app, 3) * v_k;
    v_mode := case when v_k > 0 then 'owner' else 'member' end;

    -- Tính toán phần thiếu chuyển tiếp (Carryover)
    v_carry_policy := public.get_daily_task_carryover_policy(p_date);

    if v_carry_policy is not null and v_carry_policy.is_enabled and p_date >= v_carry_policy.effective_from then
        v_carry_effective_from := v_carry_policy.effective_from;

        -- Tìm ngày kích hoạt lần đầu của hệ thống
        select min(effective_from) into v_first_policy_effective
        from public.daily_task_carryover_policies
        where is_enabled = true;

        -- Tìm xem user đã từng có row carryover nào đã finalized trước đó hay chưa (kể cả trước khi policy bị tắt)
        select t.carry_out_tests into v_last_carry_out
        from public.user_daily_tasks t
        where t.user_id = p_user_id
          and t.task_date < p_date
          and t.finalized_at is not null
          and t.carryover_version is not null
        order by t.task_date desc
        limit 1;

        v_has_prior_history := (v_last_carry_out is not null);

        if p_date = v_carry_effective_from and not v_has_prior_history then
            -- Chỉ ngày kích hoạt đầu tiên của hệ thống mới bắt đầu C = 0
            v_carry_in := 0;
            v_carryover_ready := true;
        elsif p_date = v_carry_effective_from and v_has_prior_history then
            -- Bật lại chính sách sau một khoảng thời gian tắt: nối tiếp checkpoint nợ cũ đã bảo lưu
            v_carry_in := coalesce(v_last_carry_out, 0);
            v_carryover_ready := true;
        else
            -- p_date > effective_from: nguồn bắt buộc phải từ ngày liền trước (p_date - 1)
            select t.finalized_at, t.carry_out_tests
            into v_prev_finalized, v_prev_carry_out
            from public.user_daily_tasks t
            where t.user_id = p_user_id and t.task_date = (p_date - 1);

            if v_prev_finalized is not null then
                v_carry_in := coalesce(v_prev_carry_out, 0);
                v_carryover_ready := true;
            else
                -- Ngày hôm qua chưa finalized -> nguồn chưa sẵn sàng
                v_carryover_ready := false;
                v_carry_in := 0;
            end if;
        end if;
    else
        -- Chính sách cộng dồn chưa có hiệu lực hoặc đang bị tắt
        v_carry_in := 0;
        v_carryover_ready := true;
        v_carry_effective_from := null;
    end if;

    -- R01: Tách trạng thái member hoàn thành bằng đăng nhập khỏi điều kiện đủ nguồn chốt ledger
    if v_carryover_ready then
        if v_exempt then
            v_required := v_base_required + v_carry_in;
            v_effective := least(v_required, v_a);
            v_carry_remaining := greatest(0, v_carry_in - v_d);
            v_met := true;
        elsif v_mode = 'member' then
            v_required := 0;
            v_effective := 0;
            v_carry_remaining := greatest(0, v_carry_in - v_d);
            v_met := v_logged_in or v_d > 0;
        else
            -- mode = 'owner'
            v_required := v_base_required + v_carry_in;
            v_effective := least(v_required, v_a);
            v_q := greatest(v_carry_in, v_effective);
            v_carry_remaining := greatest(0, v_q - v_d);
            v_met := (v_d >= v_effective);
        end if;
    else
        -- Khi pending:
        if v_mode = 'member' then
            -- Member vẫn thấy mình hoàn thành nhiệm vụ đăng nhập trên UI
            v_required := 0;
            v_effective := 0;
            v_carry_remaining := 0;
            v_met := v_logged_in or v_d > 0;
        else
            -- Owner: nhiệm vụ chưa xác định, met = false
            v_required := v_base_required;
            v_effective := least(v_required, v_a);
            v_carry_remaining := 0;
            v_met := false;
        end if;
    end if;

    v_next_pct := case
        when v_streak <= 0 then 1
        when v_streak = 1 then 2
        when v_streak = 2 then 5
        else 10
    end;

    return jsonb_build_object(
        'status_date', to_char(p_date, 'YYYY-MM-DD'),
        'mode', v_mode,
        'active_app_count', v_k,
        'required_tests', v_required,
        'available_apps', v_a,
        'effective_required_tests', v_effective,
        'completed_tests', v_d,
        'logged_in_today', v_logged_in,
        'is_penalty_exempt', v_exempt,
        'missed_streak', v_streak,
        'next_penalty_percent', v_next_pct,
        'met', v_met,
        'base_required_tests', v_base_required,
        'carry_in_tests', v_carry_in,
        'carryover_remaining_tests', coalesce(v_carry_remaining, 0),
        'carryover_ready', v_carryover_ready,
        'carryover_effective_from', case when v_carry_effective_from is not null then to_char(v_carry_effective_from, 'YYYY-MM-DD') else null end
    );
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_home_feed()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_uid uuid := auth.uid();
    v_today date := (clock_timestamp() at time zone 'Asia/Ho_Chi_Minh')::date;
    v_period_start date;
    v_open jsonb := '[]'::jsonb;
    v_paused jsonb := '[]'::jsonb;
    v_completed jsonb := '[]'::jsonb;
    v_owner_names jsonb := '{}'::jsonb;
    v_stats jsonb := '{}'::jsonb;
begin
    select coalesce(jsonb_agg(public._campaign_json(c) order by c.created_at desc), '[]'::jsonb)
    into v_open
    from public.campaigns c
    where c.status = 'open';

    if v_uid is not null then
        select coalesce(jsonb_agg(public._campaign_json(c) order by c.created_at desc), '[]'::jsonb)
        into v_paused
        from public.campaigns c
        where c.status = 'paused';

        select coalesce(jsonb_agg(public._campaign_json(c) order by c.created_at desc), '[]'::jsonb)
        into v_completed
        from public.campaigns c
        where c.status in ('production', 'completed');
    end if;

    select coalesce(jsonb_object_agg(t.owner_id::text, t.name), '{}'::jsonb)
    into v_owner_names
    from (
        select distinct c.owner_id,
               coalesce(nullif(p.display_name, ''), split_part(coalesce(p.email, ''), '@', 1), 'Chủ app') as name
        from public.campaigns c
        left join public.profiles p on p.id = c.owner_id
        where c.status = 'open'
           or (v_uid is not null and c.status in ('paused', 'production', 'completed'))
    ) t;

    -- Xác định mốc đầu chu kỳ hiện tại
    select period_start into v_period_start from public._get_home_stats_period(v_today);

    select coalesce(jsonb_object_agg(s.id::text, jsonb_build_object(
        'installed_count', coalesce(s.installed_count, 0),
        'today_tested_count', coalesce(s.today_tested_count, 0),
        'has_tested_today', coalesce(s.has_tested_today, false),
        'home_tested_count', coalesce(s.home_tested_count, 0),
        'stats_date', v_today::text
    )), '{}'::jsonb)
    into v_stats
    from (
        select c.id,
            (select count(*) from public.campaign_members m where m.campaign_id = c.id) as installed_count,
            (select count(distinct ci.user_id) from public.checkins ci
              where ci.campaign_id = c.id and ci.checkin_date = v_today) as today_tested_count,
            (select count(*) from public.checkins ci_period
              where ci_period.campaign_id = c.id
                and ci_period.checkin_date >= v_period_start
                and ci_period.checkin_date <= v_today) as home_tested_count,
            (v_uid is not null and (
                exists (select 1 from public.checkins ci2
                        where ci2.campaign_id = c.id and ci2.user_id = v_uid and ci2.checkin_date = v_today)
                or exists (select 1 from public.tester_reports tr
                           where tr.campaign_id = c.id and tr.user_id = v_uid
                             and tr.status <> 'rejected'
                             and (tr.created_at at time zone 'Asia/Ho_Chi_Minh')::date = v_today)
            )) as has_tested_today
        from public.campaigns c
        where c.status = 'open'
           or (v_uid is not null and c.status in ('paused', 'production', 'completed'))
    ) s;

    return jsonb_build_object(
        'open', v_open,
        'paused', v_paused,
        'completed', v_completed,
        'owner_names', v_owner_names,
        'stats', v_stats
    );
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_leaderboard_v2(p_limit integer DEFAULT 100, p_sort text DEFAULT 'credit'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_limit int := greatest(1, least(coalesce(p_limit, 100), 200));
    v_result jsonb := '[]'::jsonb;
begin
    if coalesce(p_sort, 'credit') = 'test' then
        -- Top Test: tổng lượt test toàn thời gian, tie-break theo credits rồi số app.
        select coalesce(jsonb_agg(jsonb_build_object(
            'userId', t.id,
            'displayName', t.name,
            'avatarUrl', t.avatar_url,
            'credits', t.credits,
            'checkinCount', t.checkin_count,
            'campaignsCount', t.campaigns_count,
            'rank', t.rn
        ) order by t.rn), '[]'::jsonb)
        into v_result
        from (
            select b.*, row_number() over (order by b.checkin_count desc, b.credits desc, b.campaigns_count desc) as rn
            from (
                select x.*
                from (
                    select p.id,
                           coalesce(nullif(p.display_name, ''), split_part(coalesce(p.email, ''), '@', 1), 'Tester') as name,
                           p.avatar_url,
                           p.credits,
                           (select count(*) from public.checkins ci where ci.user_id = p.id) as checkin_count,
                           (select count(distinct ci.campaign_id) from public.checkins ci where ci.user_id = p.id) as campaigns_count
                    from public.profiles p
                ) x
                where x.checkin_count > 0
                order by x.checkin_count desc, x.credits desc, x.campaigns_count desc
                limit v_limit
            ) b
        ) t;
    else
        -- Top Credit: giữ nguyên thuật toán cũ.
        select coalesce(jsonb_agg(jsonb_build_object(
            'userId', t.id,
            'displayName', t.name,
            'avatarUrl', t.avatar_url,
            'credits', t.credits,
            'checkinCount', t.checkin_count,
            'campaignsCount', t.campaigns_count,
            'rank', t.rn
        ) order by t.rn), '[]'::jsonb)
        into v_result
        from (
            select b.*, row_number() over (order by b.credits desc, b.checkin_count desc, b.campaigns_count desc) as rn
            from (
                select p.id,
                       coalesce(nullif(p.display_name, ''), split_part(coalesce(p.email, ''), '@', 1), 'Tester') as name,
                       p.avatar_url,
                       p.credits,
                       (select count(*) from public.checkins ci where ci.user_id = p.id) as checkin_count,
                       (select count(distinct ci.campaign_id) from public.checkins ci where ci.user_id = p.id) as campaigns_count
                from public.profiles p
                order by p.credits desc
                limit v_limit
            ) b
        ) t;
    end if;

    return v_result;
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_media_gateway_secret()
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
    v_secret text;
begin
    v_secret := current_setting('app.settings.media_gateway_secret', true);
    if v_secret is null or length(trim(v_secret)) = 0 then
        raise exception 'MEDIA_GATEWAY_SECRET_NOT_CONFIGURED';
    end if;
    return v_secret;
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_my_active_mission_campaign_ids()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_user_id uuid := auth.uid();
begin
    if v_user_id is null then
        raise exception 'NOT_AUTHENTICATED';
    end if;

    update public.missions
    set status = 'expired'
    where creator_id = v_user_id
      and status in ('open', 'full', 'paused_by_creator')
      and ends_at <= now();

    return coalesce((
        select jsonb_agg(campaign_id)
        from public.missions
        where creator_id = v_user_id
          and status in ('open', 'full', 'paused_by_creator')
          and ends_at > now()
    ), '[]'::jsonb);
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_my_daily_task_status()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_uid uuid := auth.uid();
begin
    if v_uid is null then
        raise exception 'NOT_AUTHENTICATED';
    end if;

    return public.get_daily_task_status(
        v_uid,
        (now() at time zone 'Asia/Ho_Chi_Minh')::date
    );
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_my_dashboard(p_include_leaderboard boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_uid uuid := auth.uid();
    v_today date := (now() at time zone 'Asia/Ho_Chi_Minh')::date;
    v_week_ago date := v_today - 6;
    v_profile jsonb;
    v_my_campaigns jsonb := '[]'::jsonb;
    v_joined jsonb := '[]'::jsonb;
    v_leaderboard jsonb := '[]'::jsonb;
    v_today_checkins int := 0;
    v_pending int := 0;
    v_unread jsonb := '[]'::jsonb;
    v_weekly int := 0;
    v_logs jsonb := '[]'::jsonb;
    v_packages jsonb := '[]'::jsonb;
    v_notifications jsonb := '[]'::jsonb;
    v_owner_stats jsonb := '{}'::jsonb;
    v_slots jsonb := '[]'::jsonb;
    v_quest jsonb := null;
    v_daily jsonb := null;
begin
    if v_uid is null then
        raise exception 'NOT_AUTHENTICATED';
    end if;

    -- Mọi lần mở Trang chủ/Hồ sơ đều được tính là đăng nhập trong ngày.
    -- Không gọi get_my_dashboard từ background worker.
    perform public.record_daily_login_internal(v_uid, v_today);

    select public._profile_json(p) into v_profile
    from public.profiles p where p.id = v_uid;

    select coalesce(jsonb_agg(public._campaign_json(c) order by c.created_at desc), '[]'::jsonb)
    into v_my_campaigns
    from public.campaigns c
    where c.owner_id = v_uid;

    select coalesce(jsonb_agg(public._campaign_json(c) order by c.created_at desc), '[]'::jsonb)
    into v_joined
    from public.campaigns c
    join public.campaign_members m on m.campaign_id = c.id and m.user_id = v_uid
    where c.owner_id <> v_uid;

    -- Bảng xếp hạng: top 100 theo credits (khớp thuật toán cũ của app).
    -- Chỉ tính khi client yêu cầu (tab Bảng xếp hạng mở).
    if p_include_leaderboard then
        select coalesce(jsonb_agg(jsonb_build_object(
            'userId', t.id,
            'displayName', t.name,
            'avatarUrl', t.avatar_url,
            'credits', t.credits,
            'checkinCount', t.checkin_count,
            'campaignsCount', t.campaigns_count,
            'rank', t.rn
        ) order by t.rn), '[]'::jsonb)
        into v_leaderboard
        from (
            select b.*, row_number() over (order by b.credits desc, b.checkin_count desc, b.campaigns_count desc) as rn
            from (
                select p.id,
                       coalesce(nullif(p.display_name, ''), split_part(coalesce(p.email, ''), '@', 1), 'Tester') as name,
                       p.avatar_url,
                       p.credits,
                       (select count(*) from public.checkins ci where ci.user_id = p.id) as checkin_count,
                       (select count(distinct ci.campaign_id) from public.checkins ci where ci.user_id = p.id) as campaigns_count
                from public.profiles p
                order by p.credits desc
                limit 100
            ) b
        ) t;
    end if;

    -- Số app đã test hôm nay: checkins + báo cáo pending/approved trong ngày
    select count(distinct campaign_id) into v_today_checkins
    from (
        select campaign_id from public.checkins
        where user_id = v_uid and checkin_date = v_today
        union
        select campaign_id from public.tester_reports
        where user_id = v_uid
          and (created_at at time zone 'Asia/Ho_Chi_Minh')::date = v_today
          and status in ('pending', 'approved')
    ) t;

    -- Báo cáo đang chờ duyệt trên toàn bộ app của tôi
    select count(*) into v_pending
    from public.tester_reports tr
    join public.campaigns c on c.id = tr.campaign_id
    where c.owner_id = v_uid and tr.status = 'pending';

    select coalesce(jsonb_agg(jsonb_build_object(
        'id', w.id,
        'user_id', w.user_id,
        'warning_type', w.warning_type,
        'message', w.message,
        'warning_date', to_char(w.warning_date, 'YYYY-MM-DD'),
        'created_at', to_char(w.created_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
        'acknowledged', w.acknowledged
    ) order by w.created_at desc), '[]'::jsonb)
    into v_unread
    from public.user_warnings w
    where w.user_id = v_uid and w.acknowledged = false;

    select count(*) into v_weekly
    from public.user_warnings
    where user_id = v_uid and warning_date >= v_week_ago;

    select coalesce(jsonb_agg(jsonb_build_object(
        'id', l.id,
        'user_id', l.user_id,
        'amount', l.amount,
        'action', l.action,
        'note', l.note,
        'balance', l.balance,
        'created_at', to_char(l.created_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"')
    ) order by l.created_at desc), '[]'::jsonb)
    into v_logs
    from (
        select * from public.credit_logs
        where user_id = v_uid
        order by created_at desc
        limit 20
    ) l;

    select coalesce(jsonb_agg(jsonb_build_object(
        'id', tp.id,
        'title', tp.title,
        'credits', tp.credits,
        'bonus_credits', tp.bonus_credits,
        'price_usd', tp.price_usd,
        'price_vnd', tp.price_vnd,
        'badge_text', tp.badge_text,
        'is_popular', tp.is_popular,
        'is_active', tp.is_active,
        'sort_order', tp.sort_order
    ) order by tp.sort_order asc), '[]'::jsonb)
    into v_packages
    from public.topup_packages tp
    where tp.is_active = true;

    select coalesce(jsonb_agg(jsonb_build_object(
        'id', n.id,
        'user_id', n.user_id,
        'title', n.title,
        'message', n.message,
        'type', n.type,
        'data', coalesce(n.data, '{}'::jsonb),
        'is_read', n.is_read,
        'created_at', to_char(n.created_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"')
    ) order by n.created_at desc), '[]'::jsonb)
    into v_notifications
    from (
        select * from public.notifications
        where user_id = v_uid
        order by created_at desc
        limit 50
    ) n;

    -- Thống kê cho từng app của chủ app hiện tại
    select coalesce(jsonb_object_agg(s.campaign_id::text, jsonb_build_object(
        'installedTestersCount', s.installed,
        'testedTodayCount', s.tested_today,
        'totalReportsCount', s.total_reports,
        'pendingReportsCount', s.pending_reports,
        'averageRating', s.avg_rating
    )), '{}'::jsonb)
    into v_owner_stats
    from (
        select c.id as campaign_id,
            (select count(*) from public.campaign_members m where m.campaign_id = c.id) as installed,
            (select count(distinct u.user_id) from (
                select ci.user_id from public.checkins ci
                where ci.campaign_id = c.id and ci.checkin_date = v_today
                union
                select tr.user_id from public.tester_reports tr
                where tr.campaign_id = c.id and tr.status <> 'rejected'
                  and (tr.created_at at time zone 'Asia/Ho_Chi_Minh')::date = v_today
            ) u) as tested_today,
            greatest(
                (select count(*) from public.tester_reports tr2 where tr2.campaign_id = c.id),
                (select count(*) from public.checkins ci2 where ci2.campaign_id = c.id)
            ) as total_reports,
            (select count(*) from public.tester_reports tr3
              where tr3.campaign_id = c.id and tr3.status = 'pending') as pending_reports,
            (select avg(f.rating)::float8 from public.feedbacks f where f.campaign_id = c.id) as avg_rating
        from public.campaigns c
        where c.owner_id = v_uid
    ) s;

    -- Slot đã mở của người dùng (bỏ 1-2 round-trip riêng cho màn Profile/Tạo app)
    select coalesce(jsonb_agg(jsonb_build_object(
        'id', s.id,
        'user_id', s.user_id,
        'slot_number', s.slot_number,
        'unlocked_at', to_char(s.unlocked_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
        'expires_at', to_char(s.expires_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
        'created_at', to_char(s.created_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"')
    ) order by s.slot_number asc), '[]'::jsonb)
    into v_slots
    from public.user_slots s
    where s.user_id = v_uid;

    begin
        v_quest := public.get_user_quest_summary();
    exception when others then
        v_quest := null;
    end;

    v_daily := public.get_daily_task_status(v_uid, v_today);

    return jsonb_build_object(
        'profile', v_profile,
        'my_campaigns', v_my_campaigns,
        'joined_campaigns', v_joined,
        'leaderboard', v_leaderboard,
        'today_checkin_count', v_today_checkins,
        'pending_reports_count', v_pending,
        'unread_warnings', v_unread,
        'weekly_warnings_count', v_weekly,
        'credit_logs', v_logs,
        'topup_packages', v_packages,
        'notifications', v_notifications,
        'owner_stats', v_owner_stats,
        'slots', v_slots,
        'quest_summary', v_quest,
        'daily_task', v_daily
    );
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_my_rank_v1(p_sort text DEFAULT 'credit'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_user uuid := auth.uid();
    v_credits int;
    v_checkins int;
    v_campaigns int;
    v_total int;
    v_rank int;
begin
    if v_user is null then
        return '{}'::jsonb;
    end if;

    -- Thống kê của chính mình.
    select p.credits,
           (select count(*) from public.checkins ci where ci.user_id = p.id),
           (select count(distinct ci.campaign_id) from public.checkins ci where ci.user_id = p.id)
    into v_credits, v_checkins, v_campaigns
    from public.profiles p
    where p.id = v_user;

    if not found then
        return '{}'::jsonb;
    end if;

    select count(*) into v_total from public.profiles;

    if coalesce(p_sort, 'credit') = 'test' then
        if v_checkins = 0 then
            -- Top Test chỉ gồm người đã thực hiện ít nhất 1 lượt test.
            return '{}'::jsonb;
        end if;

        select count(*) + 1 into v_rank
        from (
            select p.id,
                   p.credits,
                   (select count(*) from public.checkins ci where ci.user_id = p.id) as checkin_count,
                   (select count(distinct ci.campaign_id) from public.checkins ci where ci.user_id = p.id) as campaigns_count
            from public.profiles p
        ) t
        where t.checkin_count > v_checkins
           or (t.checkin_count = v_checkins and t.credits > v_credits)
           or (t.checkin_count = v_checkins and t.credits = v_credits and t.campaigns_count > v_campaigns);
    else
        select count(*) + 1 into v_rank
        from (
            select p.id,
                   p.credits,
                   (select count(*) from public.checkins ci where ci.user_id = p.id) as checkin_count,
                   (select count(distinct ci.campaign_id) from public.checkins ci where ci.user_id = p.id) as campaigns_count
            from public.profiles p
        ) t
        where t.credits > v_credits
           or (t.credits = v_credits and t.checkin_count > v_checkins)
           or (t.credits = v_credits and t.checkin_count = v_checkins and t.campaigns_count > v_campaigns);
    end if;

    return jsonb_build_object(
        'rank', v_rank,
        'credits', v_credits,
        'checkinCount', v_checkins,
        'campaignsCount', v_campaigns,
        'totalUsers', v_total
    );
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_next_untested_campaign(p_current_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_uid uuid := auth.uid();
    v_today date := (now() at time zone 'Asia/Ho_Chi_Minh')::date;
    v_camp public.campaigns%rowtype;
begin
    select c.* into v_camp
    from public.campaigns c
    where c.status = 'open'
      and (p_current_id is null or c.id <> p_current_id)
      and (v_uid is null or c.owner_id <> v_uid)
      and not exists (
          select 1 from public.checkins ci
          where ci.campaign_id = c.id
            and ci.user_id = v_uid
            and ci.checkin_date = v_today
      )
      and not exists (
          select 1 from public.tester_reports tr
          where tr.campaign_id = c.id
            and tr.user_id = v_uid
            and tr.status <> 'rejected'
            and (tr.created_at at time zone 'Asia/Ho_Chi_Minh')::date = v_today
      )
    order by c.created_at desc
    limit 1;

    return jsonb_build_object(
        'campaign', case
            when v_camp.id is null then null
            else public._campaign_json(v_camp)
        end
    );
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_open_missions()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_user_id uuid := auth.uid();
    v_now timestamptz := now();
begin
    -- Đồng bộ trạng thái hết hạn trong DB
    update public.missions
    set status = 'expired'
    where status in ('open', 'full', 'paused_by_creator')
      and ends_at <= v_now;

    return jsonb_build_object(
        'missions', coalesce((
            select jsonb_agg(
                jsonb_build_object(
                    'id', t.id,
                    'title', t.title,
                    'description', t.description,
                    'reward_credits', t.reward_credits,
                    'max_participants', t.max_participants,
                    'participant_count', t.participant_count,
                    'status', t.status,
                    'ends_at', to_char(t.ends_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
                    'created_at', to_char(t.created_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
                    'campaign_id', t.campaign_id,
                    'app_name', t.app_name,
                    'icon_url', t.icon_url,
                    'package_name', t.package_name,
                    'creator_id', t.creator_id,
                    'creator_name', t.creator_name,
                    'is_mine', t.creator_id = v_user_id,
                    'has_joined', t.has_joined,
                    'has_completed', t.has_completed
                )
                order by t.sort_mine desc, t.sort_active desc, t.created_at desc, t.id desc
            )
            from (
                select
                    m.id, m.title, m.description, m.reward_credits,
                    m.max_participants, m.participant_count, m.status,
                    m.ends_at, m.created_at, m.campaign_id, m.creator_id,
                    c.app_name, c.icon_url, c.package_name,
                    coalesce(nullif(p.display_name, ''), split_part(coalesce(p.email, ''), '@', 1), '') as creator_name,
                    case
                        when m.creator_id = v_user_id then 1
                        when exists (
                            select 1 from public.mission_participants mp_mine
                            where mp_mine.mission_id = m.id and mp_mine.user_id = v_user_id
                        ) then 1
                        else 0
                    end as sort_mine,
                    case m.status
                        when 'open' then 2
                        when 'full' then 2
                        when 'paused_by_creator' then 1
                        else 0
                    end as sort_active,
                    exists (
                        select 1 from public.mission_participants mp2
                        where mp2.mission_id = m.id and mp2.user_id = v_user_id
                    ) as has_joined,
                    exists (
                        select 1 from public.mission_participants mp3
                        where mp3.mission_id = m.id and mp3.user_id = v_user_id
                          and mp3.status = 'completed'
                    ) as has_completed
                from public.missions m
                join public.campaigns c on c.id = m.campaign_id
                left join public.profiles p on p.id = m.creator_id
                where m.status in ('open', 'full', 'paused_by_creator')
                  and m.ends_at > v_now
                order by
                    case
                        when m.creator_id = v_user_id then 1
                        when exists (
                            select 1 from public.mission_participants mp_mine
                            where mp_mine.mission_id = m.id and mp_mine.user_id = v_user_id
                        ) then 1
                        else 0
                    end desc,
                    case m.status
                        when 'open' then 2
                        when 'full' then 2
                        when 'paused_by_creator' then 1
                        else 0
                    end desc,
                    m.created_at desc,
                    m.id desc
                limit 100
            ) t
        ), '[]'::jsonb),
        'server_now', to_char(v_now at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"')
    );
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_report_media_access(p_report_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
    v_user_id uuid := auth.uid();
    v_report record;
    v_camp record;
    v_role text := null;
    v_is_admin boolean := false;
    v_is_author boolean := false;
    v_is_owner boolean := false;
    v_full_token text;
    v_thumb_token text;
    v_expires_at timestamptz;
    v_expires_epoch bigint;
    v_gateway_base text;
    v_signed_full_url text;
    v_signed_thumb_url text;
begin
    -- 1. Xác thực bắt buộc: Phải có JWT hợp lệ, không tin bất kỳ UID/role client gửi
    if v_user_id is null then
        raise exception 'NOT_AUTHENTICATED';
    end if;

    -- 2. Đọc thông tin báo cáo
    select id, campaign_id, user_id, screenshot_url, thumbnail_url,
           created_at, media_expired
    into v_report
    from public.tester_reports
    where id = p_report_id;

    if v_report.id is null then
        raise exception 'REPORT_NOT_FOUND';
    end if;

    -- 3. Kiểm tra thời hạn lưu trữ & thu hồi (SLA 30 ngày)
    if v_report.media_expired = true or v_report.created_at < (now() - interval '30 days') then
        raise exception 'MEDIA_EXPIRED';
    end if;

    -- 4. Xác định quyền dựa trên quan hệ thực tế trong database
    v_is_author := (v_report.user_id = v_user_id);

    select * into v_camp from public.campaigns where id = v_report.campaign_id;
    if v_camp.id is not null and v_camp.owner_id = v_user_id then
        v_is_owner := true;
    end if;

    if exists (
        select 1 from public.profiles
        where id = v_user_id and lower(coalesce(role, '')) in ('admin', 'moderator')
    ) then
        v_is_admin := true;
    end if;

    if v_is_author then
        v_role := 'author';
    elsif v_is_owner then
        v_role := 'owner';
    elsif v_is_admin then
        v_role := 'admin';
    else
        -- Không có quyền truy cập báo cáo này
        raise exception 'FORBIDDEN';
    end if;

    -- 5. Cấp grant tải media có hiệu lực ngắn hạn (15 phút) dùng HMAC sha256 với secret server
    v_expires_at := now() + interval '15 minutes';
    v_expires_epoch := extract(epoch from v_expires_at)::bigint;

    v_full_token := encode(
        hmac(
            format('%s:%s:%s:%s:%s', p_report_id, v_user_id, v_role, 'full', v_expires_epoch),
            public.get_media_gateway_secret(),
            'sha256'
        ),
        'hex'
    );

    v_thumb_token := encode(
        hmac(
            format('%s:%s:%s:%s:%s', p_report_id, v_user_id, v_role, 'thumb', v_expires_epoch),
            public.get_media_gateway_secret(),
            'sha256'
        ),
        'hex'
    );

    v_gateway_base := nullif(current_setting('app.settings.media_gateway_base_url', true), '');
    if v_gateway_base is null or length(trim(v_gateway_base)) = 0 then
        raise exception 'MEDIA_GATEWAY_BASE_URL_NOT_CONFIGURED';
    end if;

    v_signed_full_url := format('%s?report_id=%s&variant=full&expires_at=%s&grant_token=%s',
        v_gateway_base, p_report_id, v_expires_epoch, v_full_token);

    v_signed_thumb_url := case
        when v_report.thumbnail_url is not null then
            format('%s?report_id=%s&variant=thumb&expires_at=%s&grant_token=%s',
                v_gateway_base, p_report_id, v_expires_epoch, v_thumb_token)
        else null
    end;

    -- Không trả về raw_storage_url cho client để chặn bypass URL
    return jsonb_build_object(
        'success', true,
        'report_id', p_report_id,
        'role', v_role,
        'screenshot_url', v_signed_full_url,
        'thumbnail_url', v_signed_thumb_url,
        'expires_at', v_expires_at,
        'expires_at_epoch', v_expires_epoch,
        'access_grant_token', v_full_token
    );
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_unread_warnings()
 RETURNS SETOF user_warnings
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    select * from public.user_warnings
    where user_id = auth.uid()
      and acknowledged = false
    order by created_at desc;
$function$;

CREATE OR REPLACE FUNCTION public.get_user_quest_summary()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_uid uuid := auth.uid();
    v_today date := (now() at time zone 'Asia/Ho_Chi_Minh')::date;
    v_week_start date := date_trunc('week', (now() at time zone 'Asia/Ho_Chi_Minh'))::date;
    v_daily_count int := 0;
    v_weekly_count int := 0;
    v_daily_claimed jsonb := '[]'::jsonb;
    v_weekly_claimed jsonb := '[]'::jsonb;
begin
    if v_uid is not null then
        -- Đếm số ứng dụng đã kiểm thử hôm nay (hợp nhất checkins và các báo cáo đã nộp hôm nay)
        select count(distinct campaign_id) into v_daily_count
        from (
            select campaign_id from public.checkins
            where user_id = v_uid and checkin_date = v_today
            union
            select campaign_id from public.tester_reports
            where user_id = v_uid
              and (created_at at time zone 'Asia/Ho_Chi_Minh')::date = v_today
              and status in ('pending', 'approved')
        ) t;

        -- Đếm số ứng dụng đã kiểm thử trong tuần này
        select count(distinct campaign_id || '-' || check_date::text) into v_weekly_count
        from (
            select campaign_id, checkin_date as check_date from public.checkins
            where user_id = v_uid and checkin_date >= v_week_start and checkin_date <= v_today
            union
            select campaign_id, (created_at at time zone 'Asia/Ho_Chi_Minh')::date as check_date from public.tester_reports
            where user_id = v_uid
              and (created_at at time zone 'Asia/Ho_Chi_Minh')::date >= v_week_start
              and (created_at at time zone 'Asia/Ho_Chi_Minh')::date <= v_today
              and status in ('pending', 'approved')
        ) w;

        -- Lấy các mốc ngày đã nhận thưởng hôm nay
        select coalesce(jsonb_agg(milestone), '[]'::jsonb) into v_daily_claimed
        from public.user_quest_claims
        where user_id = v_uid and quest_type = 'daily' and period_key = v_today;

        -- Lấy các mốc tuần đã nhận thưởng tuần này
        select coalesce(jsonb_agg(milestone), '[]'::jsonb) into v_weekly_claimed
        from public.user_quest_claims
        where user_id = v_uid and quest_type = 'weekly' and period_key = v_week_start;
    end if;

    return jsonb_build_object(
        'daily_count', v_daily_count,
        'weekly_count', v_weekly_count,
        'daily_claimed', v_daily_claimed,
        'weekly_claimed', v_weekly_claimed,
        'today_date', v_today,
        'week_start_date', v_week_start,
        'daily_milestones', jsonb_build_array(
            jsonb_build_object('milestone', 10, 'reward', 5),
            jsonb_build_object('milestone', 20, 'reward', 15),
            jsonb_build_object('milestone', 50, 'reward', 30)
        ),
        'weekly_milestones', jsonb_build_array(
            jsonb_build_object('milestone', 150, 'reward', 50),
            jsonb_build_object('milestone', 300, 'reward', 100)
        )
    );
end;
$function$;

CREATE OR REPLACE FUNCTION public.guard_daily_task_policy()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
    -- Wall clock prevents a transaction opened yesterday from editing today's
    -- effective policy. Evaluate after any row-lock wait, not at transaction start.
    v_today date := (clock_timestamp() at time zone 'Asia/Ho_Chi_Minh')::date;
begin
    if tg_op in ('UPDATE', 'DELETE') and old.effective_from <= v_today then
        raise exception 'DAILY_TASK_POLICY_IMMUTABLE';
    end if;
    if tg_op = 'DELETE' then
        return old;
    end if;
    if not isfinite(new.effective_from) or new.effective_from <= v_today then
        raise exception 'DAILY_TASK_POLICY_FUTURE_DATE_REQUIRED';
    end if;
    if tg_op = 'UPDATE' and (
        new.id is distinct from old.id
        or new.effective_from is distinct from old.effective_from
        or new.created_at is distinct from old.created_at
    ) then
        raise exception 'DAILY_TASK_POLICY_IDENTITY_IMMUTABLE';
    end if;
    if tg_when = 'BEFORE' then
        new.operator_note := btrim(new.operator_note);
        new.updated_at := clock_timestamp();
    end if;
    return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.handle_campaign_target_cost()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_cost int := 0;
    v_old_cost int := 0;
    v_delta int := 0;
    v_balance int;
begin
    -- Chuẩn hóa target_testers (chỉ 12/15/20 hợp lệ)
    if new.target_testers is null or new.target_testers not in (12, 15, 20) then
        new.target_testers := 12;
    end if;

    if tg_op = 'UPDATE' then
        if new.target_testers is not distinct from old.target_testers then
            return new;
        end if;

        v_old_cost := case old.target_testers when 15 then 10 when 20 then 20 else 0 end;
        v_cost := case new.target_testers when 15 then 10 when 20 then 20 else 0 end;
        v_delta := v_cost - v_old_cost;
    else
        v_cost := case new.target_testers when 15 then 10 when 20 then 20 else 0 end;
        v_delta := v_cost;
    end if;

    -- Giảm gói hoặc giữ nguyên: không trừ thêm (không hoàn Credit khi hạ gói)
    if v_delta <= 0 then
        return new;
    end if;

    select credits into v_balance
    from public.profiles
    where id = new.owner_id
    for update;

    if v_balance is null or v_balance < v_delta then
        raise exception 'INSUFFICIENT_CREDITS_FOR_TARGET: Cần ít nhất % Credit để nâng mục tiêu lên % Test/ngày', v_delta, new.target_testers;
    end if;

    update public.profiles
    set credits = credits - v_delta
    where id = new.owner_id
    returning credits into v_balance;

    insert into public.credit_logs (user_id, amount, action, note, balance)
    values (
        new.owner_id,
        -v_delta,
        'target_upgrade',
        format('Nâng cấp mục tiêu %s Test/ngày (-%s Credit)', new.target_testers, v_delta),
        v_balance
    );

    return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.handle_checkin_reward()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    today_reward_count int;
    v_credit_reward int := 0;
    new_balance int;
begin
    update public.profiles
    set last_active_date = new.checkin_date,
        missed_streak = 0
    where id = new.user_id;

    perform public.refresh_daily_completion(new.user_id, new.checkin_date);

    -- Nếu dòng checkin này được tạo từ việc nộp/duyệt báo cáo (đã xử lý cộng điểm), bỏ qua không cộng lần 2
    if new.note is not null and (
        new.note like 'Đã kiểm thử%' or
        new.note like '%Tự động duyệt%' or
        new.note like '%chủ app duyệt%' or
        new.note like 'Đã nộp kết quả%' or
        new.note like '%tạm tính%'
    ) then
        return new;
    end if;

    select count(*) into today_reward_count
    from public.checkins
    where user_id = new.user_id and checkin_date = new.checkin_date;

    if today_reward_count <= 30 then
        v_credit_reward := 2;
    elsif today_reward_count <= 50 then
        v_credit_reward := 1;
    else
        v_credit_reward := 0;
    end if;

    if v_credit_reward > 0 then
        update public.profiles
        set credits = credits + v_credit_reward
        where id = new.user_id
        returning credits into new_balance;

        insert into public.credit_logs (user_id, amount, action, note, balance)
        values (
            new.user_id,
            v_credit_reward,
            'checkin_reward',
            format('Thưởng test app (lượt %s/50 trong ngày, +%s Credit)', today_reward_count, v_credit_reward),
            new_balance
        );
    end if;

    return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    insert into public.profiles (
        id,
        email,
        display_name,
        avatar_url,
        credits,
        last_active_date,
        missed_streak,
        role,
        is_locked
    )
    values (
        new.id,
        new.email,
        coalesce(
            new.raw_user_meta_data ->> 'full_name',
            new.raw_user_meta_data ->> 'name',
            new.raw_user_meta_data ->> 'display_name',
            split_part(coalesce(new.email, ''), '@', 1)
        ),
        coalesce(
            new.raw_user_meta_data ->> 'avatar_url',
            new.raw_user_meta_data ->> 'picture'
        ),
        100,
        current_date,
        0,
        'member',
        false
    )
    on conflict (id) do nothing;

    -- Ghi log khởi tạo 100 credit
    insert into public.credit_logs (user_id, amount, action, note, balance)
    values (
        new.id,
        100,
        'welcome',
        'Thưởng 100 Credit khi mở tài khoản',
        100
    )
    on conflict do nothing;

    return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.handle_tester_report_submitted()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    update public.profiles
    set last_active_date = (now() at time zone 'Asia/Ho_Chi_Minh')::date,
        missed_streak = 0
    where id = new.user_id;

    return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.is_valid_report_screenshot_url(p_url text, p_campaign_id uuid, p_user_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
    v_clean_url text;
    v_bucket text;
    v_path text;
    v_matches text[];
begin
    if p_url is null or length(p_url) > 2048 then
        return false;
    end if;

    -- Tách query string (?) và fragment (#) để triệt tiêu query spoofing
    v_clean_url := split_part(split_part(p_url, '?', 1), '#', 1);

    -- 1. Parse theo định dạng Firebase Storage chuẩn hoặc GCS
    if v_clean_url ~* '^https://firebasestorage\.googleapis\.com/v0/b/([^/]+)/o/(.+)$' then
        v_matches := regexp_matches(v_clean_url, '^https://firebasestorage\.googleapis\.com/v0/b/([^/]+)/o/(.+)$', 'i');
        v_bucket := v_matches[1];
        v_path := v_matches[2];
    elsif v_clean_url ~* '^https://([^/]+)\.firebasestorage\.app/v0/b/([^/]+)/o/(.+)$' then
        v_matches := regexp_matches(v_clean_url, '^https://([^/]+)\.firebasestorage\.app/v0/b/([^/]+)/o/(.+)$', 'i');
        v_bucket := v_matches[2];
        v_path := v_matches[3];
    elsif v_clean_url ~* '^https://([^/]+)\.firebasestorage\.app/o/(.+)$' then
        v_matches := regexp_matches(v_clean_url, '^https://([^/]+)\.firebasestorage\.app/o/(.+)$', 'i');
        v_bucket := v_matches[1] || '.firebasestorage.app';
        v_path := v_matches[2];
    elsif v_clean_url ~* '^https://storage\.googleapis\.com/([^/]+)/(.+)$' then
        v_matches := regexp_matches(v_clean_url, '^https://storage\.googleapis\.com/([^/]+)/(.+)$', 'i');
        v_bucket := v_matches[1];
        v_path := v_matches[2];
    else
        return false;
    end if;

    -- 2. Allowlist bucket (chỉ cho phép các bucket chính thức của dự án, không cho phép ký tự đại diện hoặc bucket test trong validator production)
    if not (
        v_bucket in ('cross-testers.firebasestorage.app', 'cross-testers.appspot.com', 'crosstest-prod.appspot.com')
    ) then
        return false;
    end if;

    -- 3. Chuẩn hoá percent-encoding (%2F -> /)
    v_path := replace(replace(v_path, '%2F', '/'), '%2f', '/');

    -- 4. Ràng buộc object path: reports/<campaign_id>/<user_id>/<filename>
    if not (
        v_path ~* ('^reports/' || p_campaign_id::text || '/' || p_user_id::text || '/[a-zA-Z0-9_\-\.]+\.(jpg|jpeg|png|webp)$')
        or v_path ~* ('^reports/' || p_campaign_id::text || '/' || p_user_id::text || '_[a-zA-Z0-9_\-\.]+\.(jpg|jpeg|png|webp)$')
    ) then
        return false;
    end if;

    return true;
end;
$function$;

CREATE OR REPLACE FUNCTION public.is_valid_report_thumbnail_url(p_thumb_url text, p_campaign_id uuid, p_user_id uuid, p_screenshot_url text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
    v_clean_thumb text;
    v_clean_full text;
    v_thumb_bucket text;
    v_thumb_path text;
    v_matches text[];
    v_thumb_filename text;
    v_full_filename text;
begin
    -- 1. Thumbnail là tùy chọn: NULL là hoàn toàn hợp lệ (legacy reports)
    if p_thumb_url is null then
        return true;
    end if;

    if length(p_thumb_url) > 2048 then
        return false;
    end if;

    -- Tách query string (?) và fragment (#)
    v_clean_thumb := split_part(split_part(p_thumb_url, '?', 1), '#', 1);

    if v_clean_thumb ~* '^https://firebasestorage\.googleapis\.com/v0/b/([^/]+)/o/(.+)$' then
        v_matches := regexp_matches(v_clean_thumb, '^https://firebasestorage\.googleapis\.com/v0/b/([^/]+)/o/(.+)$', 'i');
        v_thumb_bucket := v_matches[1];
        v_thumb_path := v_matches[2];
    elsif v_clean_thumb ~* '^https://([^/]+)\.firebasestorage\.app/v0/b/([^/]+)/o/(.+)$' then
        v_matches := regexp_matches(v_clean_thumb, '^https://([^/]+)\.firebasestorage\.app/v0/b/([^/]+)/o/(.+)$', 'i');
        v_thumb_bucket := v_matches[2];
        v_thumb_path := v_matches[3];
    elsif v_clean_thumb ~* '^https://([^/]+)\.firebasestorage\.app/o/(.+)$' then
        v_matches := regexp_matches(v_clean_thumb, '^https://([^/]+)\.firebasestorage\.app/o/(.+)$', 'i');
        v_thumb_bucket := v_matches[1] || '.firebasestorage.app';
        v_thumb_path := v_matches[2];
    elsif v_clean_thumb ~* '^https://storage\.googleapis\.com/([^/]+)/(.+)$' then
        v_matches := regexp_matches(v_clean_thumb, '^https://storage\.googleapis\.com/([^/]+)/(.+)$', 'i');
        v_thumb_bucket := v_matches[1];
        v_thumb_path := v_matches[2];
    else
        return false;
    end if;

    -- Allowlist bucket
    if not (
        v_thumb_bucket in ('cross-testers.firebasestorage.app', 'cross-testers.appspot.com', 'crosstest-prod.appspot.com')
    ) then
        return false;
    end if;

    -- Chuẩn hoá percent-encoding
    v_thumb_path := replace(replace(v_thumb_path, '%2F', '/'), '%2f', '/');

    -- Đường dẫn object thumbnail phải thuộc đúng campaign, user và có tiền tố thumb_
    if not (
        v_thumb_path ~* ('^reports/' || p_campaign_id::text || '/' || p_user_id::text || '/thumb_[a-zA-Z0-9_\-\.]+\.(jpg|jpeg|png|webp)$')
        or v_thumb_path ~* ('^reports/' || p_campaign_id::text || '/' || p_user_id::text || '_thumb_[a-zA-Z0-9_\-\.]+\.(jpg|jpeg|png|webp)$')
    ) then
        return false;
    end if;

    -- 2. Kiểm tra ràng buộc cặp Full - Thumbnail nếu có p_screenshot_url
    if p_screenshot_url is not null then
        v_clean_full := split_part(split_part(p_screenshot_url, '?', 1), '#', 1);
        v_clean_full := replace(replace(v_clean_full, '%2F', '/'), '%2f', '/');
        
        v_thumb_filename := substring(v_thumb_path from '[^/]+$');
        v_full_filename := substring(v_clean_full from '[^/]+$');

        -- Tên file thumbnail phải đúng định dạng 'thumb_' + tên file full
        if v_thumb_filename != ('thumb_' || v_full_filename) then
            return false;
        end if;
    end if;

    return true;
end;
$function$;

CREATE OR REPLACE FUNCTION public.join_mission(p_mission_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_user_id uuid := auth.uid();
    v_mission record;
    v_camp_status text;
    v_new_status text;
begin
    if v_user_id is null then
        raise exception 'NOT_AUTHENTICATED';
    end if;

    select * into v_mission
    from public.missions
    where id = p_mission_id
    for update;

    if v_mission.id is null then
        raise exception 'MISSION_NOT_FOUND';
    end if;

    if v_mission.creator_id = v_user_id then
        raise exception 'CANNOT_JOIN_OWN_MISSION';
    end if;

    if v_mission.status not in ('open', 'full') then
        raise exception 'MISSION_NOT_OPEN';
    end if;

    if v_mission.ends_at <= now() then
        raise exception 'MISSION_EXPIRED';
    end if;

    if v_mission.participant_count >= v_mission.max_participants then
        raise exception 'MISSION_FULL';
    end if;

    if exists (
        select 1 from public.mission_participants
        where mission_id = p_mission_id and user_id = v_user_id
    ) then
        raise exception 'ALREADY_JOINED';
    end if;

    select status into v_camp_status from public.campaigns where id = v_mission.campaign_id;
    if v_camp_status is null then
        raise exception 'CAMPAIGN_NOT_FOUND';
    end if;
    if v_camp_status <> 'open' then
        raise exception 'CAMPAIGN_NOT_OPEN';
    end if;

    insert into public.mission_participants (mission_id, user_id)
    values (p_mission_id, v_user_id);

    v_new_status := case when v_mission.participant_count + 1 >= v_mission.max_participants
                         then 'full' else v_mission.status end;

    update public.missions
    set participant_count = participant_count + 1,
        status = v_new_status
    where id = p_mission_id;

    insert into public.notifications (user_id, title, message, type, data)
    values (
        v_mission.creator_id,
        'Người tham gia nhiệm vụ mới 🎯',
        format('"%s" vừa nhận nhiệm vụ "%s". Hãy sẵn sàng duyệt báo cáo test để trả thưởng.',
               coalesce((select display_name from public.profiles where id = v_user_id), 'Một người dùng'),
               v_mission.title),
        'mission',
        jsonb_build_object('mission_id', p_mission_id, 'campaign_id', v_mission.campaign_id)
    );

    return jsonb_build_object(
        'success', true,
        'mission_id', p_mission_id,
        'campaign_id', v_mission.campaign_id,
        'status', v_new_status
    );
end;
$function$;

CREATE OR REPLACE FUNCTION public.make_user_admin(p_email text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_count int;
    v_caller uuid := auth.uid();
begin
    -- Cho phép gọi từ SQL Editor / service_role (không có JWT), chặn mọi caller khác không phải admin
    if v_caller is not null and not exists (
        select 1 from public.profiles where id = v_caller and role = 'admin'
    ) then
        raise exception 'PERMISSION_DENIED: Chỉ admin mới được bổ nhiệm vai trò';
    end if;

    update public.profiles
    set role = 'admin'
    where lower(email) = lower(trim(p_email));

    get diagnostics v_count = row_count;
    if v_count > 0 then
        return format('Đã bổ nhiệm tài khoản %s thành Admin thành công.', p_email);
    else
        return format('Không tìm thấy tài khoản với email %s.', p_email);
    end if;
end;
$function$;

CREATE OR REPLACE FUNCTION public.make_user_moderator(p_email text)
