    else
        return format('Không tìm thấy tài khoản với email %s.', p_email);
    end if;
end;
$function$;

CREATE OR REPLACE FUNCTION public.pause_expired_slot_campaigns()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_count int := 0;
begin
    update public.campaigns c
    set status = 'paused',
        paused_reason = 'slot_expired'
    where c.status = 'open'
      and c.slot_number > 1
      and exists (
          select 1 from public.user_slots s
          where s.user_id = c.owner_id
            and s.slot_number = c.slot_number
            and s.expires_at <= now()
      );
    get diagnostics v_count = row_count;
    return v_count;
end;
$function$;

CREATE OR REPLACE FUNCTION public.pause_inactive_owner_campaigns()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    r record;
    v_count int := 0;
    v_today date := (now() at time zone 'Asia/Ho_Chi_Minh')::date;
    v_status jsonb;
begin
    for r in
        select c.id, c.owner_id, c.app_name
        from public.campaigns c
        join public.profiles p on p.id = c.owner_id
        where c.status = 'open'
          and coalesce(c.admin_resumed, false) = false
          and c.created_at <= now() - interval '24 hours'
          and lower(p.role) not in ('admin', 'moderator')
          and p.daily_missed_streak >= 7
        for update of c
    loop
        v_status := public.get_daily_task_status(r.owner_id, v_today);

        -- R03: Pending không được kích hoạt auto-pause vì nhiệm vụ chưa xác định
        if coalesce((v_status ->> 'carryover_ready')::boolean, true) = false then
            continue;
        end if;

        -- Người vừa hoạt động lại trong hôm nay thì không pause oan
        if coalesce((v_status ->> 'met')::boolean, false) = true then
            continue;
        end if;

        update public.campaigns
        set status = 'paused',
            paused_reason = 'owner_inactive'
        where id = r.id;

        insert into public.notifications (user_id, title, message, type, data)
        values (
            r.owner_id,
            'Ứng dụng đã bị tạm dừng ⏸',
            format(
                'Ứng dụng "%s" đã bị tạm dừng vì bạn không hoàn thành chỉ tiêu test trong 7 ngày liên tục. Hãy hoàn thành chỉ tiêu hôm nay, sau đó bấm "Tiếp tục nhận tester" trong màn hình quản lý app để hiển thị lại.',
                coalesce(nullif(r.app_name, ''), 'của bạn')
            ),
            'campaign',
            jsonb_build_object('campaign_id', r.id, 'reason', 'owner_inactive')
        );

        v_count := v_count + 1;
    end loop;

    return v_count;
end;
$function$;

CREATE OR REPLACE FUNCTION public.pause_mission(p_mission_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_user_id uuid := auth.uid();
    v_mission record;
begin
    -- Giữ nguyên contract lỗi auth/quyền cũ
    if v_user_id is null then
        raise exception 'Not authenticated';
    end if;

    select * into v_mission
    from public.missions
    where id = p_mission_id
    for update;

    if v_mission.id is null or v_mission.status = 'deleted' then
        raise exception 'MISSION_NOT_FOUND';
    end if;

    if v_mission.creator_id <> v_user_id then
        raise exception 'PERMISSION_DENIED';
    end if;

    -- Nếu đã hết hạn: cập nhật DB và trả kết quả JSON có cấu trúc, KHÔNG raise exception
    -- để lệnh UPDATE status = 'expired' không bị rollback (R04).
    if v_mission.ends_at <= now() then
        update public.missions
        set status = 'expired'
        where id = p_mission_id
          and status in ('open', 'full', 'paused_by_creator');

        return jsonb_build_object(
            'success', false,
            'code', 'MISSION_EXPIRED',
            'error', 'MISSION_EXPIRED',
            'message', 'Nhiệm vụ đã hết hạn lưu hành',
            'mission_id', p_mission_id,
            'status', 'expired'
        );
    end if;

    if v_mission.status not in ('open', 'full') then
        raise exception 'MISSION_NOT_OPEN';
    end if;

    update public.missions
    set status = 'paused_by_creator'
    where id = p_mission_id;

    return jsonb_build_object(
        'success', true,
        'mission_id', p_mission_id,
        'status', 'paused_by_creator'
    );
end;
$function$;

CREATE OR REPLACE FUNCTION public.process_topup_order(p_package_id text, p_purchase_token text DEFAULT NULL::text, p_order_ref text DEFAULT NULL::text, p_payment_method text DEFAULT 'google_play'::text, p_raw_receipt text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_user_id       uuid := auth.uid();
    v_pkg           record;
    v_existing_order record;
    v_total_credits int;
    v_new_balance   int;
    v_order_id      uuid;
    v_note          text;
begin
    -- 1. Ensure authenticated
    if v_user_id is null then
        raise exception 'NOT_AUTHENTICATED';
    end if;

    -- 2. Check for duplicate purchase token (Idempotency / anti double-spend)
    if p_purchase_token is not null and trim(p_purchase_token) <> '' then
        select * into v_existing_order
        from public.topup_orders
        where purchase_token = trim(p_purchase_token)
          and payment_status = 'completed'
        limit 1;

        if found then
            -- Token already processed previously, return existing balance safely
            select credits into v_new_balance from public.profiles where id = v_user_id;
            return jsonb_build_object(
                'status', 'already_processed',
                'order_id', v_existing_order.id,
                'credits_awarded', v_existing_order.credits_awarded,
                'current_balance', coalesce(v_new_balance, 0),
                'message', 'Giao dịch này đã được cộng điểm trước đó.'
            );
        end if;
    end if;

    -- 3. Fetch package details
    select * into v_pkg
    from public.topup_packages
    where id = p_package_id;

    if not found then
        raise exception 'PACKAGE_NOT_FOUND: Gói nạp không tồn tại hoặc đã ngừng hoạt động.';
    end if;

    if v_pkg.is_active is not true then
        raise exception 'PACKAGE_INACTIVE: Gói nạp đã ngừng hoạt động.';
    end if;

    v_total_credits := v_pkg.credits + coalesce(v_pkg.bonus_credits, 0);

    -- 4. Create completed order record
    insert into public.topup_orders (
        user_id,
        package_id,
        credits_awarded,
        price_usd,
        price_vnd,
        payment_method,
        payment_status,
        purchase_token,
        order_reference,
        raw_receipt,
        completed_at
    )
    values (
        v_user_id,
        v_pkg.id,
        v_total_credits,
        v_pkg.price_usd,
        v_pkg.price_vnd,
        coalesce(p_payment_method, 'google_play'),
        'completed',
        nullif(trim(coalesce(p_purchase_token, '')), ''),
        p_order_ref,
        p_raw_receipt,
        now()
    )
    returning id into v_order_id;

    -- 5. Atomically increment user credits in profiles
    update public.profiles
    set credits = credits + v_total_credits
    where id = v_user_id
    returning credits into v_new_balance;

    -- 6. Insert audit record into credit_logs
    v_note := 'Nạp ' || v_total_credits || ' Credit (' || v_pkg.title || ')';
    if v_pkg.bonus_credits > 0 then
        v_note := v_note || ' - Tặng +' || v_pkg.bonus_credits || ' C';
    end if;

    insert into public.credit_logs (
        user_id,
        amount,
        action,
        note,
        balance
    )
    values (
        v_user_id,
        v_total_credits,
        'topup',
        v_note,
        v_new_balance
    );

    -- 7. Return success result
    return jsonb_build_object(
        'status', 'success',
        'order_id', v_order_id,
        'credits_awarded', v_total_credits,
        'current_balance', v_new_balance,
        'message', 'Nạp ' || v_total_credits || ' Credit thành công!'
    );
end;
$function$;

CREATE OR REPLACE FUNCTION public.publish_app_update(p_campaign_id uuid, p_version_name text, p_target_version_code bigint, p_release_notes text, p_client_operation_id text DEFAULT NULL::text, p_expected_current_release_id uuid DEFAULT 'ffffffff-ffff-ffff-ffff-ffffffffffff'::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_caller_id           uuid := auth.uid();
    v_camp                public.campaigns%rowtype;
    v_version_name_clean  text;
    v_release_notes_clean text;
    v_ctrl                record;
    v_active_rel          record;
    v_old_remaining       int := 0;
    v_owner_credits       int;
    v_owner_is_locked     boolean := false;
    v_effective_credits   int;
    v_new_release_id      uuid;
    v_new_release         public.app_update_releases%rowtype;
    v_refund_log_id       uuid;
    v_reserve_log_id      uuid;
    v_existing_op         record;
    c_sentinel            constant uuid := 'ffffffff-ffff-ffff-ffff-ffffffffffff'::uuid;
begin
    if v_caller_id is null then
        raise exception 'NOT_AUTHENTICATED';
    end if;

    -- Chuẩn hóa dữ liệu đầu vào trước khi so sánh
    v_version_name_clean := trim(coalesce(p_version_name, ''));
    if v_version_name_clean = '' or length(v_version_name_clean) > 100 then
        raise exception 'INVALID_VERSION_NAME';
    end if;

    if p_target_version_code is null or p_target_version_code <= 0 then
        raise exception 'INVALID_VERSION_CODE';
    end if;

    v_release_notes_clean := trim(coalesce(p_release_notes, ''));
    if v_release_notes_clean = '' or length(v_release_notes_clean) > 4000 then
        raise exception 'INVALID_RELEASE_NOTES';
    end if;

    -- R04: Kiểm tra idempotency theo client_operation_id
    if p_client_operation_id is not null and trim(p_client_operation_id) <> '' then
        select * into v_existing_op
        from public.app_update_operations
        where operation_id = trim(p_client_operation_id) and owner_id = v_caller_id;

        if v_existing_op.operation_id is not null then
            -- R04: Kiểm tra payload/fingerprint conflict
            if v_existing_op.campaign_id is distinct from p_campaign_id
               or v_existing_op.target_version_code is distinct from p_target_version_code
               or v_existing_op.version_name is distinct from v_version_name_clean
               or v_existing_op.release_notes is distinct from v_release_notes_clean
            then
                raise exception 'OPERATION_PAYLOAD_CONFLICT';
            end if;

            select * into v_new_release from public.app_update_releases where id = v_existing_op.release_id;
            select credits into v_owner_credits from public.profiles where id = v_caller_id;

            return jsonb_build_object(
                'success', true,
                'release', row_to_json(v_new_release),
                'owner_credits', v_owner_credits,
                'refund_amount', 0,
                'idempotent_replay', true
            );
        end if;
    end if;

    -- R10: Kiểm tra trạng thái tài khoản chủ app (dưới khóa profile)
    select credits, coalesce(is_locked, false)
    into v_owner_credits, v_owner_is_locked
    from public.profiles
    where id = v_caller_id
    for update;

    if v_owner_is_locked then
        raise exception 'USER_LOCKED';
    end if;

    -- R05: Thứ tự khóa 1 - Khóa và kiểm tra campaign
    select * into v_camp from public.campaigns where id = p_campaign_id for update;
    if v_camp.id is null then
        raise exception 'CAMPAIGN_NOT_FOUND';
    end if;

    if v_camp.owner_id <> v_caller_id then
        raise exception 'NOT_ACTUAL_OWNER';
    end if;

    if v_camp.status <> 'open' then
        raise exception 'CAMPAIGN_NOT_OPEN';
    end if;

    if v_camp.package_name is null or trim(v_camp.package_name) = '' then
        raise exception 'INVALID_PACKAGE_NAME';
    end if;

    -- R05: Thứ tự khóa 2 - Khóa hàng điều khiển app_update_controls
    insert into public.app_update_controls (owner_id, package_name, highest_version_code)
    values (v_caller_id, v_camp.package_name, 0)
    on conflict (owner_id, package_name) do nothing;

    select * into v_ctrl
    from public.app_update_controls
    where owner_id = v_caller_id and package_name = v_camp.package_name
    for update;

    -- R05: Kiểm tra CAS concurrency đầy đủ (bao gồm cả khi caller mong đợi null)
    if p_expected_current_release_id is distinct from c_sentinel then
        if p_expected_current_release_id is distinct from v_ctrl.active_release_id then
            raise exception 'CONCURRENT_UPDATE_CONFLICT';
        end if;
    end if;

    -- Kiểm tra watermark versionCode: phải lớn hơn bản công bố trước của cùng app
    if p_target_version_code <= v_ctrl.highest_version_code then
        raise exception 'VERSION_CODE_NOT_GREATER';
    end if;

    -- R05: Thứ tự khóa 3 - Khóa đợt cập nhật active hiện tại (nếu có)
    select * into v_active_rel
    from public.app_update_releases
    where owner_id = v_caller_id
      and package_name = v_camp.package_name
      and status = 'active'
    for update;

    if v_active_rel.id is not null then
        v_old_remaining := v_active_rel.remaining_credits;
    end if;

    -- R05: Thứ tự khóa 4 - Ví chủ app đã được khóa ở bước trên
    v_effective_credits := v_owner_credits + v_old_remaining;
    if v_effective_credits < 120 then
        raise exception 'INSUFFICIENT_CREDITS';
    end if;

    -- R09: Xử lý đợt active cũ: đổi sang superseded, hoàn phần chưa dùng
    if v_active_rel.id is not null then
        update public.app_update_releases
        set status = 'superseded',
            closed_at = now(),
            remaining_credits = 0,
            refunded_credits = refunded_credits + v_old_remaining
        where id = v_active_rel.id;

        if v_old_remaining > 0 then
            v_owner_credits := v_owner_credits + v_old_remaining;
            insert into public.credit_logs (user_id, amount, action, note, balance)
            values (
                v_caller_id,
                v_old_remaining,
                'app_update_refund',
                format('Hoàn %s Credit chưa dùng từ phiên bản %s (%s)', v_old_remaining, v_active_rel.version_name, v_camp.app_name),
                v_owner_credits
            )
            returning id into v_refund_log_id;

            insert into public.app_update_financial_events (
                release_id, event_type, amount, owner_id, credit_log_id, operation_id
            ) values (
                v_active_rel.id, 'refund', v_old_remaining, v_caller_id, v_refund_log_id, p_client_operation_id
            );
        end if;
    end if;

    -- R09: Đổi tất cả các đợt exhausted cũ của cùng package sang superseded để không bị chọn lại
    update public.app_update_releases
    set status = 'superseded'
    where owner_id = v_caller_id
      and package_name = v_camp.package_name
      and status in ('active', 'exhausted');

    -- Giữ trước 120 Credit từ ví chủ app cho đợt mới
    v_owner_credits := v_owner_credits - 120;
    update public.profiles set credits = v_owner_credits where id = v_caller_id;

    insert into public.credit_logs (user_id, amount, action, note, balance)
    values (
        v_caller_id,
        -120,
        'app_update_reserve',
        format('Giữ trước 120 Credit thưởng cập nhật phiên bản %s (%s)', v_version_name_clean, v_camp.app_name),
        v_owner_credits
    )
    returning id into v_reserve_log_id;

    -- Tạo đợt cập nhật mới
    insert into public.app_update_releases (
        campaign_id,
        owner_id,
        owner_id_snapshot,
        package_name,
        app_name,
        version_name,
        target_version_code,
        release_notes,
        status,
        reward_per_claim,
        max_claims,
        reserved_credits,
        paid_count,
        remaining_credits,
        refunded_credits,
        published_at
    ) values (
        p_campaign_id,
        v_caller_id,
        v_caller_id,
        v_camp.package_name,
        v_camp.app_name,
        v_version_name_clean,
        p_target_version_code,
        v_release_notes_clean,
        'active',
        6,
        20,
        120,
        0,
        120,
        0,
        now()
    )
    returning id into v_new_release_id;

    select * into v_new_release from public.app_update_releases where id = v_new_release_id;

    -- Ghi nhận financial event
    insert into public.app_update_financial_events (
        release_id, event_type, amount, owner_id, credit_log_id, operation_id
    ) values (
        v_new_release_id, 'reserve', 120, v_caller_id, v_reserve_log_id, p_client_operation_id
    );

    -- Cập nhật app_update_controls: watermark và active_release_id
    update public.app_update_controls
    set highest_version_code = greatest(v_ctrl.highest_version_code, p_target_version_code),
        active_release_id = v_new_release_id,
        updated_at = now()
    where owner_id = v_caller_id and package_name = v_camp.package_name;

    -- R04: Lưu operation_id kèm fingerprint đầy đủ
    if p_client_operation_id is not null and trim(p_client_operation_id) <> '' then
        insert into public.app_update_operations (
            operation_id, owner_id, release_id, status,
            campaign_id, target_version_code, version_name, release_notes
        )
        values (
            trim(p_client_operation_id), v_caller_id, v_new_release_id, 'completed',
            p_campaign_id, p_target_version_code, v_version_name_clean, v_release_notes_clean
        )
        on conflict (operation_id) do nothing;
    end if;

    return jsonb_build_object(
        'success', true,
        'release', row_to_json(v_new_release),
        'owner_credits', v_owner_credits,
        'refund_amount', v_old_remaining,
        'idempotent_replay', false
    );
end;
$function$;

CREATE OR REPLACE FUNCTION public.purge_completed_campaigns(p_retention_days integer DEFAULT 90, p_dry_run boolean DEFAULT false, p_batch_size integer DEFAULT 100)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_days int := greatest(1, coalesce(p_retention_days, 90));
    v_batch int := greatest(1, least(coalesce(p_batch_size, 100), 1000));
    v_dry_run boolean := coalesce(p_dry_run, false);
    v_run_id uuid;
    v_ids uuid[];
    v_scanned int := 0;
    v_deleted int := 0;
    v_errors jsonb := '[]'::jsonb;
    v_id uuid;
    v_row_count int;
    v_status text;
    v_stale_pending_count int := 0;
    v_expired_missions_count int := 0;
    v_camp_rec record;
begin
    -- Khóa chống race condition khi nhiều connection cùng gọi hàm purge (review point 5)
    perform pg_advisory_xact_lock(hashtextextended('purge_completed_campaigns', 0));

    -- (Review point 1): Dry-run chỉ được log và scan, TUYỆT ĐỐI không gọi sync_expired_missions()
    -- làm đổi dữ liệu nghiệp vụ. Chỉ gọi khi NOT dry_run.
    if not v_dry_run then
        begin
            v_expired_missions_count := public.sync_expired_missions();
        exception when others then
            v_expired_missions_count := -1;
        end;
    end if;

    -- Đếm số pending reports quá hạn > 7 ngày để theo dõi backlog (R07)
    begin
        select count(*)
        into v_stale_pending_count
        from public.tester_reports
        where status = 'pending'
          and created_at < now() - interval '7 days';
    exception when others then
        v_stale_pending_count := -1;
    end;

    insert into public.cleanup_runs (job_name, status, details)
    values (
        'purge_completed_campaigns',
        'running',
        jsonb_build_object(
            'retention_days', v_days,
            'batch_size', v_batch,
            'dry_run', v_dry_run,
            'expired_missions_synced', v_expired_missions_count,
            'stale_pending_reports_count', v_stale_pending_count
        )
    )
    returning id into v_run_id;

    begin
        -- Lọc campaign đủ điều kiện purge:
        -- 1. status completed/closed/production quá v_days ngày
        -- 2. không còn pending report
        -- 3. không có report nộp trong 1h qua (chống race condition khi tester vừa nộp)
        -- 4. không còn mission đang chạy (open/full/paused_by_creator) hoặc ends_at > now() (R03)
        -- 5. (Review point 3): Chống starvation:
        --    - Ưu tiên campaign chưa từng lỗi lên đầu (order by has_error asc)
        --    - Áp dụng exponential backoff (2^fail_count ngày, tối đa 14 ngày)
        select coalesce(array_agg(t.id), '{}'::uuid[])
        into v_ids
        from (
            select c.id
            from public.campaigns c
            where c.status in ('completed', 'closed', 'production')
              and coalesce(c.completed_at, c.created_at) < now() - make_interval(days => v_days)
              and not exists (
                  select 1
                  from public.tester_reports tr
                  where tr.campaign_id = c.id
                    and tr.status = 'pending'
              )
              and not exists (
                  select 1
                  from public.tester_reports tr
                  where tr.campaign_id = c.id
                    and tr.created_at > now() - interval '1 hour'
              )
              -- 4. Không còn mission nào chưa quá hạn ends_at (R03: mission đã quá hạn ends_at <= now() không chặn purge)
              and not exists (
                  select 1
                  from public.missions m
                  where m.campaign_id = c.id
                    and m.ends_at > now()
              )
              and not exists (
                  select 1
                  from (
                      select count(*) as fail_count, max(cr.started_at) as last_failed_at
                      from public.cleanup_runs cr,
                           jsonb_array_elements(cr.details->'errors') as err
                      where (err->>'campaign_id')::uuid = c.id
                        and cr.started_at > now() - interval '30 days'
                  ) f
                  where f.fail_count > 0
                    and f.last_failed_at > now() - make_interval(days => least(14, power(2, f.fail_count)::int))
              )
            order by
              -- Ưu tiên 1: Campaign chưa từng bị lỗi ưu tiên 0, có lỗi bị đẩy xuống sau (chống starvation)
              (case when exists (
                  select 1
                  from public.cleanup_runs cr,
                       jsonb_array_elements(cr.details->'errors') as err
                  where (err->>'campaign_id')::uuid = c.id
                    and cr.started_at > now() - interval '30 days'
              ) then 1 else 0 end) asc,
              coalesce(c.completed_at, c.created_at) asc,
              c.id asc
            limit v_batch
            for update skip locked
        ) t;

        v_scanned := coalesce(array_length(v_ids, 1), 0);

        if v_dry_run then
            update public.cleanup_runs
            set finished_at = now(),
                status = 'dry_run',
                scanned = v_scanned,
                details = details || jsonb_build_object('campaign_ids', to_jsonb(v_ids))
            where id = v_run_id;

            return v_scanned;
        end if;

        perform set_config('app.delete_reason', 'retention', true);

        foreach v_id in array v_ids loop
            begin
                -- Re-check trạng thái campaign trước khi delete thực tế
                select status, completed_at, created_at into v_camp_rec from public.campaigns where id = v_id for update;
                if v_camp_rec.status not in ('completed', 'closed', 'production')
                   or coalesce(v_camp_rec.completed_at, v_camp_rec.created_at) > now() - make_interval(days => v_days) then
                    continue;
                end if;

                delete from public.campaigns where id = v_id;
                get diagnostics v_row_count = row_count;
                v_deleted := v_deleted + v_row_count;
            exception when others then
                v_errors := v_errors || jsonb_build_array(
                    jsonb_build_object(
                        'campaign_id', v_id,
                        'error', left(sqlerrm, 500)
                    )
                );
            end;
        end loop;

        perform set_config('app.delete_reason', '', true);

        if jsonb_array_length(v_errors) = 0 then
            v_status := 'success';
        elsif v_deleted = 0 then
            v_status := 'failed';
        else
            v_status := 'partial';
        end if;

        update public.cleanup_runs
        set finished_at = now(),
            status = v_status,
            scanned = v_scanned,
            deleted = v_deleted,
            error = case
                when jsonb_array_length(v_errors) > 0
                    then 'One or more campaigns failed; see details.errors'
                else null
            end,
            details = details || jsonb_build_object('errors', v_errors)
        where id = v_run_id;

        return v_deleted;
    exception when others then
        perform set_config('app.delete_reason', '', true);

        update public.cleanup_runs
        set finished_at = now(),
            status = 'failed',
            scanned = v_scanned,
            error = left(sqlerrm, 2000)
        where id = v_run_id;

        raise warning 'purge_completed_campaigns failed: %', sqlerrm;
        return -1;
    end;
end;
$function$;

CREATE OR REPLACE FUNCTION public.push_campaign(p_campaign_id uuid, p_client_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_uid               uuid := auth.uid();
    v_existing_receipt  record;
    v_camp              public.campaigns%rowtype;
    v_profile           public.profiles%rowtype;
    v_now               timestamptz;
    v_business_date     date;
    v_expires_at        timestamptz;
    v_push_order        bigint;
    v_balance_after     int;
    v_credit_log_id     uuid;
    v_receipt_id        uuid;
    v_note              text;
begin
    -- 1. Yêu cầu phiên đăng nhập
    if v_uid is null then
        raise exception 'NOT_AUTHENTICATED';
    end if;

    if p_client_request_id is null then
        raise exception 'INVALID_REQUEST_ID';
    end if;

    if p_campaign_id is null then
        raise exception 'INVALID_CAMPAIGN_ID';
    end if;

    -- 2. Kiểm tra receipt trước khi khóa (so sánh target_campaign_id bất biến)
    select * into v_existing_receipt
    from public.campaign_push_receipts
    where user_id = v_uid and client_request_id = p_client_request_id;

    if v_existing_receipt.id is not null then
        if coalesce(v_existing_receipt.target_campaign_id, v_existing_receipt.campaign_id) is distinct from p_campaign_id then
            raise exception 'REQUEST_ID_CONFLICT';
        end if;
        return jsonb_build_object(
            'success', true,
            'receipt_id', v_existing_receipt.id,
            'client_request_id', v_existing_receipt.client_request_id,
            'campaign_id', p_campaign_id,
            'charged_credits', v_existing_receipt.cost_credits,
            'balance_after', v_existing_receipt.balance_after,
            'business_date', to_char(v_existing_receipt.business_date, 'YYYY-MM-DD'),
            'expires_at', to_char(v_existing_receipt.expires_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
            'push_order', v_existing_receipt.push_order,
            'replayed', true
        );
    end if;

    -- 3. Khóa campaign và profile theo thứ tự nhất quán
    select * into v_camp
    from public.campaigns
    where id = p_campaign_id
    for update;

    if v_camp.id is null then
        raise exception 'CAMPAIGN_NOT_FOUND';
    end if;

    select * into v_profile
    from public.profiles
    where id = v_uid
    for update;

    if v_profile.id is null then
        raise exception 'PROFILE_NOT_FOUND';
    end if;

    -- Re-check receipt sau khi đã có khóa
    select * into v_existing_receipt
    from public.campaign_push_receipts
    where user_id = v_uid and client_request_id = p_client_request_id;

    if v_existing_receipt.id is not null then
        if coalesce(v_existing_receipt.target_campaign_id, v_existing_receipt.campaign_id) is distinct from p_campaign_id then
            raise exception 'REQUEST_ID_CONFLICT';
        end if;
        return jsonb_build_object(
            'success', true,
            'receipt_id', v_existing_receipt.id,
            'client_request_id', v_existing_receipt.client_request_id,
            'campaign_id', p_campaign_id,
            'charged_credits', v_existing_receipt.cost_credits,
            'balance_after', v_existing_receipt.balance_after,
            'business_date', to_char(v_existing_receipt.business_date, 'YYYY-MM-DD'),
            'expires_at', to_char(v_existing_receipt.expires_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
            'push_order', v_existing_receipt.push_order,
            'replayed', true
        );
    end if;

    -- 4. Kiểm tra chủ thật và trạng thái tài khoản
    if v_camp.owner_id is distinct from v_uid then
        raise exception 'NOT_OWNER';
    end if;

    if coalesce(v_profile.is_locked, false) = true then
        raise exception 'ACCOUNT_LOCKED';
    end if;

    if v_camp.status <> 'open' then
        raise exception 'CAMPAIGN_NOT_OPEN';
    end if;

    -- 5. Kiểm tra số dư (dưới 100 từ chối hoàn toàn; đúng 100 cho phép)
    if coalesce(v_profile.credits, 0) < 100 then
        raise exception 'INSUFFICIENT_CREDITS';
    end if;

    -- 6. Khóa transaction chung cho việc cấp thứ tự đẩy
    perform pg_advisory_xact_lock(hashtext('campaign_push_order_lock'));

    v_now := clock_timestamp();
    v_business_date := (v_now at time zone 'Asia/Ho_Chi_Minh')::date;
    v_expires_at := (date_trunc('day', v_now at time zone 'Asia/Ho_Chi_Minh') + interval '1 day') at time zone 'Asia/Ho_Chi_Minh';

    -- Kiểm tra lại điều kiện thời gian sau khi có khóa và đồng hồ mới
    if v_camp.created_at <= v_now - interval '30 days' then
        raise exception 'CAMPAIGN_WINDOW_EXPIRED';
    end if;

    if v_camp.slot_number > 1 then
        if not exists (
            select 1 from public.user_slots
            where user_id = v_camp.owner_id
              and slot_number = v_camp.slot_number
              and expires_at > v_now
        ) then
            raise exception 'SLOT_EXPIRED';
        end if;
    end if;

    v_push_order := nextval('public.campaign_push_order_seq');

    -- 7. Trừ đúng 100 Credit, ghi log, cập nhật metadata campaign, ghi receipt
    update public.profiles
    set credits = credits - 100
    where id = v_uid
    returning credits into v_balance_after;

    v_note := format('Đẩy ứng dụng "%s" lên đầu danh sách (hạn đến hết %s)',
                     coalesce(nullif(v_camp.app_name, ''), 'của bạn'),
                     to_char(v_business_date, 'DD/MM/YYYY'));

    insert into public.credit_logs (user_id, amount, action, note, balance)
    values (v_uid, -100, 'campaign_push', v_note, v_balance_after)
    returning id into v_credit_log_id;

    perform set_config('app.allow_push_metadata_write', 'true', true);

    update public.campaigns
    set push_business_date = v_business_date,
        push_expires_at = v_expires_at,
        push_order = v_push_order
    where id = p_campaign_id;

    perform set_config('app.allow_push_metadata_write', 'false', true);

    insert into public.campaign_push_receipts (
        user_id,
        campaign_id,
        target_campaign_id,
        client_request_id,
        cost_credits,
        balance_after,
        business_date,
        pushed_at,
        expires_at,
        push_order,
        credit_log_id
    )
    values (
        v_uid,
        p_campaign_id,
        p_campaign_id,
        p_client_request_id,
        100,
        v_balance_after,
        v_business_date,
        v_now,
        v_expires_at,
        v_push_order,
        v_credit_log_id
    )
    returning id into v_receipt_id;

    -- 8. Trả về kết quả hoàn chỉnh
    return jsonb_build_object(
        'success', true,
        'receipt_id', v_receipt_id,
        'client_request_id', p_client_request_id,
        'campaign_id', p_campaign_id,
        'charged_credits', 100,
        'balance_after', v_balance_after,
        'business_date', to_char(v_business_date, 'YYYY-MM-DD'),
        'expires_at', to_char(v_expires_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
        'push_order', v_push_order,
        'replayed', false
    );
end;
$function$;

CREATE OR REPLACE FUNCTION public.record_daily_login()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_uid uuid := auth.uid();
begin
    if v_uid is null then
        raise exception 'NOT_AUTHENTICATED';
    end if;

    perform public.record_daily_login_internal(
        v_uid,
        (now() at time zone 'Asia/Ho_Chi_Minh')::date
    );
end;
$function$;

CREATE OR REPLACE FUNCTION public.record_daily_login_internal(p_user_id uuid, p_date date DEFAULT NULL::date)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_date date := coalesce(
        p_date,
        (now() at time zone 'Asia/Ho_Chi_Minh')::date
    );
begin
    if p_user_id is null then
        return;
    end if;

    -- Auth user có thể chưa có profile (signup dở dang): bỏ qua thay vì lỗi FK.
    if not exists (select 1 from public.profiles where id = p_user_id) then
        return;
    end if;

    update public.profiles
    set last_login_date = v_date
    where id = p_user_id
      and (last_login_date is null or last_login_date < v_date);

    insert into public.user_daily_tasks as t (user_id, task_date, logged_in, finalized_at)
    values (p_user_id, v_date, true, null)
    on conflict (user_id, task_date) do update
    set logged_in = true
    where t.finalized_at is null;

    perform public.refresh_daily_completion(p_user_id, v_date);
end;
$function$;

CREATE OR REPLACE FUNCTION public.refresh_daily_completion(p_user_id uuid, p_date date DEFAULT NULL::date)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_today date := (now() at time zone 'Asia/Ho_Chi_Minh')::date;
    v_date date := coalesce(p_date, v_today);
    v_status jsonb;
begin
    if p_user_id is null then
        return;
    end if;

    -- Chỉ đặt lại chuỗi hiện tại khi nhiệm vụ của đúng hôm nay đã đạt.
    -- Tránh checkin/backfill của ngày cũ vô tình xoá chuỗi hiện tại.
    if v_date <> v_today then
        return;
    end if;

    v_status := public.get_daily_task_status(p_user_id, v_date);
    if v_status is not null
       and coalesce((v_status ->> 'met')::boolean, false) then
        update public.profiles
        set daily_missed_streak = 0
        where id = p_user_id
          and daily_missed_streak <> 0;
    end if;
end;
$function$;

CREATE OR REPLACE FUNCTION public.reject_daily_task_policy_history_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
    raise exception 'DAILY_TASK_POLICY_HISTORY_IMMUTABLE';
end;
$function$;

CREATE OR REPLACE FUNCTION public.reject_tester_report(p_report_id uuid, p_reason text DEFAULT NULL::text, p_reason_code text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_caller_id uuid := auth.uid();
    v_caller_role text;
    v_report record;
    v_camp record;
    v_tester_credits int;
    v_deduct int := 0;
    v_new_balance int;
    v_report_date date;
    v_vn_today date := (now() at time zone 'Asia/Ho_Chi_Minh')::date;

    v_extracted_code text;
    v_final_reason_code text;

    v_tester_today_rejections int := 0;
    v_tester_warned boolean := false;
    v_tester_warning_msg text := null;
    v_tester_weekly_warnings int := 0;
    v_is_tester_locked boolean := false;

    v_owner_today_rejections int := 0;
    v_owner_warned boolean := false;
    v_owner_warning_msg text := null;
    v_owner_weekly_warnings int := 0;
    v_is_owner_locked boolean := false;

    v_msg_tester text := 'Hệ thống ghi nhận bạn tham gia kiểm thử chưa nghiêm túc, đề nghị test app nghiêm túc và chụp ảnh màn hình không trùng với ảnh đã chụp hôm trước (nên chụp các tính năng khác của ứng dụng kiểm thử). Nếu trong 1 tuần bạn bị 3 lần cảnh báo như thế này thì tài khoản của bạn sẽ bị tạm khóa';
    v_msg_owner text := 'Hệ thống ghi nhận bạn xác nhận kết quả của người kiểm thử chưa nghiêm túc, đề nghị đối chiếu kỹ ảnh chụp của người kiểm thử chụp các ngày khác nhau để duyệt cho chính xác. Nếu trong 1 tuần bạn bị 3 lần cảnh báo như thế này thì tài khoản của bạn sẽ bị tạm khóa';
begin
    if v_caller_id is null then
        raise exception 'NOT_AUTHENTICATED';
    end if;

    select * into v_report
    from public.tester_reports
    where id = p_report_id
    for update;

    if v_report.id is null then
        raise exception 'REPORT_NOT_FOUND';
    end if;

    if v_report.status <> 'pending' then
        raise exception 'REPORT_ALREADY_REVIEWED';
    end if;

    select * into v_camp
    from public.campaigns
    where id = v_report.campaign_id;

    select role into v_caller_role
    from public.profiles
    where id = v_caller_id;

    if v_camp.owner_id <> v_caller_id
       and lower(coalesce(v_caller_role, '')) not in ('admin', 'moderator') then
        raise exception 'PERMISSION_DENIED';
    end if;

    -- Quá 8h: không cho từ chối tay, để auto_accept xử lý.
    if v_report.created_at <= (now() - interval '8 hours') then
        raise exception 'REPORT_EXPIRED';
    end if;

    -- Xác định reason_code: ưu tiên p_reason_code, sau đó trích xuất từ [CODE:...] trong p_reason
    if p_reason is not null and p_reason like '[CODE:%]' then
        v_extracted_code := substring(p_reason from '\[CODE:([A-Za-z0-9_]+)\]');
    end if;
    v_final_reason_code := coalesce(p_reason_code, v_extracted_code);

    -- Ghi audit TRƯỚC khi tính cảnh báo: event này cũng được tính vào hôm nay.
    insert into public.report_review_events (
        report_id, campaign_id, tester_id, owner_id, reviewer_id, event_type, reason
    ) values (
        v_report.id, v_report.campaign_id, v_report.user_id,
        v_camp.owner_id, v_caller_id, 'reject', p_reason
    );

    v_report_date := (v_report.created_at at time zone 'Asia/Ho_Chi_Minh')::date;

    -- 1. Thu hồi đúng số Credit THỰC đã cấp khi nộp (10 mới, 2 cũ).
    select credits into v_tester_credits
    from public.profiles
    where id = v_report.user_id
    for update;

    v_deduct := least(
        coalesce(v_tester_credits, 0),
        greatest(0, least(10, coalesce(v_report.provisional_granted_credits, 2)))
    );

    if v_deduct > 0 then
        update public.profiles
        set credits = credits - v_deduct
        where id = v_report.user_id
        returning credits into v_new_balance;

        insert into public.credit_logs (user_id, amount, action, note, balance, metadata)
        values (
            v_report.user_id,
            -v_deduct,
            'test_rejected_clawback',
            format('Thu hồi %s Credit tạm nhận do báo cáo bị từ chối: %s', v_deduct, coalesce(p_reason, 'Chưa đạt yêu cầu')),
            v_new_balance,
            jsonb_build_object('report_id', v_report.id, 'campaign_id', v_camp.id, 'reason_code', v_final_reason_code)
        );
    else
        v_new_balance := coalesce(v_tester_credits, 0);
    end if;

    -- 2. Cập nhật trạng thái báo cáo thành rejected với reason_code
    update public.tester_reports
    set status = 'rejected',
        rejection_reason = p_reason,
        reason_code = v_final_reason_code,
        bonus_awarded = 0,
        provisional_clawed = v_deduct,
        reviewed_at = now()
    where id = p_report_id;

    -- 3. Chỉ xóa checkin TẠM TÍNH (không xóa checkin xác nhận khác trong ngày)
    delete from public.checkins
    where campaign_id = v_report.campaign_id
      and user_id = v_report.user_id
      and checkin_date = v_report_date
      and coalesce(note, '') like '%tạm tính%';

    -- 4. Cảnh báo tester: đếm từ audit event (không bị reset khi nộp lại)
    select count(*) into v_tester_today_rejections
    from public.report_review_events
    where tester_id = v_report.user_id
      and event_type = 'reject'
      and (created_at at time zone 'Asia/Ho_Chi_Minh')::date = v_vn_today;

    if v_tester_today_rejections >= 3 then
        if not exists (
            select 1 from public.user_warnings
            where user_id = v_report.user_id
              and warning_type = 'tester_rejection_streak'
              and warning_date = v_vn_today
        ) then
            insert into public.user_warnings (user_id, warning_type, message, warning_date, metadata)
            values (
                v_report.user_id,
                'tester_rejection_streak',
                v_msg_tester,
                v_vn_today,
                jsonb_build_object('warning_type', 'tester_rejection_streak', 'streak_count', v_tester_today_rejections)
            );
            v_tester_warned := true;
            v_tester_warning_msg := v_msg_tester;

            select count(*) into v_tester_weekly_warnings
            from public.user_warnings
            where user_id = v_report.user_id
              and warning_date >= (v_vn_today - 6);

            if v_tester_weekly_warnings >= 3 then
                update public.profiles
                set is_locked = true
                where id = v_report.user_id;
                v_is_tester_locked := true;
            end if;
        end if;
    end if;

    -- 5. Cảnh báo chủ app: đếm từ audit event
    select count(*) into v_owner_today_rejections
    from public.report_review_events
    where owner_id = v_camp.owner_id
      and event_type = 'reject'
      and (created_at at time zone 'Asia/Ho_Chi_Minh')::date = v_vn_today;

    if v_owner_today_rejections >= 5 then
        if not exists (
            select 1 from public.user_warnings
            where user_id = v_camp.owner_id
              and warning_type = 'owner_rejection_streak'
              and warning_date = v_vn_today
        ) then
            insert into public.user_warnings (user_id, warning_type, message, warning_date, metadata)
            values (
                v_camp.owner_id,
                'owner_rejection_streak',
                v_msg_owner,
                v_vn_today,
                jsonb_build_object('warning_type', 'owner_rejection_streak', 'streak_count', v_owner_today_rejections)
            );
            v_owner_warned := true;
            v_owner_warning_msg := v_msg_owner;

            select count(*) into v_owner_weekly_warnings
            from public.user_warnings
            where user_id = v_camp.owner_id
              and warning_date >= (v_vn_today - 6);

            if v_owner_weekly_warnings >= 3 then
                update public.profiles
                set is_locked = true
                where id = v_camp.owner_id;
                v_is_owner_locked := true;
            end if;
        end if;
    end if;

    -- R02: Trả đầy đủ cả khóa cũ (credits_deducted, tester_balance, is_tester_locked, is_owner_locked...)
    -- lẫn khóa alias mới (clawed_credits, new_balance, tester_locked, owner_locked...)
    return jsonb_build_object(
        'success', true,
        'report_id', v_report.id,
        'campaign_id', v_camp.id,
        'tester_id', v_report.user_id,
        'status', 'rejected',
        'credits_deducted', v_deduct,
        'clawed_credits', v_deduct,
        'tester_balance', v_new_balance,
        'new_balance', v_new_balance,
        'reason_code', v_final_reason_code,
        'tester_today_rejections', v_tester_today_rejections,
        'tester_warned', v_tester_warned,
        'tester_warning_msg', v_tester_warning_msg,
        'is_tester_locked', v_is_tester_locked,
        'tester_locked', v_is_tester_locked,
        'owner_today_rejections', v_owner_today_rejections,
        'owner_warned', v_owner_warned,
        'owner_warning_msg', v_owner_warning_msg,
        'is_owner_locked', v_is_owner_locked,
        'owner_locked', v_is_owner_locked
    );
end;
$function$;

CREATE OR REPLACE FUNCTION public.resume_campaign(p_campaign_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_uid uuid := auth.uid();
    v_camp record;
    v_missed int;
    v_today date := (now() at time zone 'Asia/Ho_Chi_Minh')::date;
    v_status jsonb;
begin
    if v_uid is null then
        raise exception 'NOT_AUTHENTICATED';
    end if;

    select * into v_camp from public.campaigns where id = p_campaign_id for update;
    if v_camp.id is null then
        raise exception 'CAMPAIGN_NOT_FOUND';
    end if;
    if v_camp.owner_id <> v_uid then
        raise exception 'PERMISSION_DENIED';
    end if;
    if v_camp.status <> 'paused' then
        raise exception 'CAMPAIGN_NOT_PAUSED';
    end if;

    if v_camp.paused_reason = 'admin_manual' then
        raise exception 'PAUSED_BY_ADMIN';
    end if;

    if v_camp.created_at <= now() - interval '30 days' then
        update public.campaigns
        set status = 'completed',
            completed_at = now(),
            paused_reason = null,
            admin_note = null,
            admin_resumed = false
        where id = p_campaign_id;

        return jsonb_build_object(
            'success', true,
            'campaign_id', p_campaign_id,
            'status', 'completed'
        );
    end if;

    if v_camp.slot_number > 1 then
        if not exists (
            select 1 from public.user_slots s
            where s.user_id = v_camp.owner_id
              and s.slot_number = v_camp.slot_number
              and s.expires_at > now()
        ) then
            raise exception 'SLOT_EXPIRED';
        end if;
    end if;

    -- R03: Nếu bị pause vì owner_inactive, bắt buộc phải kiểm tra nhiệm vụ hôm nay
    if v_camp.paused_reason = 'owner_inactive' then
        v_status := public.get_daily_task_status(v_uid, v_today);
        if coalesce((v_status ->> 'carryover_ready')::boolean, true) = false then
            raise exception 'DAILY_TASK_PENDING';
        end if;
        if coalesce((v_status ->> 'met')::boolean, false) = false then
            raise exception 'OWNER_INACTIVE';
        end if;
    end if;

    perform public.refresh_daily_completion(v_uid, v_today);

    select daily_missed_streak into v_missed
    from public.profiles
    where id = v_uid;

    if coalesce(v_missed, 0) >= 7 then
        raise exception 'OWNER_INACTIVE';
    end if;

    update public.campaigns
    set status = 'open',
        paused_reason = null,
        completed_at = null,
        admin_note = null,
        admin_resumed = false
    where id = p_campaign_id;

    return jsonb_build_object(
        'success', true,
        'campaign_id', p_campaign_id,
        'status', 'open'
    );
end;
$function$;

CREATE OR REPLACE FUNCTION public.resume_mission(p_mission_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_user_id uuid := auth.uid();
    v_mission record;
    v_camp record;
    v_new_status text;
begin
    if v_user_id is null then
        raise exception 'Not authenticated';
    end if;

    select * into v_mission
    from public.missions
    where id = p_mission_id
    for update;

    if v_mission.id is null or v_mission.status = 'deleted' then
        raise exception 'MISSION_NOT_FOUND';
    end if;

    if v_mission.creator_id <> v_user_id then
        raise exception 'PERMISSION_DENIED';
    end if;

    if v_mission.status <> 'paused_by_creator' then
        raise exception 'MISSION_NOT_PAUSED';
    end if;

    -- Bảo toàn sửa 043: nếu đã hết hạn, cập nhật DB và trả kết quả JSON, không rollback UPDATE
    if v_mission.ends_at <= now() then
        update public.missions
        set status = 'expired'
        where id = p_mission_id;

        return jsonb_build_object(
            'success', false,
            'code', 'MISSION_EXPIRED',
            'error', 'MISSION_EXPIRED',
            'message', 'Nhiệm vụ đã hết hạn lưu hành',
            'mission_id', p_mission_id,
            'status', 'expired'
        );
    end if;

    -- Khóa campaign row
    select * into v_camp
    from public.campaigns
    where id = v_mission.campaign_id
    for update;

    if v_camp.id is null then
        raise exception 'CAMPAIGN_NOT_FOUND';
    end if;
    if v_camp.status <> 'open' then
        raise exception 'CAMPAIGN_NOT_OPEN';
    end if;

    -- M02: Đồng bộ hết hạn trên campaign trước khi kiểm tra xung đột
    update public.missions
    set status = 'expired'
    where campaign_id = v_mission.campaign_id
      and id <> p_mission_id
      and status in ('open', 'full', 'paused_by_creator')
      and ends_at <= now();

    if exists (
        select 1 from public.missions
        where campaign_id = v_mission.campaign_id
          and id <> p_mission_id
          and status in ('open', 'full')
    ) then
        raise exception 'MISSION_ALREADY_EXISTS';
    end if;

    v_new_status := case when v_mission.participant_count >= v_mission.max_participants
                         then 'full' else 'open' end;

    update public.missions
    set status = v_new_status
    where id = p_mission_id;

    return jsonb_build_object(
        'success', true,
        'mission_id', p_mission_id,
        'status', v_new_status
    );
end;
$function$;

CREATE OR REPLACE FUNCTION public.retry_failed_mission_settlements(p_limit integer DEFAULT 50)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_job record;
    v_success_count int := 0;
    v_res jsonb;
begin
    for v_job in
        select id, report_id
        from public.mission_settlement_jobs
        where status in ('pending', 'failed')
          and attempt_count < 10
          and next_attempt_at <= now()
        order by next_attempt_at asc, created_at asc
        limit p_limit
        for update skip locked
    loop
        v_res := public._settle_mission_reward(v_job.report_id);
        if coalesce((v_res->>'settled')::boolean, false) and coalesce((v_res->>'paid')::boolean, false) then
            v_success_count := v_success_count + 1;
        end if;
    end loop;

    return v_success_count;
end;
$function$;

CREATE OR REPLACE FUNCTION public.schedule_daily_task_policy(p_tests_per_active_app integer, p_effective_from date, p_operator_note text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
    v_policy public.daily_task_policies;
begin
    perform pg_advisory_xact_lock(hashtextextended('daily_task_policy_schedule', 0));
    if p_tests_per_active_app is null or p_tests_per_active_app not between 1 and 30 then
        raise exception 'DAILY_TASK_POLICY_INVALID_RATIO';
    end if;
    if p_effective_from is null or not isfinite(p_effective_from)
       or p_effective_from <= (clock_timestamp() at time zone 'Asia/Ho_Chi_Minh')::date then
        raise exception 'DAILY_TASK_POLICY_FUTURE_DATE_REQUIRED';
    end if;
    if p_operator_note is null or length(btrim(p_operator_note)) not between 1 and 1000 then
        raise exception 'DAILY_TASK_POLICY_NOTE_REQUIRED';
    end if;
    -- UPDATE first: INSERT ... ON CONFLICT would execute a BEFORE INSERT
    -- trigger before discovering a conflict. Both paths remain fully audited.
    update public.daily_task_policies
    set tests_per_active_app = p_tests_per_active_app, operator_note = btrim(p_operator_note)
    where effective_from = p_effective_from
    returning * into v_policy;
    if not found then
        insert into public.daily_task_policies (
            effective_from, tests_per_active_app, operator_note
        ) values (p_effective_from, p_tests_per_active_app, btrim(p_operator_note))
        on conflict (effective_from) do update
        set tests_per_active_app = excluded.tests_per_active_app,
            operator_note = excluded.operator_note
        returning * into v_policy;
    end if;
    return to_jsonb(v_policy);
end;
$function$;

CREATE OR REPLACE FUNCTION public.self_unlock_account()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_caller_id uuid := auth.uid();
    v_current_credits int;
    v_new_balance int;
    v_is_locked boolean;
begin
    if v_caller_id is null then
        raise exception 'NOT_AUTHENTICATED';
    end if;

    select credits, is_locked into v_current_credits, v_is_locked
    from public.profiles
    where id = v_caller_id
    for update;

    if v_is_locked is not true then
        raise exception 'ACCOUNT_NOT_LOCKED';
    end if;

    if v_current_credits is null or v_current_credits < 100 then
        raise exception 'INSUFFICIENT_CREDITS: Cần tối thiểu 100 Credit để mở khóa tài khoản';
    end if;

    v_new_balance := v_current_credits - 100;

    -- Unlock account and deduct credits
    update public.profiles
    set credits = v_new_balance,
        is_locked = false
    where id = v_caller_id;

    -- Record credit log
    insert into public.credit_logs (user_id, amount, action, note, balance)
    values (
        v_caller_id,
        -100,
        'self_unlock_penalty',
        'Trừ 100 Credit để mở khóa tài khoản',
        v_new_balance
    );

    -- Reset weekly warnings so user is not immediately re-locked
    update public.user_warnings
    set acknowledged = true
    where user_id = v_caller_id
      and warning_date >= (current_date - 6);

    return jsonb_build_object(
        'success', true,
        'user_id', v_caller_id,
        'previous_credits', v_current_credits,
        'new_credits', v_new_balance,
        'is_locked', false
    );
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_campaign_tip(p_campaign_id uuid, p_tip_credits integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_uid uuid := auth.uid();
    v_role text;
    v_camp record;
begin
    if v_uid is null then
        raise exception 'NOT_AUTHENTICATED';
    end if;

    if p_tip_credits is null or p_tip_credits not in (0, 1, 2, 3, 5, 10) then
        raise exception 'INVALID_TIP_AMOUNT: Mức tip chỉ nhận 0/1/2/3/5/10 Credit.';
    end if;

    select * into v_camp from public.campaigns where id = p_campaign_id;
    if v_camp.id is null then
        raise exception 'CAMPAIGN_NOT_FOUND';
    end if;

    select role into v_role from public.profiles where id = v_uid;
    if v_camp.owner_id <> v_uid and lower(coalesce(v_role, '')) <> 'admin' then
        raise exception 'PERMISSION_DENIED';
    end if;

    update public.campaigns
    set tip_credits = p_tip_credits,
        is_boosted = (p_tip_credits > 0)
    where id = p_campaign_id;

    return jsonb_build_object(
        'success', true,
        'campaign_id', p_campaign_id,
        'tip_credits', p_tip_credits,
        'is_boosted', p_tip_credits > 0
    );
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_daily_task_carryover_policy(p_effective_from date, p_is_enabled boolean DEFAULT true, p_operator_note text DEFAULT 'Configured carryover policy'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_today date := (now() at time zone 'Asia/Ho_Chi_Minh')::date;
    v_old public.daily_task_carryover_policies;
    v_row public.daily_task_carryover_policies;
    v_allow_retro boolean := (current_setting('test.allow_policy_retroactive_write', true) = 'true');
begin
    if p_effective_from is null then
        raise exception 'INVALID_EFFECTIVE_DATE';
    end if;

    select * into v_old
    from public.daily_task_carryover_policies
    where effective_from = p_effective_from;

    -- Chặn sửa hồi tố chính sách quá khứ đã áp dụng (trừ khi bật cờ test)
    if p_effective_from <= v_today and v_old.id is not null and not v_allow_retro then
        raise exception 'CANNOT_MODIFY_HISTORICAL_POLICY: Chinh sach da co hieu luc khong the sua doi hoi to';
    end if;

    insert into public.daily_task_carryover_policies (
        effective_from, is_enabled, operator_note
    ) values (
        p_effective_from,
        coalesce(p_is_enabled, true),
        coalesce(btrim(p_operator_note), 'Configured carryover policy')
    )
    on conflict (effective_from) do update
    set is_enabled = excluded.is_enabled,
        operator_note = excluded.operator_note
    returning * into v_row;

    insert into public.daily_task_carryover_policy_audit (
        policy_id, effective_from, old_is_enabled, new_is_enabled,
        old_operator_note, new_operator_note, changed_by, changed_at
    ) values (
        v_row.id, p_effective_from, v_old.is_enabled, v_row.is_enabled,
        v_old.operator_note, v_row.operator_note, current_user, clock_timestamp()
    );

    return to_jsonb(v_row);
end;
$function$;

CREATE OR REPLACE FUNCTION public.submit_tester_report(p_campaign_id uuid, p_content text DEFAULT ''::text, p_screenshot_url text DEFAULT NULL::text, p_rating integer DEFAULT 5, p_image_hash text DEFAULT NULL::text, p_client_submit_id uuid DEFAULT NULL::uuid, p_thumbnail_url text DEFAULT NULL::text, p_mission_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_user_id uuid := auth.uid();
    v_report_id uuid;
    v_today date := (now() at time zone 'Asia/Ho_Chi_Minh')::date;
    v_camp record;
    v_existing_report record;
    v_idempotent_report record;
    v_receipt record;
    v_fingerprint text;
    v_already_checked_in boolean := false;
    v_status text := 'pending';
    v_rating int := greatest(1, least(5, coalesce(p_rating, 5)));
    v_new_balance int;
    v_provisional_granted boolean := false;
    v_provisional_amount int := 0;
    v_provisional_reward int := 10;
    v_regrant int := 0;
    v_new_screenshot boolean := false;
    v_effective_full text;
    v_final_url text;
    v_final_hash text;
    v_final_thumb text;

    -- Mission context variables
    v_mission record;
    v_mp record;
    v_eligible_count int := 0;
    v_submission_context text := 'app_test';
    v_target_mission_id uuid := null;
    v_target_mp_id uuid := null;
    v_target_title text := null;
    v_target_reward int := null;
    v_target_ends_at timestamptz := null;
    v_check_m record;
    v_res_context text;
    v_res_mission_id uuid;
    v_res_title text;
    v_res_reward int;
    v_res_ends_at timestamptz;
    v_result jsonb;
begin
    if v_user_id is null then
        raise exception 'NOT_AUTHENTICATED';
    end if;

    -- Tính payload fingerprint
    v_fingerprint := encode(digest(format('%s|%s|%s|%s|%s|%s|%s',
        p_campaign_id,
        coalesce(p_content, ''),
        coalesce(p_screenshot_url, ''),
        coalesce(p_rating, 5),
        coalesce(lower(p_image_hash), ''),
        coalesce(p_thumbnail_url, ''),
        coalesce(p_mission_id::text, '')
    ), 'sha256'), 'hex');

    -- Idempotency check qua durable receipt ledger
    if p_client_submit_id is not null then
        select * into v_receipt
        from public.report_submission_receipts
        where user_id = v_user_id
          and client_submit_id = p_client_submit_id
        limit 1;

        if v_receipt.id is not null then
            if v_receipt.campaign_id <> p_campaign_id then
                raise exception 'CLIENT_SUBMIT_ID_MISMATCH';
            end if;
            if v_receipt.payload_fingerprint = v_fingerprint then
                return v_receipt.response_json;
            end if;

            -- Nếu receipt là legacy_backfill: hỗ trợ semantics legacy an toàn (B01, B02, P02)
            if v_receipt.provenance = 'legacy_backfill' then
                declare
                    v_resp_mission text := coalesce(v_receipt.response_json ->> 'mission_id', '');
                    v_resp_url text := coalesce(v_receipt.response_json ->> 'screenshot_url', '');
                    v_resp_hash text := coalesce(lower(v_receipt.response_json ->> 'image_hash'), '');
                    v_resp_thumb text := coalesce(v_receipt.response_json ->> 'thumbnail_url', '');
                    v_resp_status text := coalesce(v_receipt.response_json ->> 'status', '');
                    v_eff_mission text := case when p_mission_id is null then v_resp_mission else p_mission_id::text end;
                    v_eff_url text := case when p_screenshot_url is null then v_resp_url else p_screenshot_url end;
                    v_eff_hash text := case when p_image_hash is null then v_resp_hash else lower(p_image_hash) end;
                    v_eff_thumb text := case when p_thumbnail_url is null then v_resp_thumb else p_thumbnail_url end;
                    v_eff_rating int;
                    v_legacy_fp text;
                begin
                    -- Với báo cáo đã duyệt (approved): thao tác bổ sung comment giữ nguyên rating đã khóa
                    if v_resp_status = 'approved' then
                        select rating into v_eff_rating from public.tester_reports where id = v_receipt.report_id;
                        if v_eff_rating is null then
                            v_eff_rating := coalesce((v_receipt.response_json ->> 'rating')::int, 5);
                        end if;
                    else
                        v_eff_rating := coalesce(p_rating, 5);
                    end if;

                    if (p_screenshot_url is null or p_screenshot_url = v_resp_url)
                       and (p_image_hash is null or lower(p_image_hash) = v_resp_hash)
                       and (p_thumbnail_url is null or p_thumbnail_url = v_resp_thumb)
                       and (p_mission_id is null or p_mission_id::text = v_resp_mission)
                       and (v_resp_status = 'approved' or p_rating is null or p_rating = v_eff_rating)
                    then
                        v_legacy_fp := encode(digest(format('%s|%s|%s|%s|%s|%s|%s',
                            p_campaign_id,
                            coalesce(p_content, ''),
                            v_eff_url,
                            v_eff_rating,
                            v_eff_hash,
                            v_eff_thumb,
                            v_eff_mission
                        ), 'sha256'), 'hex');

                        if v_receipt.payload_fingerprint = v_legacy_fp then
                            return v_receipt.response_json;
                        end if;
                    end if;
                end;
            end if;

            raise exception 'CLIENT_SUBMIT_ID_PAYLOAD_MISMATCH';
        end if;

        -- Fallback check tester_reports cho legacy submissions
        select * into v_idempotent_report
        from public.tester_reports
        where user_id = v_user_id
          and client_submit_id = p_client_submit_id
        limit 1;

        if v_idempotent_report.id is not null then
            if v_idempotent_report.campaign_id <> p_campaign_id then
                raise exception 'CLIENT_SUBMIT_ID_MISMATCH';
            end if;
            if p_mission_id is not null and v_idempotent_report.mission_id is distinct from p_mission_id then
                raise exception 'CLIENT_SUBMIT_ID_MISMATCH';
            end if;
            if coalesce(v_idempotent_report.content, '') <> coalesce(p_content, '') then
                raise exception 'CLIENT_SUBMIT_ID_PAYLOAD_MISMATCH';
            end if;
            if p_rating is not null and v_idempotent_report.rating is not null and v_idempotent_report.rating <> v_rating then
                raise exception 'CLIENT_SUBMIT_ID_PAYLOAD_MISMATCH';
            end if;
            if p_image_hash is not null and v_idempotent_report.image_hash is not null and lower(v_idempotent_report.image_hash) <> lower(p_image_hash) then
                raise exception 'CLIENT_SUBMIT_ID_PAYLOAD_MISMATCH';
            end if;
            if p_screenshot_url is not null and v_idempotent_report.screenshot_url is not null and v_idempotent_report.screenshot_url <> p_screenshot_url then
                raise exception 'CLIENT_SUBMIT_ID_PAYLOAD_MISMATCH';
            end if;

            v_result := jsonb_build_object(
                'success', true,
                'report_id', v_idempotent_report.id,
                'status', v_idempotent_report.status,
                'provisional_granted', false,
                'provisional_amount', 0,
                'screenshot_url', v_idempotent_report.screenshot_url,
                'image_hash', v_idempotent_report.image_hash,
                'thumbnail_url', v_idempotent_report.thumbnail_url,
                'submission_context', v_idempotent_report.submission_context,
                'mission_id', v_idempotent_report.mission_id,
                'mission_title', v_idempotent_report.mission_title,
                'mission_reward_credits', v_idempotent_report.mission_reward_credits,
                'mission_ends_at', to_char(v_idempotent_report.mission_ends_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
                'rating', v_idempotent_report.rating
            );

            -- Ghi vào receipt ledger để các lần retry tiếp theo dùng thẳng receipt
            insert into public.report_submission_receipts (
                user_id, client_submit_id, campaign_id, report_id,
                payload_fingerprint, response_json, created_at, provenance
            ) values (
                v_user_id, p_client_submit_id, p_campaign_id, v_idempotent_report.id,
                v_fingerprint, v_result, now(), 'exact_v1'
            ) on conflict (user_id, client_submit_id) do nothing;

            return v_result;
        end if;
    end if;

    select * into v_camp from public.campaigns where id = p_campaign_id;
    if v_camp.id is null then
        raise exception 'CAMPAIGN_NOT_FOUND';
    end if;

    if v_camp.owner_id = v_user_id then
        raise exception 'CANNOT_TEST_OWN_APP';
    end if;

    if exists (
        select 1 from public.profiles
        where id = v_user_id and is_locked = true
    ) then
        raise exception 'USER_LOCKED';
    end if;

    if v_camp.status <> 'open' then
        raise exception 'CAMPAIGN_NOT_OPEN';
    end if;

    -- Khóa tuần tự theo (user, campaign, ngày)
    perform pg_advisory_xact_lock(
        hashtextextended(format('%s:%s:%s', v_user_id, p_campaign_id, v_today), 0)
    );

    -- Re-check idempotency sau khi đã nắm giữ khóa để loại trừ race condition
    if p_client_submit_id is not null then
        select * into v_receipt
        from public.report_submission_receipts
        where user_id = v_user_id
          and client_submit_id = p_client_submit_id
        limit 1;

        if v_receipt.id is not null then
            if v_receipt.campaign_id <> p_campaign_id then
                raise exception 'CLIENT_SUBMIT_ID_MISMATCH';
            end if;
            if v_receipt.payload_fingerprint = v_fingerprint then
                return v_receipt.response_json;
            end if;

            if v_receipt.provenance = 'legacy_backfill' then
                declare
                    v_resp_mission text := coalesce(v_receipt.response_json ->> 'mission_id', '');
                    v_resp_url text := coalesce(v_receipt.response_json ->> 'screenshot_url', '');
                    v_resp_hash text := coalesce(lower(v_receipt.response_json ->> 'image_hash'), '');
                    v_resp_thumb text := coalesce(v_receipt.response_json ->> 'thumbnail_url', '');
                    v_resp_status text := coalesce(v_receipt.response_json ->> 'status', '');
                    v_eff_mission text := case when p_mission_id is null then v_resp_mission else p_mission_id::text end;
                    v_eff_url text := case when p_screenshot_url is null then v_resp_url else p_screenshot_url end;
                    v_eff_hash text := case when p_image_hash is null then v_resp_hash else lower(p_image_hash) end;
                    v_eff_thumb text := case when p_thumbnail_url is null then v_resp_thumb else p_thumbnail_url end;
                    v_eff_rating int;
                    v_legacy_fp text;
                begin
                    -- Với báo cáo đã duyệt (approved): thao tác bổ sung comment giữ nguyên rating đã khóa
                    if v_resp_status = 'approved' then
                        select rating into v_eff_rating from public.tester_reports where id = v_receipt.report_id;
                        if v_eff_rating is null then
                            v_eff_rating := coalesce((v_receipt.response_json ->> 'rating')::int, 5);
                        end if;
                    else
                        v_eff_rating := coalesce(p_rating, 5);
                    end if;

                    if (p_screenshot_url is null or p_screenshot_url = v_resp_url)
                       and (p_image_hash is null or lower(p_image_hash) = v_resp_hash)
                       and (p_thumbnail_url is null or p_thumbnail_url = v_resp_thumb)
                       and (p_mission_id is null or p_mission_id::text = v_resp_mission)
                       and (v_resp_status = 'approved' or p_rating is null or p_rating = v_eff_rating)
                    then
                        v_legacy_fp := encode(digest(format('%s|%s|%s|%s|%s|%s|%s',
                            p_campaign_id,
                            coalesce(p_content, ''),
                            v_eff_url,
                            v_eff_rating,
                            v_eff_hash,
                            v_eff_thumb,
                            v_eff_mission
                        ), 'sha256'), 'hex');

                        if v_receipt.payload_fingerprint = v_legacy_fp then
                            return v_receipt.response_json;
                        end if;
                    end if;
                end;
            end if;

            raise exception 'CLIENT_SUBMIT_ID_PAYLOAD_MISMATCH';
        end if;
    end if;

    insert into public.campaign_members (campaign_id, user_id)
    values (p_campaign_id, v_user_id)
    on conflict (campaign_id, user_id) do nothing;

    -- Tìm báo cáo hôm nay và khóa dòng để phân loại thao tác
    select * into v_existing_report
    from public.tester_reports
    where campaign_id = p_campaign_id
      and user_id = v_user_id
      and (created_at at time zone 'Asia/Ho_Chi_Minh')::date = v_today
    order by created_at desc
    limit 1
    for update;

    -- N04: Bảo toàn dấu yêu cầu legacy/trước đó của report trước khi client_submit_id bị ghi đè
    if v_existing_report.id is not null
       and v_existing_report.client_submit_id is not null
       and v_existing_report.client_submit_id is distinct from p_client_submit_id then
        insert into public.report_submission_receipts (
            user_id, client_submit_id, campaign_id, report_id,
            payload_fingerprint, response_json, created_at, provenance
        ) values (
            v_user_id,
            v_existing_report.client_submit_id,
            p_campaign_id,
            v_existing_report.id,
            encode(digest(format('%s|%s|%s|%s|%s|%s|%s',
                p_campaign_id,
                coalesce(v_existing_report.content, ''),
                coalesce(v_existing_report.screenshot_url, ''),
                coalesce(v_existing_report.rating, 5),
                coalesce(lower(v_existing_report.image_hash), ''),
                coalesce(v_existing_report.thumbnail_url, ''),
                coalesce(v_existing_report.mission_id::text, '')
            ), 'sha256'), 'hex'),
            jsonb_build_object(
                'success', true,
                'report_id', v_existing_report.id,
                'status', v_existing_report.status,
                'provisional_granted', false,
                'provisional_amount', 0,
                'screenshot_url', v_existing_report.screenshot_url,
                'image_hash', v_existing_report.image_hash,
                'thumbnail_url', v_existing_report.thumbnail_url,
                'submission_context', v_existing_report.submission_context,
                'mission_id', v_existing_report.mission_id,
                'mission_title', v_existing_report.mission_title,
                'mission_reward_credits', v_existing_report.mission_reward_credits,
                'mission_ends_at', to_char(v_existing_report.mission_ends_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
                'rating', v_existing_report.rating
            ),
            v_existing_report.created_at,
            'legacy_backfill'
        ) on conflict (user_id, client_submit_id) do nothing;
    end if;

    -- TH1: BÁO CÁO ĐÃ DUYỆT (approved) -> Chỉ cho phép bổ sung comment, không phát sinh thưởng
    if v_existing_report.id is not null and v_existing_report.status = 'approved' then
        if p_mission_id is not null then
            if v_existing_report.submission_context <> 'mission' then
                raise exception 'REPORT_ALREADY_APPROVED_AS_APP_TEST';
            end if;
            if v_existing_report.mission_id is distinct from p_mission_id then
                raise exception 'REPORT_ALREADY_APPROVED_FOR_ANOTHER_MISSION';
            end if;
            v_submission_context := 'mission';
            v_target_mission_id := v_existing_report.mission_id;
            v_target_mp_id := v_existing_report.mission_participant_id;
            v_target_title := v_existing_report.mission_title;
            v_target_reward := v_existing_report.mission_reward_credits;
            v_target_ends_at := v_existing_report.mission_ends_at;
        else
            v_submission_context := coalesce(v_existing_report.submission_context, 'app_test');
            v_target_mission_id := v_existing_report.mission_id;
            v_target_mp_id := v_existing_report.mission_participant_id;
            v_target_title := v_existing_report.mission_title;
            v_target_reward := v_existing_report.mission_reward_credits;
            v_target_ends_at := v_existing_report.mission_ends_at;
        end if;

        -- Feedback: chỉ cập nhật comment, giữ rating
        insert into public.feedbacks (campaign_id, user_id, rating, comment, updated_at)
        values (
            p_campaign_id, v_user_id, coalesce(v_existing_report.rating, v_rating),
            coalesce(p_content, ''), now()
        )
        on conflict (campaign_id, user_id)
        do update set
            comment = case when coalesce(excluded.comment, '') <> '' then excluded.comment else public.feedbacks.comment end,
            updated_at = now();

        perform set_config('app.submitting_report', 'true', true);

        update public.tester_reports
        set content = case when coalesce(p_content, '') <> '' then p_content else content end,
            client_submit_id = coalesce(p_client_submit_id, client_submit_id)
        where id = v_existing_report.id
          and status = 'approved'
        returning id into v_report_id;

        if v_report_id is null then
            raise exception 'REPORT_ALREADY_REVIEWED';
        end if;
        v_status := 'approved';

        update public.profiles
        set last_active_date = v_today, missed_streak = 0
        where id = v_user_id;

        select
            submission_context, mission_id, mission_title,
            mission_reward_credits, mission_ends_at, screenshot_url,
            image_hash, thumbnail_url
        into
            v_res_context, v_res_mission_id, v_res_title,
            v_res_reward, v_res_ends_at, v_final_url,
            v_final_hash, v_final_thumb
        from public.tester_reports
        where id = v_report_id;

        v_result := jsonb_build_object(
            'success', true,
            'report_id', v_report_id,
            'status', v_status,
            'provisional_granted', false,
            'provisional_amount', 0,
            'screenshot_url', v_final_url,
            'image_hash', v_final_hash,
            'thumbnail_url', v_final_thumb,
            'submission_context', v_res_context,
            'mission_id', v_res_mission_id,
            'mission_title', v_res_title,
            'mission_reward_credits', v_res_reward,
            'mission_ends_at', to_char(v_res_ends_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
            'rating', coalesce(v_existing_report.rating, v_rating)
        );

        if p_client_submit_id is not null then
            insert into public.report_submission_receipts (
                user_id, client_submit_id, campaign_id, report_id,
                payload_fingerprint, response_json, created_at, provenance
            ) values (
                v_user_id, p_client_submit_id, p_campaign_id, v_report_id,
                v_fingerprint, v_result, now(), 'exact_v1'
            ) on conflict (user_id, client_submit_id) do nothing;
        end if;

        return v_result;
    end if;

    -- TH2: ĐÃ CÓ BÁO CÁO PENDING HOẶC REJECTED TRONG NGÀY
    if v_existing_report.id is not null then
        if v_existing_report.submission_context = 'mission' then
            if p_mission_id is not null and v_existing_report.mission_id is distinct from p_mission_id then
                raise exception 'CANNOT_CHANGE_MISSION_IDENTITY';
            end if;
            v_submission_context := 'mission';
            v_target_mission_id := v_existing_report.mission_id;
            v_target_mp_id := v_existing_report.mission_participant_id;
            v_target_title := v_existing_report.mission_title;
            v_target_reward := v_existing_report.mission_reward_credits;
            v_target_ends_at := v_existing_report.mission_ends_at;

            if v_existing_report.status = 'rejected' then
                if v_target_ends_at is not null and v_target_ends_at < now() then
                    raise exception 'MISSION_EXPIRED';
                end if;
            end if;
        else
            if p_mission_id is not null then
                raise exception 'CANNOT_CONVERT_EXISTING_PENDING_REPORT';
            end if;
            v_submission_context := 'app_test';
        end if;

        if p_screenshot_url is not null and btrim(p_screenshot_url) <> '' then
            v_new_screenshot := true;
            v_effective_full := p_screenshot_url;
            if p_image_hash is null or btrim(p_image_hash) = '' then
                raise exception 'IMAGE_HASH_REQUIRED';
            end if;

            if exists (
                select 1 from public.tester_reports
                where lower(image_hash) = lower(p_image_hash)
                  and id <> v_existing_report.id
            ) then
                raise exception 'SAME_SCREENSHOT_REJECTED';
            end if;
        else
            v_effective_full := v_existing_report.screenshot_url;
            if v_existing_report.status = 'rejected' then
                raise exception 'REPORT_RESUBMIT_NEW_PHOTO_REQUIRED';
            end if;
        end if;

        insert into public.feedbacks (campaign_id, user_id, rating, comment, updated_at)
        values (p_campaign_id, v_user_id, v_rating, coalesce(p_content, ''), now())
        on conflict (campaign_id, user_id)
        do update set
            rating = excluded.rating,
            comment = case when coalesce(excluded.comment, '') <> '' then excluded.comment else public.feedbacks.comment end,
            updated_at = now();

        perform set_config('app.submitting_report', 'true', true);

        if v_existing_report.status = 'rejected' then
            v_regrant := coalesce(v_existing_report.provisional_granted_credits, v_provisional_reward);
            if v_existing_report.provisional_clawed > 0 then
                update public.profiles
                set credits = credits + v_regrant,
                    last_active_date = v_today,
                    missed_streak = 0
                where id = v_user_id
                returning credits into v_new_balance;

                insert into public.credit_logs (user_id, amount, action, note, balance)
                values (
                    v_user_id, v_regrant, 'test_provisional',
                    format('Tạm cấp lại %s Credit sau khi nộp lại kết quả test', v_regrant),
                    v_new_balance
                );

                v_provisional_granted := true;
                v_provisional_amount := v_regrant;
            else
                v_provisional_granted := false;
                v_provisional_amount := 0;
            end if;

            update public.tester_reports
            set content = case when coalesce(p_content, '') <> '' then p_content else content end,
                screenshot_url = v_effective_full,
                thumbnail_url = case when v_new_screenshot then p_thumbnail_url else thumbnail_url end,
                image_hash = case when v_new_screenshot then lower(p_image_hash) else image_hash end,
                rating = v_rating,
                status = 'pending',
                rejection_reason = null,
                rejected_at = null,
                provisional_clawed = 0,
                client_submit_id = coalesce(p_client_submit_id, client_submit_id),
                created_at = now(),
                mission_submitted_at = case when v_submission_context = 'mission' then now() else mission_submitted_at end
            where id = v_existing_report.id
            returning id into v_report_id;
        else
            update public.tester_reports
            set content = case when coalesce(p_content, '') <> '' then p_content else content end,
                screenshot_url = v_effective_full,
                thumbnail_url = case when v_new_screenshot then p_thumbnail_url else thumbnail_url end,
                image_hash = case when v_new_screenshot then lower(p_image_hash) else image_hash end,
                rating = v_rating,
                client_submit_id = coalesce(p_client_submit_id, client_submit_id)
            where id = v_existing_report.id
            returning id into v_report_id;
            v_provisional_granted := false;
            v_provisional_amount := 0;
        end if;
        v_status := 'pending';
    else
        -- TH3: BÁO CÁO MỚI TINH TRONG NGÀY
        if p_screenshot_url is null or btrim(p_screenshot_url) = '' then
            raise exception 'SCREENSHOT_URL_REQUIRED';
        end if;
        if p_image_hash is null or btrim(p_image_hash) = '' then
            raise exception 'IMAGE_HASH_REQUIRED';
        end if;

        if exists (
            select 1 from public.tester_reports
            where lower(image_hash) = lower(p_image_hash)
        ) then
            raise exception 'SAME_SCREENSHOT_REJECTED';
        end if;

        if p_mission_id is not null then
            select * into v_mission from public.missions
            where id = p_mission_id and campaign_id = p_campaign_id;

            if v_mission.id is null then
                raise exception 'MISSION_NOT_FOUND';
            end if;
            if v_mission.status <> 'open' then
                raise exception 'MISSION_NOT_OPEN';
            end if;
            if v_mission.ends_at < now() then
                raise exception 'MISSION_EXPIRED';
            end if;

            select * into v_mp from public.mission_participants
            where mission_id = v_mission.id and user_id = v_user_id;

            if v_mp.id is null then
                raise exception 'MISSION_NOT_JOINED';
            end if;

            v_submission_context := 'mission';
            v_target_mission_id := v_mission.id;
            v_target_mp_id := v_mp.id;
            v_target_title := v_mission.title;
            v_target_reward := v_mission.reward_credits;
            v_target_ends_at := v_mission.ends_at;
        else
            select count(*) into v_eligible_count
            from public.mission_participants mp
            join public.missions m on m.id = mp.mission_id
            where mp.user_id = v_user_id
              and m.campaign_id = p_campaign_id
              and m.status = 'open'
              and m.ends_at > now();

            if v_eligible_count = 1 then
                select m.*, mp.id as mp_id into v_check_m
                from public.mission_participants mp
                join public.missions m on m.id = mp.mission_id
                where mp.user_id = v_user_id
                  and m.campaign_id = p_campaign_id
                  and m.status = 'open'
                  and m.ends_at > now()
                limit 1;

                v_submission_context := 'mission';
                v_target_mission_id := v_check_m.id;
                v_target_mp_id := v_check_m.mp_id;
                v_target_title := v_check_m.title;
                v_target_reward := v_check_m.reward_credits;
                v_target_ends_at := v_check_m.ends_at;
            else
                v_submission_context := 'app_test';
            end if;
        end if;

        insert into public.feedbacks (campaign_id, user_id, rating, comment, updated_at)
        values (p_campaign_id, v_user_id, v_rating, coalesce(p_content, ''), now())
        on conflict (campaign_id, user_id)
        do update set
            rating = excluded.rating,
            comment = case when coalesce(excluded.comment, '') <> '' then excluded.comment else public.feedbacks.comment end,
            updated_at = now();

        perform set_config('app.submitting_report', 'true', true);

        select exists (
            select 1 from public.checkins
            where campaign_id = p_campaign_id
              and user_id = v_user_id
              and checkin_date = v_today
        ) into v_already_checked_in;

        if v_already_checked_in then
            insert into public.tester_reports (
                campaign_id, user_id, report_type, content, screenshot_url,
                thumbnail_url, rating, status, bonus_awarded, provisional_clawed,
                provisional_granted_credits, image_hash, client_submit_id, created_at,
                submission_context, mission_id, mission_participant_id,
                mission_title, mission_reward_credits, mission_ends_at, mission_submitted_at
            ) values (
                p_campaign_id, v_user_id, 'feedback', coalesce(p_content, ''),
                p_screenshot_url, p_thumbnail_url, v_rating, 'pending', 0, 0, 0,
                lower(p_image_hash), p_client_submit_id, now(),
                v_submission_context, v_target_mission_id, v_target_mp_id,
                v_target_title, v_target_reward, v_target_ends_at,
                case when v_submission_context = 'mission' then now() else null end
            )
            returning id into v_report_id;

            v_status := 'pending';
            v_provisional_granted := false;
            v_provisional_amount := 0;
        else
            update public.profiles
            set credits = credits + v_provisional_reward,
                last_active_date = v_today,
                missed_streak = 0
            where id = v_user_id
            returning credits into v_new_balance;

            insert into public.credit_logs (user_id, amount, action, note, balance)
            values (
                v_user_id, v_provisional_reward, 'test_provisional',
                format('Tạm nhận %s Credit sau khi nộp kết quả test (chờ chủ app duyệt)', v_provisional_reward),
                v_new_balance
            );

            insert into public.checkins (campaign_id, user_id, checkin_date, note)
            values (p_campaign_id, v_user_id, v_today, 'Đã nộp kết quả test (tạm tính, chờ chủ app duyệt)')
            on conflict (campaign_id, user_id, checkin_date)
            do update set note = 'Đã nộp kết quả test (tạm tính, chờ chủ app duyệt)';

            insert into public.tester_reports (
                campaign_id, user_id, report_type, content, screenshot_url,
                thumbnail_url, rating, status, bonus_awarded, provisional_clawed,
                provisional_granted_credits, image_hash, client_submit_id, created_at,
                submission_context, mission_id, mission_participant_id,
                mission_title, mission_reward_credits, mission_ends_at, mission_submitted_at
            ) values (
                p_campaign_id, v_user_id, 'feedback', coalesce(p_content, ''),
                p_screenshot_url, p_thumbnail_url, v_rating, 'pending', v_provisional_reward, 0, v_provisional_reward,
                lower(p_image_hash), p_client_submit_id, now(),
                v_submission_context, v_target_mission_id, v_target_mp_id,
                v_target_title, v_target_reward, v_target_ends_at,
                case when v_submission_context = 'mission' then now() else null end
            )
            returning id into v_report_id;

            v_status := 'pending';
            v_provisional_granted := true;
            v_provisional_amount := v_provisional_reward;
        end if;
    end if;

    update public.profiles
    set last_active_date = v_today, missed_streak = 0
    where id = v_user_id;

    select
        submission_context, mission_id, mission_title,
        mission_reward_credits, mission_ends_at, screenshot_url,
        image_hash, thumbnail_url
    into
        v_res_context, v_res_mission_id, v_res_title,
        v_res_reward, v_res_ends_at, v_final_url,
        v_final_hash, v_final_thumb
    from public.tester_reports
    where id = v_report_id;

    v_result := jsonb_build_object(
        'success', true,
        'report_id', v_report_id,
        'status', v_status,
        'provisional_granted', v_provisional_granted,
        'provisional_amount', v_provisional_amount,
        'screenshot_url', v_final_url,
        'image_hash', v_final_hash,
        'thumbnail_url', v_final_thumb,
        'submission_context', v_res_context,
        'mission_id', v_res_mission_id,
        'mission_title', v_res_title,
        'mission_reward_credits', v_res_reward,
        'mission_ends_at', to_char(v_res_ends_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
        'rating', case
            when v_existing_report.id is not null and v_existing_report.status = 'approved' then coalesce(v_existing_report.rating, v_rating)
            else v_rating
        end
    );

    if p_client_submit_id is not null then
        insert into public.report_submission_receipts (
            user_id, client_submit_id, campaign_id, report_id,
            payload_fingerprint, response_json, created_at, provenance
        ) values (
            v_user_id, p_client_submit_id, p_campaign_id, v_report_id,
            v_fingerprint, v_result, now(), 'exact_v1'
        ) on conflict (user_id, client_submit_id) do nothing;
    end if;

    return v_result;
end;
$function$;

CREATE OR REPLACE FUNCTION public.sync_campaign_lifecycle()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_completed int := 0;
    v_paused int := 0;
    v_slot_paused int := 0;
begin
    v_completed := public.complete_expired_campaigns();
    v_paused := public.pause_inactive_owner_campaigns();
    -- Trước đây hàm này bị mồ côi: app có slot hết hạn không bao giờ tự tạm dừng.
    v_slot_paused := public.pause_expired_slot_campaigns();
    return jsonb_build_object(
        'completed', v_completed,
        'paused', v_paused,
        'slot_paused', v_slot_paused
    );
end;
$function$;

CREATE OR REPLACE FUNCTION public.sync_expired_missions()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_updated int := 0;
begin
    update public.missions
    set status = 'expired'
    where status in ('open', 'full', 'paused_by_creator')
      and ends_at <= now();

    get diagnostics v_updated = row_count;
    return v_updated;
end;
$function$;

CREATE OR REPLACE FUNCTION public.trg_campaign_status_lifecycle()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
    if new.status in ('production', 'completed') then
        if new.completed_at is null then
            new.completed_at := now();
        end if;
        new.admin_resumed := false;
        -- Giữ admin_note khi app hết hạn: guard bên dưới dựa vào việc note
        -- không đổi để phân biệt hệ thống hoàn thành app với chủ app lách luật.
    elsif new.status = 'paused' then
        new.admin_resumed := false;
    elsif new.status = 'open' then
        new.completed_at := null;
        new.paused_reason := null;
        new.admin_note := null;
    end if;
    return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.trg_campaigns_guard_admin_actions()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_uid uuid := auth.uid();
    v_role text;
begin
    -- SQL Editor / service_role không có auth.uid -> cho phép.
    if v_uid is null then
        return new;
    end if;

    -- Chặn client tự tạo campaign với cờ/lý do của Admin.
    if tg_op = 'INSERT' then
        if new.admin_resumed
           or new.admin_note is not null
           or new.paused_reason = 'admin_manual' then
            raise exception 'PERMISSION_DENIED';
        end if;
        return new;
    end if;

    -- Không ai (kể cả Admin qua client) được đổi chủ sở hữu campaign.
    -- SQL Editor / service_role vẫn có thể sửa trực tiếp khi thật sự cần.
    if new.owner_id is distinct from old.owner_id then
        raise exception 'OWNER_ID_IMMUTABLE';
    end if;

    -- Chỉ Admin được bật cờ bỏ qua auto-pause; chủ app không được tự bật.
    if new.admin_resumed and not coalesce(old.admin_resumed, false) then
        select lower(p.role) into v_role
        from public.profiles p
        where p.id = v_uid;

        if coalesce(v_role, '') <> 'admin' then
            raise exception 'PERMISSION_DENIED';
        end if;
    end if;

    -- App đang bị Admin tạm dừng: chủ app không được mở lại, không được xóa
    -- paused_reason/admin_note để lách luật. Hệ thống vẫn được chuyển app sang
    -- 'completed' khi hết 30 ngày vì update đó không đổi paused_reason/admin_note.
    if old.paused_reason = 'admin_manual' then
        if new.status = 'open'
           or new.paused_reason is distinct from 'admin_manual'
           or new.admin_note is distinct from old.admin_note
        then
            select lower(p.role) into v_role
            from public.profiles p
            where p.id = v_uid;

            if coalesce(v_role, '') <> 'admin' then
                raise exception 'PAUSED_BY_ADMIN';
            end if;
        end if;
    end if;

    return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.trg_fn_campaigns_app_update_settle()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    if TG_OP = 'DELETE' then
        perform public._settle_campaign_app_update(OLD.id);
        return OLD;
    elsif TG_OP = 'UPDATE' then
        -- R02: Xử lý mọi chuyển trạng thái hợp lệ sang completed/production/closed (bao gồm cả từ paused)
        if (OLD.status is distinct from NEW.status) and NEW.status in ('completed', 'production', 'closed') then
            perform public._settle_campaign_app_update(NEW.id);
        end if;
        return NEW;
    end if;
    return null;
end;
$function$;

CREATE OR REPLACE FUNCTION public.trg_fn_protect_campaign_push_metadata()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
    if (tg_op = 'INSERT' and (new.push_business_date is not null or new.push_expires_at is not null or new.push_order is not null))
       or (tg_op = 'UPDATE' and (new.push_business_date is distinct from old.push_business_date
            or new.push_expires_at is distinct from old.push_expires_at
            or new.push_order is distinct from old.push_order)) then
        -- Client trực tiếp mang role authenticated/anon/public tuyệt đối không được ghi đè metadata
        -- Sử dụng current_user (quyền thực thi hiệu lực trong ngữ cảnh invoker) để phân biệt
        -- lời gọi trực tiếp từ client với lời gọi bên trong RPC SECURITY DEFINER (đang chạy với role owner tin cậy).
        if current_user in ('authenticated', 'anon', 'public') or session_user in ('anon') then
            raise exception 'PUSH_METADATA_READ_ONLY: Client khong duoc phep thay doi metadata day app truc tiep';
        end if;

        -- Metadata chỉ được cập nhật khi có cờ transaction-local do RPC push_campaign bật
        if current_setting('app.allow_push_metadata_write', true) is distinct from 'true' then
            raise exception 'PUSH_METADATA_READ_ONLY: Metadata day app chi duoc cap nhat qua RPC push_campaign';
        end if;
    end if;
    return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.trg_notify_campaign_member_joined()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_owner_id uuid;
    v_camp_name text;
begin
    select owner_id, app_name into v_owner_id, v_camp_name
    from public.campaigns
    where id = new.campaign_id;

    if v_owner_id is not null and v_owner_id <> new.user_id then
        insert into public.notifications (user_id, title, message, type, data)
        values (
            v_owner_id,
            'Tester mới tham gia 🚀',
            format('Một người dùng vừa tham gia thử nghiệm ứng dụng "%s" của bạn.', coalesce(v_camp_name, '')),
            'campaign',
            jsonb_build_object('campaign_id', new.campaign_id, 'tester_id', new.user_id)
        );
    end if;
    return new;
exception when others then
    return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.trg_notify_credit_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_title text;
begin
    if new.action = 'test_approved' then
        return new;
    end if;

    if new.amount > 0 then
        v_title := format('Biến động số dư: +%s Credit 🪙', new.amount);
    else
        v_title := format('Biến động số dư: %s Credit 🪙', new.amount);
    end if;

    insert into public.notifications (user_id, title, message, type, data)
    values (
        new.user_id,
        v_title,
        coalesce(new.note, format('Số dư hiện tại: %s Credit', new.balance)),
        'credit',
        jsonb_build_object(
            'amount', new.amount,
            'balance', new.balance,
            'action', new.action,
            'event_code', 'credit_change'
        )
    );

    return new;
exception when others then
    return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.trg_notify_profile_lock_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    if old.is_locked = false and new.is_locked = true then
        insert into public.notifications (user_id, title, message, type, data)
        values (
            new.id,
            'Tài khoản đã bị tạm khóa 🔒',
            'Tài khoản của bạn đã bị tạm khóa do vi phạm quy tắc kiểm thử hoặc quyết định từ Quản trị viên. Bạn có thể tự mở khóa bằng 100 Credit hoặc liên hệ Admin.',
            'account',
            jsonb_build_object('is_locked', true)
        );
    elsif old.is_locked = true and new.is_locked = false then
        insert into public.notifications (user_id, title, message, type, data)
        values (
            new.id,
            'Tài khoản đã được mở khóa 🔓',
            'Chúc mừng! Tài khoản của bạn đã được mở khóa thành công. Bạn có thể tiếp tục tham gia kiểm thử và đăng chiến dịch.',
            'account',
            jsonb_build_object('is_locked', false)
        );
    end if;
    return new;
exception when others then
    return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.trg_notify_tester_report()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_owner_id uuid;
    v_camp_name text;
    v_extra int;
    v_clawed int;
begin
    if coalesce(current_setting('app.suppress_report_notify', true), '') = '1' then
        return new;
    end if;

    -- 1. Báo cáo mới
    if tg_op = 'INSERT' and new.status = 'pending' then
        select owner_id, app_name into v_owner_id, v_camp_name
        from public.campaigns
        where id = new.campaign_id;

        if v_owner_id is not null and v_owner_id <> new.user_id then
            insert into public.notifications (user_id, title, message, type, data)
            values (
                v_owner_id,
                'Báo cáo kiểm thử mới 📋',
                format('Ứng dụng "%s" vừa nhận được 1 báo cáo kiểm thử mới. Bạn có 8 giờ để kiểm tra và duyệt (+2 Credit thưởng cho tester và +2 Credit cho bạn nếu duyệt).', coalesce(v_camp_name, 'của bạn')),
                'report',
                jsonb_build_object(
                    'campaign_id', new.campaign_id,
                    'report_id', new.id,
                    'status', 'pending',
                    'event_code', 'new_report',
                    'app_name', coalesce(v_camp_name, 'của bạn')
                )
            );
        end if;

    -- 2. Tester nộp lại báo cáo sau khi bị từ chối
    elsif tg_op = 'UPDATE' and old.status = 'rejected' and new.status = 'pending' then
        select owner_id, app_name into v_owner_id, v_camp_name
        from public.campaigns
        where id = new.campaign_id;

        if v_owner_id is not null and v_owner_id <> new.user_id then
            insert into public.notifications (user_id, title, message, type, data)
            values (
                v_owner_id,
                'Báo cáo nộp lại 🔄',
                format('Tester đã nộp lại báo cáo cho ứng dụng "%s". Vui lòng kiểm tra lại.', coalesce(v_camp_name, 'của bạn')),
                'report',
                jsonb_build_object(
                    'campaign_id', new.campaign_id,
                    'report_id', new.id,
                    'status', 'pending',
                    'event_code', 'resubmit_report',
                    'app_name', coalesce(v_camp_name, 'của bạn')
                )
            );
        end if;

    -- 3. Tester sửa báo cáo đang chờ duyệt (đổi ảnh/nội dung) -> báo chủ app
    elsif tg_op = 'UPDATE' and old.status = 'pending' and new.status = 'pending'
          and (old.screenshot_url is distinct from new.screenshot_url
               or old.image_hash is distinct from new.image_hash
               or old.content is distinct from new.content) then
        select owner_id, app_name into v_owner_id, v_camp_name
        from public.campaigns
        where id = new.campaign_id;

        if v_owner_id is not null and v_owner_id <> new.user_id then
            insert into public.notifications (user_id, title, message, type, data)
            values (
                v_owner_id,
                'Tester cập nhật báo cáo ✏️',
                format('Tester vừa cập nhật báo cáo kiểm thử cho ứng dụng "%s". Vui lòng xem lại ảnh/nội dung mới trước khi duyệt.', coalesce(v_camp_name, 'của bạn')),
                'report',
                jsonb_build_object(
                    'campaign_id', new.campaign_id,
                    'report_id', new.id,
                    'status', 'pending',
                    'is_edited', true,
                    'event_code', 'report_edited',
                    'app_name', coalesce(v_camp_name, 'của bạn')
                )
            );
        end if;

    -- 4. Chủ app/Admin/Moderator duyệt hoặc từ chối
    elsif tg_op = 'UPDATE' and old.status = 'pending' and new.status <> 'pending' then
        select app_name into v_camp_name
        from public.campaigns
        where id = new.campaign_id;

        if new.status = 'approved' then
            v_extra := greatest(0, coalesce(new.bonus_awarded, 0) - coalesce(old.bonus_awarded, 0));

            insert into public.notifications (user_id, title, message, type, data)
            values (
                new.user_id,
                'Báo cáo kiểm thử được phê duyệt! 🎉',
                format('Báo cáo của bạn cho ứng dụng "%s" đã được duyệt thành công! Bạn nhận thêm %s Credit cho lượt test này. Cảm ơn bạn!',
                    coalesce(v_camp_name, 'ứng dụng'),
                    v_extra
                ),
                'report',
                jsonb_build_object(
                    'campaign_id', new.campaign_id,
                    'report_id', new.id,
                    'status', 'approved',
                    'event_code', 'report_approved',
                    'app_name', coalesce(v_camp_name, 'ứng dụng'),
                    'bonus', v_extra
                )
            );
        elsif new.status = 'rejected' then
            v_clawed := greatest(0, coalesce(new.provisional_clawed, 0));

            insert into public.notifications (user_id, title, message, type, data)
            values (
                new.user_id,
                'Báo cáo kiểm thử bị từ chối ⚠️',
                case
                    when v_clawed > 0 and new.rejection_reason is not null and trim(new.rejection_reason) <> '' then
                        format('Báo cáo của bạn cho ứng dụng "%s" đã bị từ chối. Lý do: "%s". %s Credit tạm nhận đã bị thu hồi. Vui lòng kiểm tra và chụp ảnh khác để nộp lại.', coalesce(v_camp_name, 'ứng dụng'), new.rejection_reason, v_clawed)
                    when v_clawed > 0 then
                        format('Báo cáo của bạn cho ứng dụng "%s" đã bị từ chối. %s Credit tạm nhận đã bị thu hồi. Hãy đảm bảo chụp đúng giao diện ứng dụng và kiểm thử nghiêm túc để nộp lại.', coalesce(v_camp_name, 'ứng dụng'), v_clawed)
                    when new.rejection_reason is not null and trim(new.rejection_reason) <> '' then
                        format('Báo cáo của bạn cho ứng dụng "%s" đã bị từ chối. Lý do: "%s". Vui lòng kiểm tra và chụp ảnh khác để nộp lại.', coalesce(v_camp_name, 'ứng dụng'), new.rejection_reason)
                    else
                        format('Báo cáo của bạn cho ứng dụng "%s" đã bị từ chối. Hãy đảm bảo chụp đúng giao diện ứng dụng và kiểm thử nghiêm túc để nộp lại.', coalesce(v_camp_name, 'ứng dụng'))
                end,
                'report',
                jsonb_build_object(
                    'campaign_id', new.campaign_id,
                    'report_id', new.id,
                    'status', 'rejected',
                    'reason', new.rejection_reason,
                    'reason_code', new.reason_code,
                    'event_code', 'report_rejected',
                    'app_name', coalesce(v_camp_name, 'ứng dụng'),
                    'credits_clawed', v_clawed
                )
            );
        end if;
    end if;

    return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.trg_notify_user_warning()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    insert into public.notifications (user_id, title, message, type, data)
    values (
        new.user_id,
        'Cảnh báo từ hệ thống ⚠️',
        new.message,
        'warning',
        jsonb_build_object('warning_id', new.id, 'warning_type', new.warning_type)
    );
    return new;
exception when others then
    return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.trg_reports_require_open_campaign()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_status text;
begin
    select status into v_status from public.campaigns where id = new.campaign_id;
    if v_status is not null and v_status <> 'open' then
        raise exception 'CAMPAIGN_NOT_OPEN';
    end if;
    return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.trg_reset_tester_report_rejection()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    if tg_op = 'UPDATE' and old.status = 'rejected' and new.status = 'pending' then
        new.reason_code := null;
        new.rejection_reason := null;
    end if;
    return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.trig_protect_tester_reports_mission_metadata()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
    if current_setting('app.submitting_report', true) = 'true' then
        return new;
    end if;

    if current_user not in ('anon', 'authenticated')
       and coalesce(current_setting('request.jwt.claim.role', true), '') not in ('anon', 'authenticated') then
        return new;
    end if;

    if (TG_OP = 'INSERT') then
        if new.submission_context is not null
           or new.mission_id is not null
           or new.mission_participant_id is not null
           or new.mission_title is not null
           or new.mission_reward_credits is not null
           or new.mission_ends_at is not null
           or new.mission_submitted_at is not null then
            raise exception 'CANNOT_SET_MISSION_METADATA_DIRECTLY';
        end if;
    elsif (TG_OP = 'UPDATE') then
        if (new.submission_context is distinct from old.submission_context)
           or (new.mission_id is distinct from old.mission_id)
           or (new.mission_participant_id is distinct from old.mission_participant_id)
           or (new.mission_title is distinct from old.mission_title)
           or (new.mission_reward_credits is distinct from old.mission_reward_credits)
           or (new.mission_ends_at is distinct from old.mission_ends_at)
           or (new.mission_submitted_at is distinct from old.mission_submitted_at) then
            raise exception 'CANNOT_MODIFY_MISSION_METADATA_DIRECTLY';
        end if;
    end if;

    return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.unlock_or_renew_slot(p_slot_number integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_user_id uuid := auth.uid();
    v_cost int;
    v_balance int;
    v_current_expires timestamptz;
    v_new_expires timestamptz;
begin
    if v_user_id is null then
        raise exception 'NOT_AUTHENTICATED';
    end if;

    -- Slot 1 luôn miễn phí và vĩnh viễn
    if p_slot_number < 2 or p_slot_number > 6 then
        raise exception 'INVALID_SLOT_NUMBER';
    end if;

    if p_slot_number = 2 then
        v_cost := 50;
    elsif p_slot_number = 3 then
        v_cost := 100;
    else
        v_cost := 200;
    end if;

    select credits into v_balance
    from public.profiles
    where id = v_user_id
    for update;

    if v_balance is null or v_balance < v_cost then
        raise exception 'INSUFFICIENT_CREDITS';
    end if;

    -- Slot N (N > 2) chỉ mở được khi Slot N - 1 đang còn hoạt động
    if p_slot_number > 2 then
        if not exists (
            select 1 from public.user_slots
            where user_id = v_user_id
              and slot_number = p_slot_number - 1
              and expires_at > now()
        ) then
            raise exception 'PREVIOUS_SLOT_NOT_ACTIVE';
        end if;
    end if;

    -- Tính hạn mới (+30 ngày); cộng dồn nếu slot còn hoạt động
    select expires_at into v_current_expires
    from public.user_slots
    where user_id = v_user_id and slot_number = p_slot_number;

    if v_current_expires is not null and v_current_expires > now() then
        v_new_expires := v_current_expires + interval '30 days';
    else
        v_new_expires := now() + interval '30 days';
    end if;

    insert into public.user_slots (user_id, slot_number, unlocked_at, expires_at)
    values (v_user_id, p_slot_number, now(), v_new_expires)
    on conflict (user_id, slot_number)
    do update set
        unlocked_at = now(),
        expires_at = v_new_expires;

    update public.profiles
    set credits = credits - v_cost
    where id = v_user_id
    returning credits into v_balance;

    insert into public.credit_logs (user_id, amount, action, note, balance)
    values (
        v_user_id,
        -v_cost,
        'unlock_slot',
        format('Mở khóa / Gia hạn Slot %s (thời hạn 30 ngày)', p_slot_number),
        v_balance
    );

    return jsonb_build_object(
        'success', true,
        'slot_number', p_slot_number,
        'cost', v_cost,
        'balance', v_balance,
        'expires_at', to_char(v_new_expires at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"')
    );
end;
$function$;

CREATE OR REPLACE FUNCTION public.verify_media_access_grant(p_report_id uuid, p_grant_token text, p_variant text DEFAULT 'full'::text, p_expires_at_epoch bigint DEFAULT NULL::bigint)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
    v_consumer_id uuid := auth.uid();
    v_report record;
    v_camp record;
    v_role text := null;
    v_now_epoch bigint := extract(epoch from now())::bigint;
    v_expected_sig text;
begin
    -- 1. Identity binding: Bắt buộc phải có phiên người dùng thực tế
    if v_consumer_id is null or p_grant_token is null or p_expires_at_epoch is null then
        return false;
    end if;

    -- 2. Kiểm tra hết hạn & tuổi thọ tối đa của grant (tối đa 30 phút = 1800s)
    if v_now_epoch > p_expires_at_epoch or (p_expires_at_epoch - v_now_epoch) > 1800 then
        return false;
    end if;

    -- 3. Kiểm tra báo cáo tồn tại, không bị xóa và chưa hết hạn lưu trữ (SLA 30 ngày)
    select id, campaign_id, user_id, media_expired, created_at
    into v_report
    from public.tester_reports
    where id = p_report_id;

    if v_report.id is null or v_report.media_expired = true or v_report.created_at < (now() - interval '30 days') then
        return false;
    end if;

    -- 4. Xác định quyền hiện tại của consumer đối với báo cáo
    if v_report.user_id = v_consumer_id then
        v_role := 'author';
    else
        select owner_id into v_camp from public.campaigns where id = v_report.campaign_id;
        if v_camp.owner_id = v_consumer_id then
            v_role := 'owner';
        elsif exists (
            select 1 from public.profiles
            where id = v_consumer_id and lower(coalesce(role, '')) in ('admin', 'moderator')
        ) then
            v_role := 'admin';
        else
            return false;
        end if;
    end if;

    -- 5. Tính lại chữ ký HMAC gắn chặt với định danh consumer, role, report, variant, expires
    v_expected_sig := encode(
        hmac(
            format('%s:%s:%s:%s:%s', p_report_id, v_consumer_id, v_role, coalesce(p_variant, 'full'), p_expires_at_epoch),
            public.get_media_gateway_secret(),
            'sha256'
        ),
        'hex'
    );

    return (v_expected_sig = p_grant_token);
exception
    when others then
        return false;
end;
$function$;

CREATE OR REPLACE FUNCTION public.verify_media_access_grant_internal(p_report_id uuid, p_user_id uuid, p_grant_token text, p_variant text DEFAULT 'full'::text, p_expires_at_epoch bigint DEFAULT NULL::bigint)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
    v_report record;
    v_camp record;
    v_role text := null;
    v_now_epoch bigint := extract(epoch from now())::bigint;
    v_expected_sig text;
begin
    if p_user_id is null or p_grant_token is null or p_expires_at_epoch is null then
        return false;
    end if;

    if v_now_epoch > p_expires_at_epoch or (p_expires_at_epoch - v_now_epoch) > 1800 then
        return false;
    end if;

    select id, campaign_id, user_id, media_expired, created_at
    into v_report
    from public.tester_reports
    where id = p_report_id;

    if v_report.id is null or v_report.media_expired = true or v_report.created_at < (now() - interval '30 days') then
        return false;
    end if;

    if v_report.user_id = p_user_id then
        v_role := 'author';
    else
        select owner_id into v_camp from public.campaigns where id = v_report.campaign_id;
        if v_camp.owner_id = p_user_id then
            v_role := 'owner';
        elsif exists (
            select 1 from public.profiles
            where id = p_user_id and lower(coalesce(role, '')) in ('admin', 'moderator')
        ) then
            v_role := 'admin';
        else
            return false;
        end if;
    end if;

    v_expected_sig := encode(
        hmac(
            format('%s:%s:%s:%s:%s', p_report_id, p_user_id, v_role, coalesce(p_variant, 'full'), p_expires_at_epoch),
            public.get_media_gateway_secret(),
            'sha256'
        ),
        'hex'
    );

    return (v_expected_sig = p_grant_token);
exception
    when others then
        return false;
end;
$function$;

-- Ràng buộc: giữ nguyên khi đã có, dừng nếu phát hiện định nghĩa khác.
do $constraint$
declare v_definition text;
begin
    select pg_get_constraintdef(oid,true) into v_definition from pg_constraint
    where conrelid='public."app_configs"'::regclass and conname='app_configs_pkey';
    if v_definition is null then
        alter table public."app_configs" add constraint "app_configs_pkey" PRIMARY KEY (id);
    elsif v_definition <> 'PRIMARY KEY (id)' then
        raise exception 'BASELINE_062_CONSTRAINT_DRIFT: %.%', 'app_configs', 'app_configs_pkey';
    end if;
end;
$constraint$;

