-- Indexes: không xây lại index đã tồn tại.
CREATE INDEX IF NOT EXISTS campaign_members_user_idx ON public.campaign_members USING btree (user_id);
CREATE INDEX IF NOT EXISTS campaigns_owner_idx ON public.campaigns USING btree (owner_id);
CREATE INDEX IF NOT EXISTS campaigns_status_idx ON public.campaigns USING btree (status);
CREATE INDEX IF NOT EXISTS checkins_campaign_idx ON public.checkins USING btree (campaign_id);
CREATE INDEX IF NOT EXISTS credit_logs_created_idx ON public.credit_logs USING btree (created_at DESC);
CREATE INDEX IF NOT EXISTS credit_logs_user_idx ON public.credit_logs USING btree (user_id);
CREATE INDEX IF NOT EXISTS feedbacks_campaign_idx ON public.feedbacks USING btree (campaign_id);
CREATE INDEX IF NOT EXISTS idx_app_update_claims_tester ON public.app_update_claims USING btree (tester_id);
CREATE UNIQUE INDEX IF NOT EXISTS idx_app_update_releases_active ON public.app_update_releases USING btree (owner_id, package_name) WHERE (status = 'active'::text);
CREATE INDEX IF NOT EXISTS idx_app_update_releases_campaign ON public.app_update_releases USING btree (campaign_id);
CREATE UNIQUE INDEX IF NOT EXISTS idx_app_update_releases_code ON public.app_update_releases USING btree (owner_id, package_name, target_version_code);
CREATE INDEX IF NOT EXISTS idx_app_update_releases_owner ON public.app_update_releases USING btree (owner_id);
CREATE INDEX IF NOT EXISTS idx_app_update_releases_pkg ON public.app_update_releases USING btree (package_name);
CREATE INDEX IF NOT EXISTS idx_campaign_archive_archived_at ON public.campaign_archive USING btree (archived_at DESC);
CREATE INDEX IF NOT EXISTS idx_campaign_archive_owner ON public.campaign_archive USING btree (owner_id);
CREATE INDEX IF NOT EXISTS idx_campaign_push_receipts_campaign ON public.campaign_push_receipts USING btree (campaign_id);
CREATE INDEX IF NOT EXISTS idx_campaign_push_receipts_date_order ON public.campaign_push_receipts USING btree (business_date, push_order DESC);
CREATE INDEX IF NOT EXISTS idx_campaign_push_receipts_target_campaign ON public.campaign_push_receipts USING btree (target_campaign_id);
CREATE INDEX IF NOT EXISTS idx_campaign_push_receipts_user ON public.campaign_push_receipts USING btree (user_id);
CREATE INDEX IF NOT EXISTS idx_campaigns_admin_resumed ON public.campaigns USING btree (admin_resumed) WHERE (admin_resumed = true);
CREATE INDEX IF NOT EXISTS idx_campaigns_completed_at ON public.campaigns USING btree (completed_at DESC);
CREATE INDEX IF NOT EXISTS idx_campaigns_owner_slot ON public.campaigns USING btree (owner_id, slot_number);
CREATE INDEX IF NOT EXISTS idx_campaigns_purge_due ON public.campaigns USING btree (COALESCE(completed_at, created_at)) WHERE (status = ANY (ARRAY['completed'::text, 'production'::text]));
CREATE INDEX IF NOT EXISTS idx_campaigns_push_order ON public.campaigns USING btree (push_business_date, push_order DESC) WHERE (push_order IS NOT NULL);
CREATE INDEX IF NOT EXISTS idx_campaigns_status_created ON public.campaigns USING btree (status, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_checkins_campaign_date ON public.checkins USING btree (campaign_id, checkin_date);
CREATE INDEX IF NOT EXISTS idx_cleanup_runs_job_started ON public.cleanup_runs USING btree (job_name, started_at DESC);
CREATE INDEX IF NOT EXISTS idx_contact_reports_status_created ON public.contact_reports USING btree (status, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_contact_reports_user_created ON public.contact_reports USING btree (user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_credit_logs_user_created ON public.credit_logs USING btree (user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_home_stats_policies_effective ON public.home_stats_policies USING btree (effective_from DESC);
CREATE INDEX IF NOT EXISTS idx_mission_participants_user ON public.mission_participants USING btree (user_id);
CREATE INDEX IF NOT EXISTS idx_mission_settlement_jobs_retry ON public.mission_settlement_jobs USING btree (next_attempt_at, created_at) WHERE (status = ANY (ARRAY['pending'::text, 'failed'::text]));
CREATE INDEX IF NOT EXISTS idx_mission_settlement_jobs_status ON public.mission_settlement_jobs USING btree (status) WHERE (status = ANY (ARRAY['pending'::text, 'failed'::text]));
CREATE INDEX IF NOT EXISTS idx_missions_campaign ON public.missions USING btree (campaign_id);
CREATE UNIQUE INDEX IF NOT EXISTS idx_missions_campaign_active_unique ON public.missions USING btree (campaign_id) WHERE (status = ANY (ARRAY['open'::text, 'full'::text, 'paused_by_creator'::text]));
CREATE INDEX IF NOT EXISTS idx_missions_creator ON public.missions USING btree (creator_id);
CREATE INDEX IF NOT EXISTS idx_missions_status_created ON public.missions USING btree (status, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_notifications_user_created ON public.notifications USING btree (user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_notifications_user_read ON public.notifications USING btree (user_id, is_read);
CREATE INDEX IF NOT EXISTS idx_profiles_is_locked ON public.profiles USING btree (is_locked);
CREATE INDEX IF NOT EXISTS idx_profiles_role ON public.profiles USING btree (role);
CREATE INDEX IF NOT EXISTS idx_report_submission_receipts_lookup ON public.report_submission_receipts USING btree (user_id, client_submit_id);
CREATE INDEX IF NOT EXISTS idx_review_events_owner_day ON public.report_review_events USING btree (owner_id, created_at DESC);
