CREATE INDEX IF NOT EXISTS idx_tester_reports_mission_id ON public.tester_reports USING btree (mission_id) WHERE (mission_id IS NOT NULL);
CREATE INDEX IF NOT EXISTS idx_tester_reports_pending_created ON public.tester_reports USING btree (created_at) WHERE (status = 'pending'::text);
CREATE INDEX IF NOT EXISTS idx_tester_reports_reason_code ON public.tester_reports USING btree (reason_code) WHERE (reason_code IS NOT NULL);
CREATE INDEX IF NOT EXISTS idx_tester_reports_status ON public.tester_reports USING btree (status);
CREATE INDEX IF NOT EXISTS idx_tester_reports_submission_context ON public.tester_reports USING btree (submission_context);
CREATE UNIQUE INDEX IF NOT EXISTS idx_tester_reports_user_client_submit ON public.tester_reports USING btree (user_id, client_submit_id) WHERE (client_submit_id IS NOT NULL);
CREATE INDEX IF NOT EXISTS idx_topup_orders_purchase_token ON public.topup_orders USING btree (purchase_token);
CREATE INDEX IF NOT EXISTS idx_topup_orders_status ON public.topup_orders USING btree (payment_status);
CREATE INDEX IF NOT EXISTS idx_topup_orders_user_created ON public.topup_orders USING btree (user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_user_daily_tasks_date ON public.user_daily_tasks USING btree (task_date);
