CREATE INDEX IF NOT EXISTS idx_user_slots_user ON public.user_slots USING btree (user_id);
CREATE INDEX IF NOT EXISTS idx_user_warnings_user_created ON public.user_warnings USING btree (user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_user_warnings_user_date ON public.user_warnings USING btree (user_id, warning_date);
CREATE INDEX IF NOT EXISTS idx_user_warnings_user_unread ON public.user_warnings USING btree (user_id, acknowledged, created_at DESC);
CREATE UNIQUE INDEX IF NOT EXISTS uq_topup_orders_purchase_token_completed ON public.topup_orders USING btree (purchase_token) WHERE ((payment_status = 'completed'::text) AND (purchase_token IS NOT NULL));

