        insert into public."topup_packages" ("id","title","credits","bonus_credits","price_usd","price_vnd","badge_text","is_popular","is_active","sort_order","created_at") values ('credit_pack_starter_20'::text,'Gói Khởi Đầu'::text,20,0,0.99,25000,null,false,true,1,clock_timestamp());
