        insert into public."daily_task_policies" ("effective_from","tests_per_active_app","operator_note","created_at","updated_at") values ('-infinity'::date,3,'Migration 042: preserve existing 3:1 policy'::text,clock_timestamp(),clock_timestamp());
        insert into public."daily_task_policy_changes" ("policy_id","operation","old_row","new_row","operator_note","session_role","invoked_role","changed_at","actor_id") values ((select id from public.daily_task_policies where effective_from=date '-infinity'),'INSERT'::text,null,(select to_jsonb(p) from public.daily_task_policies p where effective_from=date '-infinity'),'Migration 042: preserve existing 3:1 policy'::text,'postgres'::text,null,clock_timestamp(),null);
        insert into public."home_stats_policies" ("effective_from","cycle_days","created_at","created_by","updated_at","updated_by") values ('2020-01-01'::date,1,clock_timestamp(),null,clock_timestamp(),null);
        insert into public."daily_task_carryover_policies" ("effective_from","is_enabled","operator_note","created_at") values ('2026-10-30'::date,true,'Migration 053: baseline daily task carryover policy'::text,clock_timestamp());
    end if;
