-- Policies: chỉ thay các policy do dự án quản lý.
drop policy if exists "Allow read app_configs to all" on public."app_configs";
create policy "Allow read app_configs to all" on public."app_configs" as PERMISSIVE for SELECT to PUBLIC using (true);

drop policy if exists "Allow update app_configs to admin" on public."app_configs";
create policy "Allow update app_configs to admin" on public."app_configs" as PERMISSIVE for UPDATE to "authenticated" using ((EXISTS ( SELECT 1
   FROM profiles
  WHERE ((profiles.id = auth.uid()) AND (profiles.role = 'admin'::text)))));

drop policy if exists "app_update_claims_select_policy" on public."app_update_claims";
create policy "app_update_claims_select_policy" on public."app_update_claims" as PERMISSIVE for SELECT to "authenticated" using (((tester_id = auth.uid()) OR (EXISTS ( SELECT 1
   FROM app_update_releases r
  WHERE ((r.id = app_update_claims.release_id) AND (r.owner_id = auth.uid())))) OR (EXISTS ( SELECT 1
   FROM profiles p
  WHERE ((p.id = auth.uid()) AND (lower(p.role) = ANY (ARRAY['admin'::text, 'moderator'::text])))))));

drop policy if exists "app_update_controls_select_policy" on public."app_update_controls";
create policy "app_update_controls_select_policy" on public."app_update_controls" as PERMISSIVE for SELECT to "authenticated" using (((owner_id = auth.uid()) OR (EXISTS ( SELECT 1
   FROM profiles p
  WHERE ((p.id = auth.uid()) AND (lower(p.role) = ANY (ARRAY['admin'::text, 'moderator'::text])))))));

drop policy if exists "app_update_financial_events_select_policy" on public."app_update_financial_events";
create policy "app_update_financial_events_select_policy" on public."app_update_financial_events" as PERMISSIVE for SELECT to "authenticated" using (((owner_id = auth.uid()) OR (tester_id = auth.uid()) OR (EXISTS ( SELECT 1
   FROM profiles p
  WHERE ((p.id = auth.uid()) AND (lower(p.role) = ANY (ARRAY['admin'::text, 'moderator'::text])))))));

drop policy if exists "app_update_operations_select_policy" on public."app_update_operations";
create policy "app_update_operations_select_policy" on public."app_update_operations" as PERMISSIVE for SELECT to "authenticated" using (((owner_id = auth.uid()) OR (EXISTS ( SELECT 1
   FROM profiles p
  WHERE ((p.id = auth.uid()) AND (lower(p.role) = ANY (ARRAY['admin'::text, 'moderator'::text])))))));

drop policy if exists "app_update_releases_select_policy" on public."app_update_releases";
create policy "app_update_releases_select_policy" on public."app_update_releases" as PERMISSIVE for SELECT to "authenticated" using (((owner_id = auth.uid()) OR ((campaign_id IS NOT NULL) AND (EXISTS ( SELECT 1
   FROM campaign_members cm
  WHERE ((cm.campaign_id = app_update_releases.campaign_id) AND (cm.user_id = auth.uid()))))) OR (EXISTS ( SELECT 1
   FROM profiles p
  WHERE ((p.id = auth.uid()) AND (lower(p.role) = ANY (ARRAY['admin'::text, 'moderator'::text])))))));

drop policy if exists "members_delete_own_or_owner" on public."campaign_members";
create policy "members_delete_own_or_owner" on public."campaign_members" as PERMISSIVE for DELETE to "authenticated" using (((user_id = auth.uid()) OR (EXISTS ( SELECT 1
   FROM campaigns c
  WHERE ((c.id = campaign_members.campaign_id) AND (c.owner_id = auth.uid()))))));

drop policy if exists "members_insert_own" on public."campaign_members";
create policy "members_insert_own" on public."campaign_members" as PERMISSIVE for INSERT to "authenticated" with check ((user_id = auth.uid()));

drop policy if exists "members_select_all" on public."campaign_members";
create policy "members_select_all" on public."campaign_members" as PERMISSIVE for SELECT to "authenticated" using (true);

drop policy if exists "members_select_anon" on public."campaign_members";
create policy "members_select_anon" on public."campaign_members" as PERMISSIVE for SELECT to "anon" using (true);

drop policy if exists "campaign_push_receipts_select_own" on public."campaign_push_receipts";
create policy "campaign_push_receipts_select_own" on public."campaign_push_receipts" as PERMISSIVE for SELECT to "authenticated" using ((user_id = auth.uid()));

drop policy if exists "campaigns_delete_owner_or_admin" on public."campaigns";
create policy "campaigns_delete_owner_or_admin" on public."campaigns" as PERMISSIVE for DELETE to "authenticated" using (((owner_id = auth.uid()) OR (EXISTS ( SELECT 1
   FROM profiles
  WHERE ((profiles.id = auth.uid()) AND (profiles.role = 'admin'::text))))));

drop policy if exists "campaigns_insert_own" on public."campaigns";
create policy "campaigns_insert_own" on public."campaigns" as PERMISSIVE for INSERT to "authenticated" with check (((owner_id = auth.uid()) AND (EXISTS ( SELECT 1
   FROM profiles
  WHERE ((profiles.id = auth.uid()) AND (profiles.credits > 10) AND (profiles.is_locked = false))))));

drop policy if exists "campaigns_select_anon" on public."campaigns";
create policy "campaigns_select_anon" on public."campaigns" as PERMISSIVE for SELECT to "anon" using ((status = 'open'::text));

drop policy if exists "campaigns_select_visible" on public."campaigns";
create policy "campaigns_select_visible" on public."campaigns" as PERMISSIVE for SELECT to "authenticated" using (((status = ANY (ARRAY['open'::text, 'paused'::text, 'production'::text, 'completed'::text])) OR (owner_id = auth.uid()) OR (EXISTS ( SELECT 1
   FROM profiles
  WHERE ((profiles.id = auth.uid()) AND (profiles.role = 'admin'::text))))));

drop policy if exists "campaigns_update_owner" on public."campaigns";
create policy "campaigns_update_owner" on public."campaigns" as PERMISSIVE for UPDATE to "authenticated" using ((owner_id = auth.uid())) with check ((owner_id = auth.uid()));

drop policy if exists "checkins_insert_own" on public."checkins";
create policy "checkins_insert_own" on public."checkins" as PERMISSIVE for INSERT to "authenticated" with check (((user_id = auth.uid()) AND (EXISTS ( SELECT 1
   FROM profiles
  WHERE ((profiles.id = auth.uid()) AND (profiles.is_locked = false))))));

drop policy if exists "checkins_select_all" on public."checkins";
create policy "checkins_select_all" on public."checkins" as PERMISSIVE for SELECT to "anon", "authenticated" using (true);

drop policy if exists "checkins_select_anon" on public."checkins";
create policy "checkins_select_anon" on public."checkins" as PERMISSIVE for SELECT to "anon" using (true);

drop policy if exists "contact_reports_insert_own" on public."contact_reports";
create policy "contact_reports_insert_own" on public."contact_reports" as PERMISSIVE for INSERT to "authenticated" with check (((user_id = auth.uid()) AND (status = 'new'::text) AND (admin_reply IS NULL) AND (replied_at IS NULL)));

drop policy if exists "contact_reports_select_own" on public."contact_reports";
create policy "contact_reports_select_own" on public."contact_reports" as PERMISSIVE for SELECT to "authenticated" using ((user_id = auth.uid()));

drop policy if exists "credit_logs_select_own" on public."credit_logs";
create policy "credit_logs_select_own" on public."credit_logs" as PERMISSIVE for SELECT to "authenticated" using ((user_id = auth.uid()));

drop policy if exists "feedbacks_insert_own" on public."feedbacks";
create policy "feedbacks_insert_own" on public."feedbacks" as PERMISSIVE for INSERT to "authenticated" with check ((user_id = auth.uid()));

drop policy if exists "feedbacks_select_all" on public."feedbacks";
create policy "feedbacks_select_all" on public."feedbacks" as PERMISSIVE for SELECT to "authenticated" using (true);

drop policy if exists "feedbacks_select_anon" on public."feedbacks";
create policy "feedbacks_select_anon" on public."feedbacks" as PERMISSIVE for SELECT to "anon" using (true);

drop policy if exists "feedbacks_update_own" on public."feedbacks";
create policy "feedbacks_update_own" on public."feedbacks" as PERMISSIVE for UPDATE to "authenticated" using ((user_id = auth.uid())) with check ((user_id = auth.uid()));

drop policy if exists "mission_participants_read_authenticated" on public."mission_participants";
create policy "mission_participants_read_authenticated" on public."mission_participants" as PERMISSIVE for SELECT to "authenticated" using (true);

drop policy if exists "missions_read_authenticated" on public."missions";
create policy "missions_read_authenticated" on public."missions" as PERMISSIVE for SELECT to "authenticated" using (true);

drop policy if exists "notifications_delete_own" on public."notifications";
create policy "notifications_delete_own" on public."notifications" as PERMISSIVE for DELETE to "authenticated" using ((user_id = auth.uid()));

drop policy if exists "notifications_insert_all" on public."notifications";
create policy "notifications_insert_all" on public."notifications" as PERMISSIVE for INSERT to "authenticated" with check (true);

drop policy if exists "notifications_select_own" on public."notifications";
create policy "notifications_select_own" on public."notifications" as PERMISSIVE for SELECT to "authenticated" using ((user_id = auth.uid()));

drop policy if exists "notifications_update_own" on public."notifications";
create policy "notifications_update_own" on public."notifications" as PERMISSIVE for UPDATE to "authenticated" using ((user_id = auth.uid())) with check ((user_id = auth.uid()));

drop policy if exists "profiles_insert_own" on public."profiles";
create policy "profiles_insert_own" on public."profiles" as PERMISSIVE for INSERT to "authenticated" with check ((id = auth.uid()));

drop policy if exists "profiles_select_all" on public."profiles";
create policy "profiles_select_all" on public."profiles" as PERMISSIVE for SELECT to "anon", "authenticated" using (true);

drop policy if exists "profiles_select_anon" on public."profiles";
create policy "profiles_select_anon" on public."profiles" as PERMISSIVE for SELECT to "anon" using (true);

drop policy if exists "profiles_update_own" on public."profiles";
create policy "profiles_update_own" on public."profiles" as PERMISSIVE for UPDATE to "authenticated" using ((id = auth.uid())) with check ((id = auth.uid()));

drop policy if exists "report_submission_receipts_select_policy" on public."report_submission_receipts";
create policy "report_submission_receipts_select_policy" on public."report_submission_receipts" as PERMISSIVE for SELECT to PUBLIC using ((auth.uid() = user_id));

drop policy if exists "reports_insert_tester" on public."tester_reports";
create policy "reports_insert_tester" on public."tester_reports" as PERMISSIVE for INSERT to "authenticated" with check (((user_id = auth.uid()) AND (status = 'pending'::text) AND (bonus_awarded = 0) AND (reviewed_at IS NULL) AND (EXISTS ( SELECT 1
   FROM profiles
  WHERE ((profiles.id = auth.uid()) AND (profiles.is_locked = false))))));

drop policy if exists "reports_select_own_or_owner" on public."tester_reports";
create policy "reports_select_own_or_owner" on public."tester_reports" as PERMISSIVE for SELECT to "authenticated" using (((user_id = auth.uid()) OR (EXISTS ( SELECT 1
   FROM campaigns c
  WHERE ((c.id = tester_reports.campaign_id) AND (c.owner_id = auth.uid())))) OR (EXISTS ( SELECT 1
   FROM profiles p
  WHERE ((p.id = auth.uid()) AND (p.role = 'admin'::text))))));

drop policy if exists "reports_update_owner" on public."tester_reports";
create policy "reports_update_owner" on public."tester_reports" as PERMISSIVE for UPDATE to "authenticated" using ((EXISTS ( SELECT 1
   FROM campaigns c
  WHERE ((c.id = tester_reports.campaign_id) AND (c.owner_id = auth.uid())))));

drop policy if exists "reports_update_tester" on public."tester_reports";
create policy "reports_update_tester" on public."tester_reports" as PERMISSIVE for UPDATE to "authenticated" using ((user_id = auth.uid())) with check ((user_id = auth.uid()));

drop policy if exists "topup_orders_select_own" on public."topup_orders";
create policy "topup_orders_select_own" on public."topup_orders" as PERMISSIVE for SELECT to "authenticated" using ((user_id = auth.uid()));

drop policy if exists "topup_packages_read_all" on public."topup_packages";
create policy "topup_packages_read_all" on public."topup_packages" as PERMISSIVE for SELECT to PUBLIC using ((is_active = true));

drop policy if exists "quest_claims_select_own" on public."user_quest_claims";
create policy "quest_claims_select_own" on public."user_quest_claims" as PERMISSIVE for SELECT to "authenticated" using ((user_id = auth.uid()));

drop policy if exists "user_slots_select_own" on public."user_slots";
create policy "user_slots_select_own" on public."user_slots" as PERMISSIVE for SELECT to "authenticated" using ((user_id = auth.uid()));

drop policy if exists "warnings_select_own" on public."user_warnings";
create policy "warnings_select_own" on public."user_warnings" as PERMISSIVE for SELECT to "authenticated" using ((user_id = auth.uid()));

drop policy if exists "warnings_update_own" on public."user_warnings";
create policy "warnings_update_own" on public."user_warnings" as PERMISSIVE for UPDATE to "authenticated" using ((user_id = auth.uid())) with check ((user_id = auth.uid()));

-- Triggers: cùng các định nghĩa cuối; không kích hoạt backfill dữ liệu.
drop trigger if exists "on_auth_user_created" on "auth"."users";
CREATE TRIGGER on_auth_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION handle_new_user();

drop trigger if exists "on_auth_user_created_auto_confirm" on "auth"."users";
CREATE TRIGGER on_auth_user_created_auto_confirm BEFORE INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION auto_confirm_user();

drop trigger if exists "trg_on_campaign_member_joined" on "public"."campaign_members";
CREATE TRIGGER trg_on_campaign_member_joined AFTER INSERT ON campaign_members FOR EACH ROW EXECUTE FUNCTION trg_notify_campaign_member_joined();

drop trigger if exists "trg_campaign_status_lifecycle" on "public"."campaigns";
CREATE TRIGGER trg_campaign_status_lifecycle BEFORE INSERT OR UPDATE OF status ON campaigns FOR EACH ROW EXECUTE FUNCTION trg_campaign_status_lifecycle();

drop trigger if exists "trg_campaigns_app_update_settle_delete" on "public"."campaigns";
CREATE TRIGGER trg_campaigns_app_update_settle_delete BEFORE DELETE ON campaigns FOR EACH ROW EXECUTE FUNCTION trg_fn_campaigns_app_update_settle();

drop trigger if exists "trg_campaigns_app_update_settle_update" on "public"."campaigns";
CREATE TRIGGER trg_campaigns_app_update_settle_update AFTER UPDATE OF status ON campaigns FOR EACH ROW EXECUTE FUNCTION trg_fn_campaigns_app_update_settle();

drop trigger if exists "trg_campaigns_archive_before_delete" on "public"."campaigns";
CREATE TRIGGER trg_campaigns_archive_before_delete BEFORE DELETE ON campaigns FOR EACH ROW EXECUTE FUNCTION archive_campaign_before_delete();

drop trigger if exists "trg_campaigns_guard_admin_actions" on "public"."campaigns";
CREATE TRIGGER trg_campaigns_guard_admin_actions BEFORE INSERT OR UPDATE ON campaigns FOR EACH ROW EXECUTE FUNCTION trg_campaigns_guard_admin_actions();

drop trigger if exists "trg_check_campaign_slot" on "public"."campaigns";
CREATE TRIGGER trg_check_campaign_slot BEFORE INSERT OR UPDATE ON campaigns FOR EACH ROW EXECUTE FUNCTION check_campaign_slot_validity();

drop trigger if exists "trg_on_campaign_target_cost" on "public"."campaigns";
CREATE TRIGGER trg_on_campaign_target_cost BEFORE INSERT OR UPDATE OF target_testers ON campaigns FOR EACH ROW EXECUTE FUNCTION handle_campaign_target_cost();

drop trigger if exists "trg_protect_campaign_push_metadata" on "public"."campaigns";
CREATE TRIGGER trg_protect_campaign_push_metadata BEFORE INSERT OR UPDATE ON campaigns FOR EACH ROW EXECUTE FUNCTION trg_fn_protect_campaign_push_metadata();

drop trigger if exists "on_checkin_reward_trigger" on "public"."checkins";
CREATE TRIGGER on_checkin_reward_trigger AFTER INSERT ON checkins FOR EACH ROW EXECUTE FUNCTION handle_checkin_reward();

drop trigger if exists "trg_on_credit_log_created" on "public"."credit_logs";
CREATE TRIGGER trg_on_credit_log_created AFTER INSERT ON credit_logs FOR EACH ROW EXECUTE FUNCTION trg_notify_credit_change();

drop trigger if exists "trg_audit_daily_task_policy" on "public"."daily_task_policies";
CREATE TRIGGER trg_audit_daily_task_policy AFTER INSERT OR DELETE OR UPDATE ON daily_task_policies FOR EACH ROW EXECUTE FUNCTION audit_daily_task_policy();

drop trigger if exists "trg_daily_task_policy_commit" on "public"."daily_task_policies";
CREATE CONSTRAINT TRIGGER trg_daily_task_policy_commit AFTER INSERT OR DELETE OR UPDATE ON daily_task_policies DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION guard_daily_task_policy();

drop trigger if exists "trg_guard_daily_task_policy" on "public"."daily_task_policies";
CREATE TRIGGER trg_guard_daily_task_policy BEFORE INSERT OR DELETE OR UPDATE ON daily_task_policies FOR EACH ROW EXECUTE FUNCTION guard_daily_task_policy();

drop trigger if exists "trg_no_truncate_daily_task_policies" on "public"."daily_task_policies";
CREATE TRIGGER trg_no_truncate_daily_task_policies BEFORE TRUNCATE ON daily_task_policies FOR EACH STATEMENT EXECUTE FUNCTION reject_daily_task_policy_history_change();

drop trigger if exists "trg_no_change_daily_task_policy_history" on "public"."daily_task_policy_changes";
CREATE TRIGGER trg_no_change_daily_task_policy_history BEFORE DELETE OR UPDATE ON daily_task_policy_changes FOR EACH ROW EXECUTE FUNCTION reject_daily_task_policy_history_change();

drop trigger if exists "trg_no_truncate_daily_task_policy_history" on "public"."daily_task_policy_changes";
CREATE TRIGGER trg_no_truncate_daily_task_policy_history BEFORE TRUNCATE ON daily_task_policy_changes FOR EACH STATEMENT EXECUTE FUNCTION reject_daily_task_policy_history_change();

drop trigger if exists "trg_home_stats_policy_immutability" on "public"."home_stats_policies";
CREATE TRIGGER trg_home_stats_policy_immutability BEFORE UPDATE ON home_stats_policies FOR EACH ROW EXECUTE FUNCTION _check_home_stats_policy_immutability();

drop trigger if exists "trg_on_profile_lock_changed" on "public"."profiles";
CREATE TRIGGER trg_on_profile_lock_changed AFTER UPDATE ON profiles FOR EACH ROW WHEN (old.is_locked IS DISTINCT FROM new.is_locked) EXECUTE FUNCTION trg_notify_profile_lock_status();

drop trigger if exists "trg_on_tester_report_event" on "public"."tester_reports";
CREATE TRIGGER trg_on_tester_report_event AFTER INSERT OR UPDATE ON tester_reports FOR EACH ROW EXECUTE FUNCTION trg_notify_tester_report();

drop trigger if exists "trg_on_tester_report_submitted" on "public"."tester_reports";
CREATE TRIGGER trg_on_tester_report_submitted AFTER INSERT ON tester_reports FOR EACH ROW EXECUTE FUNCTION handle_tester_report_submitted();

drop trigger if exists "trg_protect_tester_reports_mission_metadata" on "public"."tester_reports";
CREATE TRIGGER trg_protect_tester_reports_mission_metadata BEFORE INSERT OR UPDATE ON tester_reports FOR EACH ROW EXECUTE FUNCTION trig_protect_tester_reports_mission_metadata();

drop trigger if exists "trg_reports_require_open" on "public"."tester_reports";
CREATE TRIGGER trg_reports_require_open BEFORE INSERT ON tester_reports FOR EACH ROW EXECUTE FUNCTION trg_reports_require_open_campaign();

drop trigger if exists "trg_tester_reports_reset_rejection" on "public"."tester_reports";
CREATE TRIGGER trg_tester_reports_reset_rejection BEFORE UPDATE ON tester_reports FOR EACH ROW EXECUTE FUNCTION trg_reset_tester_report_rejection();

drop trigger if exists "trg_on_user_warning_created" on "public"."user_warnings";
CREATE TRIGGER trg_on_user_warning_created AFTER INSERT ON user_warnings FOR EACH ROW EXECUTE FUNCTION trg_notify_user_warning();

