        grant EXECUTE on function public."verify_media_access_grant_internal"(uuid, uuid, text, text, bigint) to "service_role";
    end if;
end;
$fresh_acl$;

-- Quyền riêng của 046 cho các hàm Media Gateway vừa bổ sung.
revoke all on function public.get_media_gateway_secret() from public, anon, authenticated;
grant execute on function public.get_media_gateway_secret() to service_role;
revoke execute on function public.get_report_media_access(uuid) from public, anon;
grant execute on function public.get_report_media_access(uuid) to authenticated, service_role;
grant execute on function public.verify_media_access_grant(uuid,text,text,bigint) to authenticated, service_role;
revoke execute on function public.verify_media_access_grant_internal(uuid,uuid,text,text,bigint) from public, anon, authenticated;
grant execute on function public.verify_media_access_grant_internal(uuid,uuid,text,text,bigint) to service_role;

-- Mô tả schema.
comment on table public."app_update_releases" is 'Các đợt công bố phiên bản cập nhật kèm quỹ thưởng 120 Credit (20 suất x 6 Credit)';
comment on table public."campaign_archive" is 'Thống kê campaign được chụp trước khi xóa. Không có FK tới campaigns/profiles để tồn tại sau khi dữ liệu gốc bị xóa.';
comment on table public."campaign_push_receipts" is 'Biên lai giao dịch mua lượt Đẩy app (100 Credit/lượt, hiệu lực đến 00:00 hôm sau VN)';
comment on table public."cleanup_runs" is 'Log các lần chạy job dọn dẹp dữ liệu (purge, retention...). Không chứa PII.';
comment on column public."campaign_archive"."completed_at" is 'completed_at gốc; nếu null (dữ liệu cũ) thì dùng created_at tại thời điểm archive.';
comment on column public."campaign_archive"."completed_tester_count" is 'Số tester có số checkin >= campaigns.target_days tại thời điểm archive.';
comment on column public."campaign_archive"."archived_reason" is 'retention | unknown | ... (lấy từ app.delete_reason nếu có).';
comment on column public."campaigns"."admin_note" is 'Lý do Admin tạm dừng app; hiển thị cho chủ app. Bị xóa khi app mở lại.';
comment on column public."campaigns"."admin_resumed" is 'True khi Admin mở lại app vốn bị auto-pause vì chủ vắng; cron bỏ qua auto-pause.';
comment on column public."profiles"."last_login_date" is 'Ngày đăng nhập gần nhất theo Asia/Ho_Chi_Minh.';
comment on column public."profiles"."daily_missed_streak" is 'Số ngày liên tiếp không hoàn thành nhiệm vụ ngày. Không dùng missed_streak legacy.';
comment on column public."tester_reports"."client_submit_id" is 'Idempotency key do client sinh ra cho một lần nộp; retry dùng lại cùng id.';
comment on column public."user_daily_tasks"."policy_id" is 'Policy used at finalization; NULL for legacy / unfinalized rows. No historical backfill.';
comment on column public."user_daily_tasks"."tests_per_active_app" is 'Ratio used at finalization. Legacy rows remain unchanged.';
comment on column public."user_daily_tasks"."carryover_version" is 'Phiên bản công thức cộng dồn (1 cho chính sách mới; NULL cho dòng lịch sử)';
comment on column public."user_daily_tasks"."base_required_tests" is 'Chỉ tiêu cơ bản B của ngày đang chấm (tỷ lệ * số active app)';
comment on column public."user_daily_tasks"."carry_in_tests" is 'Số app còn thiếu chuyển vào từ ngày trước (C)';
comment on column public."user_daily_tasks"."carry_out_tests" is 'Số app còn thiếu chuyển sang ngày sau sau khi chốt (carry_out)';
comment on column public."user_daily_tasks"."carry_source_date" is 'Ngày liền trước dùng làm nguồn chuyển tiếp; giúp phát hiện khoảng trống';
comment on column public."user_daily_tasks"."carryover_effective_from" is 'Ngày bắt đầu có hiệu lực của chính sách cộng dồn';
comment on function public."archive_campaign_before_delete"() is 'Trigger BEFORE DELETE trên campaigns: chụp thống kê vào campaign_archive trước khi cascade xóa dữ liệu con.';
comment on function public."purge_completed_campaigns"(integer, boolean, integer) is 'Xóa campaign completed/production đã quá retention_days. Trả về số campaign đã xóa; dry_run trả về số sẽ xóa; -1 nếu lỗi toàn cục.';
comment on function public."sync_expired_missions"() is 'Helper backend: tự động chuyển các mission open/full/paused_by_creator đã quá ends_at sang expired. Chỉ cấp quyền service_role/cron.';

-- Cron: giữ nguyên job đang dùng; chỉ tạo lịch mặc định trên database mới nếu có pg_cron.
do $jobs$
begin
    if current_setting('crosstest.baseline_062_existing')='false'
       and exists(select 1 from pg_extension where extname='pg_cron') then
        perform cron.schedule('campaign_lifecycle_sync_job','11 * * * *','select public.sync_campaign_lifecycle();');
        perform cron.schedule('auto_accept_reports_job','*/30 * * * *','select public.auto_accept_expired_reports();');
        perform cron.schedule('daily_inactivity_penalty_job','5 17 * * *','select public.apply_daily_inactivity_penalty();');
        perform cron.schedule('sync_expired_missions_job','0 * * * *','select public.sync_expired_missions();');
        perform cron.schedule('purge_completed_campaigns_job','15 3 * * *','select public.purge_completed_campaigns(90, false, 100);');
    end if;
end;
$jobs$;

$baseline_payload$;
    insert into crosstest_migrations.baselines(version,source_sha256,existing_database)
    values ('062','ec320587f9dde87bbea8d22d80026a1ede7e52300bfb9372dabec48fdae2a517',v_existing);
    raise notice 'Baseline 062 thanh cong. Migration tiep theo: 063. Du lieu hien co duoc giu nguyen.';
end;
$baseline$;

notify pgrst,'reload schema';
commit;

-- Kết quả: phải có đúng một dòng version=062. Đây không phải lệnh sửa dữ liệu.
select version,applied_at,existing_database from crosstest_migrations.baselines where version='062';
